__reload_all = true
local System = require("System.System")
local readonly = System.readonly
local Text_AvgVideoCaption = readonly({
  AvgVideoCaption_100284_Content_1 = {
    Text = "Palet, Kâğıt, Boya"
  },
  AvgVideoCaption_100284_Content_10 = {
    Text = "Doğal değil. Tüylerimi diken diken ediyor."
  },
  AvgVideoCaption_100284_Content_100 = {
    Text = "Delilik. Açlık."
  },
  AvgVideoCaption_100284_Content_101 = {
    Text = "Bunlar varoluşumuzun temel hakikatleridir."
  },
  AvgVideoCaption_100284_Content_102 = {
    Text = "Tüm sanat, o güzel ve korkunç hakikate yaklaşmak için yalnızca bir yoldur."
  },
  AvgVideoCaption_100284_Content_103 = {
    Text = "Öyle değil mi, Bay Matthew?"
  },
  AvgVideoCaption_100284_Content_11 = {
    Text = "Gerçekten mi?! Teşekkür ederim!"
  },
  AvgVideoCaption_100284_Content_12 = {
    Text = "Birinin eserimi takdir etmesinin üzerinden o kadar uzun zaman geçti ki..."
  },
  AvgVideoCaption_100284_Content_13 = {
    Text = "Sizin... benzersiz sanatsal görüşünüz, Bay Pickman."
  },
  AvgVideoCaption_100284_Content_14 = {
    Text = "Bu bir ucube. Saygın hiçbir galeride yeri yok."
  },
  AvgVideoCaption_100284_Content_15 = {
    Text = "Lütfen, sadece çabuk olun."
  },
  AvgVideoCaption_100284_Content_16 = {
    Text = "Şu sıkıcı, küçük sembolizm oyununu bitir de gidebileyim."
  },
  AvgVideoCaption_100284_Content_17 = {
    Text = "Sembolizm mi?"
  },
  AvgVideoCaption_100284_Content_18 = {
    Text = "Yanılıyorsunuz, Bay Matthew."
  },
  AvgVideoCaption_100284_Content_19 = {
    Text = "Sembolizme karşı değilim."
  },
  AvgVideoCaption_100284_Content_2 = {
    Text = "Tuhaf, fırçam nerede...?"
  },
  AvgVideoCaption_100284_Content_20 = {
    Text = "Ama ben bir gerçekçiyim. Hakiki sureti resmederim."
  },
  AvgVideoCaption_100284_Content_21 = {
    Text = "Tanrı aşkına, sanat kuramının sadelerini bile bilmiyorsun."
  },
  AvgVideoCaption_100284_Content_22 = {
    Text = "Sizin yaptığınız gerçekçilik değil, o..."
  },
  AvgVideoCaption_100284_Content_23 = {
    Text = "Bekle. Az önce... köşedeki tuval kıpırdadı mı?"
  },
  AvgVideoCaption_100284_Content_24 = {
    Text = "Kımıldamayın, Bay Matthew."
  },
  AvgVideoCaption_100284_Content_25 = {
    Text = "O pozu koru! Ne kadar rahattı, ne kadar doğaldı."
  },
  AvgVideoCaption_100284_Content_26 = {
    Text = "Özünüzü yakalıyorum."
  },
  AvgVideoCaption_100284_Content_27 = {
    Text = "Evet... pençelerinizin yere açısı..."
  },
  AvgVideoCaption_100284_Content_28 = {
    Text = "Muhteşem bir gerilim hattı."
  },
  AvgVideoCaption_100284_Content_29 = {
    Text = "Benim... pençem mi?"
  },
  AvgVideoCaption_100284_Content_3 = {
    Text = "Ah! İşte buradasın!"
  },
  AvgVideoCaption_100284_Content_30 = {
    Text = "Bay Pickman, ben... iyi hissetmiyorum."
  },
  AvgVideoCaption_100284_Content_31 = {
    Text = "Büyük sanat zaman ister, Bay Matthew."
  },
  AvgVideoCaption_100284_Content_32 = {
    Text = "Çizgiler... evet, nasıl kıvrılıp özlemle gerildiğine bakın!"
  },
  AvgVideoCaption_100284_Content_33 = {
    Text = "Ve yüzünüzdeki dehşet! Eseri tamamlayan o!"
  },
  AvgVideoCaption_100284_Content_34 = {
    Text = "Hayır, buradan çıkmalıyım..."
  },
  AvgVideoCaption_100284_Content_35 = {
    Text = "Bana ne yaptınız?!"
  },
  AvgVideoCaption_100284_Content_36 = {
    Text = "Ben mi? Hayır, Bay Matthew."
  },
  AvgVideoCaption_100284_Content_37 = {
    Text = "Ben hiçbir şey yapmadım."
  },
  AvgVideoCaption_100284_Content_38 = {
    Text = "Ben değilim. Gitmek istemeyen bedeniniz."
  },
  AvgVideoCaption_100284_Content_39 = {
    Text = "Görmek ister misin? Gerçekten, ne yaptığımızı görmek?"
  },
  AvgVideoCaption_100284_Content_4 = {
    Text = "Evet Bay Matthew, onu öyle tutun."
  },
  AvgVideoCaption_100284_Content_40 = {Text = "N-Ne?"},
  AvgVideoCaption_100284_Content_41 = {
    Text = "Bedenime ne oluyor?!"
  },
  AvgVideoCaption_100284_Content_42 = {
    Text = "Ah, sana bak! O güzelim köpekdişleri! O zarif yarasa kanatları!"
  },
  AvgVideoCaption_100284_Content_43 = {
    Text = "Sanata dönüşüyorsunuz!"
  },
  AvgVideoCaption_100284_Content_44 = {
    Text = "Hayır... Bunu durdur!"
  },
  AvgVideoCaption_100284_Content_45 = {
    Text = "Acıtıyor, değil mi?"
  },
  AvgVideoCaption_100284_Content_46 = {
    Text = "Şşş, şşş, geçecek Bay Matthew."
  },
  AvgVideoCaption_100284_Content_47 = {
    Text = "İlk değişim her zaman en kötüsüdür."
  },
  AvgVideoCaption_100284_Content_48 = {
    Text = "Acıyı hatırlıyorum. Yırtılışı."
  },
  AvgVideoCaption_100284_Content_49 = {
    Text = "Ne mükemmel, ne canlı bir kızıl üretiyorsun."
  },
  AvgVideoCaption_100284_Content_5 = {
    Text = "Gördünüz mü? Kompozisyon kusursuz."
  },
  AvgVideoCaption_100284_Content_50 = {
    Text = "Bana bir keresinde acının sanatı beslediğini söylemiştin."
  },
  AvgVideoCaption_100284_Content_51 = {
    Text = "Hele de sen, bunu herkesten iyi anlarsın."
  },
  AvgVideoCaption_100284_Content_52 = {
    Text = "Biraz daha dayan"
  },
  AvgVideoCaption_100284_Content_53 = {
    Text = "Başyapıt neredeyse tamamlandı...!"
  },
  AvgVideoCaption_100284_Content_54 = {
    Text = "Nerede... neredeyiz biz?!"
  },
  AvgVideoCaption_100284_Content_55 = {
    Text = "Nihai hakikatin galerisi! Gem vurulmamış formun katedrali!"
  },
  AvgVideoCaption_100284_Content_56 = {
    Text = "Hoş Geldin, Bay Matthew, Gulyabani Şehri Necrovia’nın kalbine!"
  },
  AvgVideoCaption_100284_Content_57 = {
    Text = "Ghoul Şehri..."
  },
  AvgVideoCaption_100284_Content_58 = {
    Text = "Bak! Sanatımın hamileri, ziyafet çekiyorlar!"
  },
  AvgVideoCaption_100284_Content_59 = {
    Text = "Dans eden partnerlerini nasıl da keyifle tükettiklerine bak!"
  },
  AvgVideoCaption_100284_Content_6 = {
    Text = "Başlayalım!"
  },
  AvgVideoCaption_100284_Content_60 = {
    Text = "Bu görkemli, kıvranan bakhanal sahnemiz olacak!"
  },
  AvgVideoCaption_100284_Content_61 = {
    Text = "Yeter artık... Pickman... Dayanamıyorum..."
  },
  AvgVideoCaption_100284_Content_62 = {
    Text = "Ama sen her zaman Gerçek Sanat’ı kavramaya çalıştın."
  },
  AvgVideoCaption_100284_Content_63 = {
    Text = "Senin asil avını bozmaya cüret edemem."
  },
  AvgVideoCaption_100284_Content_64 = {
    Text = "İlk kez buraya geldiğimde,"
  },
  AvgVideoCaption_100284_Content_65 = {
    Text = "Onların görkemli, kadim geleneklerine Hoş Geldin edildim."
  },
  AvgVideoCaption_100284_Content_66 = {
    Text = "Gelin, Bay Matthew!"
  },
  AvgVideoCaption_100284_Content_67 = {
    Text = "Bu sanatçının ziyafetini tatmalısınız!"
  },
  AvgVideoCaption_100284_Content_68 = {
    Text = "O da ne... o şey..."
  },
  AvgVideoCaption_100284_Content_69 = {
    Text = "Şu çürümüş, pis kokan tepsiyi benden uzak tut!"
  },
  AvgVideoCaption_100284_Content_7 = {
    Text = "Tanrım, bundan pişmanım..."
  },
  AvgVideoCaption_100284_Content_70 = {
    Text = "Emin misin, biraz istemiyor musun?"
  },
  AvgVideoCaption_100284_Content_71 = {
    Text = "Ben... Ben..."
  },
  AvgVideoCaption_100284_Content_72 = {
    Text = "İSTİYORSUN! Açlığını hissediyorum!"
  },
  AvgVideoCaption_100284_Content_73 = {
    Text = "İçine işlemiş derin ısırma ihtiyacını!"
  },
  AvgVideoCaption_100284_Content_74 = {
    Text = "Bu, ghoul dürtüsü!"
  },
  AvgVideoCaption_100284_Content_75 = {
    Text = "İnsanın zayıf kabuğunu kazıyıp atan görkemli bir fırtına,"
  },
  AvgVideoCaption_100284_Content_76 = {
    Text = "seni ilkel, açlıktan kıvranan özgürlüğün bir durumuna geri döndürüyor!"
  },
  AvgVideoCaption_100284_Content_77 = {
    Text = "Bırak beni! Çıkmalıyım buradan! Sal beni!"
  },
  AvgVideoCaption_100284_Content_78 = {
    Text = "Teslim ol ona, Bay Matthew."
  },
  AvgVideoCaption_100284_Content_79 = {
    Text = "Izdırap, vecd, hafıza, açlık, özlem, leziz bir bozulma..."
  },
  AvgVideoCaption_100284_Content_8 = {
    Text = "Bana ödediğin üç kuruş buna değmez."
  },
  AvgVideoCaption_100284_Content_80 = {
    Text = "Ne aşkın bir ifade! Kusursuz bir poz!"
  },
  AvgVideoCaption_100284_Content_81 = {
    Text = "Şimdi, son fırça darbesi için..."
  },
  AvgVideoCaption_100284_Content_82 = {
    Text = "Hayır... lütfen..."
  },
  AvgVideoCaption_100284_Content_83 = {
    Text = "Ona ihtiyacım var... ver onu bana... Ceset... yiyecek!"
  },
  AvgVideoCaption_100284_Content_84 = {
    Text = "Et... o... Hayır! Nereye gitti?"
  },
  AvgVideoCaption_100284_Content_85 = {
    Text = "Ah, üzgünüm Bay Matthew."
  },
  AvgVideoCaption_100284_Content_86 = {
    Text = "Resimlerim... bir bakıma şeyleri içeri çeker."
  },
  AvgVideoCaption_100284_Content_87 = {
    Text = "Pek bir şey yapamıyorum."
  },
  AvgVideoCaption_100284_Content_88 = {
    Text = "Bu... bir düş müydü?"
  },
  AvgVideoCaption_100284_Content_89 = {
    Text = "Tamım. Ben... hâlâ ben miyim?"
  },
  AvgVideoCaption_100284_Content_9 = {
    Text = "Bu tablolar... şu iğrenç, sırıtan gulyabaniler."
  },
  AvgVideoCaption_100284_Content_90 = {
    Text = "Elbette! Modellerimi severim! Sana zarar vermem."
  },
  AvgVideoCaption_100284_Content_91 = {
    Text = "Görüş alanı... rahatsız edici olmuş olabilir."
  },
  AvgVideoCaption_100284_Content_92 = {
    Text = "Ama gerekliydi."
  },
  AvgVideoCaption_100284_Content_93 = {
    Text = "Bakın, Bay Matthew!"
  },
  AvgVideoCaption_100284_Content_94 = {
    Text = "Yaptığımız tabloya bak!"
  },
  AvgVideoCaption_100284_Content_95 = {
    Text = "Bu... sefil bir şey... yarım kalmış bir gulyabani..."
  },
  AvgVideoCaption_100284_Content_96 = {
    Text = "Necrovia'da çığlık atıyor..."
  },
  AvgVideoCaption_100284_Content_97 = {
    Text = "Ne kadar umutsuz... ne kadar... aç..."
  },
  AvgVideoCaption_100284_Content_98 = {
    Text = "Ne kadar derinlemesine verimli bir gün!"
  },
  AvgVideoCaption_100284_Content_99 = {
    Text = "Bir arkadaş buldum. Sen gerçek sanatı gördün."
  },
  AvgVideoCaption_117618_Content_1 = {
    Text = "Fleeing without permission, resisting arrest, killing Light Guards—\nİzinsiz kaçış, tutuklamaya direnme, Fener Muhafızları’nı öldürme—"
  },
  AvgVideoCaption_117618_Content_10 = {
    Text = "Pollux sadece dış dünyayı görmek istemişti!"
  },
  AvgVideoCaption_117618_Content_100 = {
    Text = "Burada ne kadar çok kelime var... Bunların hepsini ben mi yazdım?"
  },
  AvgVideoCaption_117618_Content_101 = {
    Text = "Bu da ne...?"
  },
  AvgVideoCaption_117618_Content_102 = {
    Text = "Ve... Castor... kim...?"
  },
  AvgVideoCaption_117618_Content_103 = {
    Text = "Artık bu kelimelere bile odaklanamıyorum..."
  },
  AvgVideoCaption_117618_Content_104 = {
    Text = "Çok üzgünüm. Neden aniden ağlamak istiyorum..."
  },
  AvgVideoCaption_117618_Content_105 = {
    Text = "Pekâlâ, Pollux."
  },
  AvgVideoCaption_117618_Content_106 = {
    Text = "Bugün, Işık Taşıyıcı'nın kutsal fiillerini benimle içtenlikle okuyacaksın,"
  },
  AvgVideoCaption_117618_Content_107 = {
    Text = "ve O'nun ışığını ve merhametini derinden idrak edeceksin."
  },
  AvgVideoCaption_117618_Content_108 = {
    Text = "Evet, Leydi Fener."
  },
  AvgVideoCaption_117618_Content_109 = {
    Text = "\"Ruhu Masum Saf Diyar'a dönmüştür,\""
  },
  AvgVideoCaption_117618_Content_11 = {
    Text = "Dönüşüm ayini ona öylesine büyük Pain yaşattı ki..."
  },
  AvgVideoCaption_117618_Content_110 = {
    Text = "\"ama Bakışı hâlâ bu dünyayı sevgiyle gözetler.\""
  },
  AvgVideoCaption_117618_Content_111 = {
    Text = "\"Ruhu Masum Saf Diyar'a dönmüştür,\""
  },
  AvgVideoCaption_117618_Content_112 = {
    Text = "\"ama Bakışı hâlâ bu dünyayı sevgiyle gözetler.\""
  },
  AvgVideoCaption_117618_Content_113 = {
    Text = "\"Kendi kanını, etini ve kemiğini dünyaya sunar,\""
  },
  AvgVideoCaption_117618_Content_114 = {
    Text = "\"masum ruhları Saf Diyar'a kılavuzluk etmek için bekler,\""
  },
  AvgVideoCaption_117618_Content_115 = {
    Text = "\"…Onunla birlikte Cennetin Saf Krallığını paylaşmak.\""
  },
  AvgVideoCaption_117618_Content_116 = {
    Text = "\"Kendi kanını, etini ve kemiğini dünyaya sunar,\""
  },
  AvgVideoCaption_117618_Content_117 = {
    Text = "\"masum ruhları Saf Diyar'a kılavuzluk etmek için bekler,\""
  },
  AvgVideoCaption_117618_Content_118 = {
    Text = "\"…Onunla birlikte Cennetin Saf Krallığını paylaşmak.\""
  },
  AvgVideoCaption_117618_Content_119 = {Text = "Öhö..."},
  AvgVideoCaption_117618_Content_12 = {
    Text = "Başını eğme, kardeşim."
  },
  AvgVideoCaption_117618_Content_120 = {
    Text = "Hey, günahkâr. Erzak vaktin geldi."
  },
  AvgVideoCaption_117618_Content_121 = {
    Text = "Lütfen, sorabilir miyim... Divus Pollux bugün nasıldır...?"
  },
  AvgVideoCaption_117618_Content_122 = {
    Text = "Elbette, Hazretleri iyi. Bugün Leydi Fener'in gözetiminde gayretle talim yapıyor."
  },
  AvgVideoCaption_117618_Content_123 = {
    Text = "Ama bu seni neden ilgilendirsin ki?"
  },
  AvgVideoCaption_117618_Content_124 = {
    Text = "Bunu her gün soruyorsun, oysa sen sadece bir..."
  },
  AvgVideoCaption_117618_Content_125 = {
    Text = "Şey... Sen kimsin, yine?"
  },
  AvgVideoCaption_117618_Content_126 = {
    Text = "Boş ver. Günah Havuzu'nda olan herkes muhakkak bir günahkârdır."
  },
  AvgVideoCaption_117618_Content_127 = {
    Text = "Gelecekte Divus hakkında soru sormayı bırakmalısın."
  },
  AvgVideoCaption_117618_Content_128 = {
    Text = "O... neden artık beni hatırlayamıyorlar?"
  },
  AvgVideoCaption_117618_Content_129 = {
    Text = "Leydi Fener onları yeni Fitillerle mi değiştirdi...?"
  },
  AvgVideoCaption_117618_Content_13 = {
    Text = "Bendim! Fener Muhafızları'na ben saldırdım!"
  },
  AvgVideoCaption_117618_Content_130 = {
    Text = "Pollux... beni bekle..."
  },
  AvgVideoCaption_117618_Content_131 = {
    Text = "Ne kadar sürerse sürsün, tahammül edeceğim. Nihayet kavuşacağımız günü bekleyeceğim..."
  },
  AvgVideoCaption_117618_Content_14 = {
    Text = "Eğer bir cezalandırma olacaksa, o hâlde beni cezalandırın! Hayır... Hayır!"
  },
  AvgVideoCaption_117618_Content_15 = {
    Text = "Özgürlük için... Vazgeçme."
  },
  AvgVideoCaption_117618_Content_16 = {Text = "Ah—"},
  AvgVideoCaption_117618_Content_17 = {
    Text = "AAARGH—! Pollux! Öhö..."
  },
  AvgVideoCaption_117618_Content_18 = {
    Text = "Ah, neredeyse unutuyordum, Divus’umuz Castor zaten epey... hasar görmüş durumda."
  },
  AvgVideoCaption_117618_Content_19 = {
    Text = "Onu İyileştirme mi? Gerek yok. Castor’u Günah Havuzu’na atın."
  },
  AvgVideoCaption_117618_Content_2 = {
    Text = "Bu mu Kilise’ye sunduğumuz Divus’umuzun minnettarlığı?"
  },
  AvgVideoCaption_117618_Content_20 = {
    Text = "Kutsal kan, günahlarını yıkayıp götürecek."
  },
  AvgVideoCaption_117618_Content_21 = {
    Text = "Ancak pislik akıp gittikten sonra ayrılabilir."
  },
  AvgVideoCaption_117618_Content_22 = {
    Text = "Kar... deşim..."
  },
  AvgVideoCaption_117618_Content_23 = {
    Text = "Pekâlâ. Sırada, geriye kalan Divus’umuzun"
  },
  AvgVideoCaption_117618_Content_24 = {
    Text = "Işık Taşıyıcı’nın öğretilerini kapsamlı biçimde gözden geçirme vakti geldi."
  },
  AvgVideoCaption_117618_Content_25 = {
    Text = "Bugünden itibaren, kutsal sözleri kavraman için sana bizzat ben ders vereceğim."
  },
  AvgVideoCaption_117618_Content_26 = {Text = "..."},
  AvgVideoCaption_117618_Content_27 = {
    Text = "Aslında seni bütünüyle anlıyorum ve Ruh’unu takdir ediyorum."
  },
  AvgVideoCaption_117618_Content_28 = {
    Text = "Pollux, sen gerçekten bilge ve iyi bir çocuksun."
  },
  AvgVideoCaption_117618_Content_29 = {
    Text = "Görünüşe göre bu kıymetli bilgelik doğru biçimde uygulanmamış,"
  },
  AvgVideoCaption_117618_Content_3 = {
    Text = "Söyle bana hemen: Kimin planıydı bu?"
  },
  AvgVideoCaption_117618_Content_30 = {
    Text = "ve seni gerçek görevin olan Işık Taşıyıcı’ya hizmetten uzaklaştırmış."
  },
  AvgVideoCaption_117618_Content_31 = {
    Text = "Şu Dönüşüm Ayinleri sana fazlasıyla Pain çektirdi, öyle değil mi?"
  },
  AvgVideoCaption_117618_Content_32 = {
    Text = "Oysa Işık Taşıyıcı’nın Kendisi, ışığı ekmek için ölçülemez Pain’e tahammül etti,"
  },
  AvgVideoCaption_117618_Content_33 = {
    Text = "hatta insanlığın günahlarını arıtmak için kendi etini feda etti."
  },
  AvgVideoCaption_117618_Content_34 = {
    Text = "Onun merhametini ya da gereken o yüce Adanmışlık’ı henüz kavrayamıyorsun, bu da son derece doğal."
  },
  AvgVideoCaption_117618_Content_35 = {
    Text = "Ölümlüler Tanrı’nın eylemlerini kavramaya çalıştıklarında çoğu zaman şaşkın ve güçsüz kalırlar."
  },
  AvgVideoCaption_117618_Content_36 = {
    Text = "Gereken tek şey daha fazla öğrenmek ve daha derin bir Kavrayış..."
  },
  AvgVideoCaption_117618_Content_37 = {
    Text = "Ne yazık ki. Dahası, Castor hâlâ ağır yaralı ve Kritik Durumda."
  },
  AvgVideoCaption_117618_Content_38 = {
    Text = "Kardeşinin günahını olabildiğince çabuk Arındırmak için,"
  },
  AvgVideoCaption_117618_Content_39 = {
    Text = "derhâl Divus’un tüm sorumluluklarını yeniden üstlenmelisin."
  },
  AvgVideoCaption_117618_Content_4 = {Text = "Evet..."},
  AvgVideoCaption_117618_Content_40 = {
    Text = "...Özür dilerim, Hanımefendi Fener. Öğreneceğim."
  },
  AvgVideoCaption_117618_Content_41 = {
    Text = "Pekâlâ. Öyleyse benimle gel ve Işık Taşıyıcı’nın kutsal eylemlerini içtenlikle tekrar et,"
  },
  AvgVideoCaption_117618_Content_42 = {
    Text = "ve O’nun bahşettiği öğretiler üzerine derin derin tefekkür et."
  },
  AvgVideoCaption_117618_Content_43 = {
    Text = "...Evet, Hanımefendi Fener."
  },
  AvgVideoCaption_117618_Content_44 = {
    Text = "\"Karanlık Toprak üzerinde yürürken, ebedî bir mum taşır.\""
  },
  AvgVideoCaption_117618_Content_45 = {
    Text = "\"Karanlık Toprak üzerinde yürürken, ebedî bir mum taşır.\""
  },
  AvgVideoCaption_117618_Content_46 = {
    Text = "\"Günah denizine baktı, Ağıt gözyaşları döktü,\""
  },
  AvgVideoCaption_117618_Content_47 = {
    Text = "\"ve böylece kendi etini yardı, siyah Kanını akıttı...\""
  },
  AvgVideoCaption_117618_Content_48 = {
    Text = "\"Günah denizine baktı, Ağıt gözyaşları döktü,\""
  },
  AvgVideoCaption_117618_Content_49 = {
    Text = "\"ve böylece kendi etini yardı, siyah Kanını akıttı...\""
  },
  AvgVideoCaption_117618_Content_5 = {
    Text = "Ben... Bendim."
  },
  AvgVideoCaption_117618_Content_50 = {
    Text = "Ah! Abi! Neden kolunu yardın?!"
  },
  AvgVideoCaption_117618_Content_51 = {
    Text = "Tamamen benim suçum; Ayin’de senin yerini alamam."
  },
  AvgVideoCaption_117618_Content_52 = {
    Text = "Ama en azından acını seninle paylaşmama izin ver..."
  },
  AvgVideoCaption_117618_Content_53 = {Text = "Abi!"},
  AvgVideoCaption_117618_Content_54 = {
    Text = "Ugh... kahretsin, başım çatlıyor."
  },
  AvgVideoCaption_117618_Content_55 = {
    Text = "O kadın... Kesinlikle bana bir şey yaptı."
  },
  AvgVideoCaption_117618_Content_56 = {
    Text = "Ağabeyimin yüzü neden gözümün önünde gitgide daha da bulanıklaşıyor...?"
  },
  AvgVideoCaption_117618_Content_57 = {
    Text = "Bunu mutlaka yazmalıyım! Hayır, kâğıda değil—onu bulurlar..."
  },
  AvgVideoCaption_117618_Content_58 = {
    Text = "Bunu yazmalıyım! Hayır, kazıyacağım—gizli bir yere kazıyacağım..."
  },
  AvgVideoCaption_117618_Content_59 = {
    Text = "yatağın altına! Buraya bakmayı akıllarından bile geçirmezler..."
  },
  AvgVideoCaption_117618_Content_6 = {
    Text = "Elbette Castor kadar kalın kafalı birinin bunu tasarlamış olamayacağını biliyorsundur."
  },
  AvgVideoCaption_117618_Content_60 = {
    Text = "Doğuşumuzdan beri her Hafızayı, tüm Kaçış Planlarını ve keşfettiğimiz o küçücük yolları kazıyacağım!"
  },
  AvgVideoCaption_117618_Content_61 = {
    Text = "İradimi söküp almak mı istiyorlar? Başaramayacaklar!"
  },
  AvgVideoCaption_117618_Content_62 = {
    Text = "Beni bekle, kardeşim. Seninle birlikte yeniden kaçmak için bir fırsat bulacağım..."
  },
  AvgVideoCaption_117618_Content_63 = {
    Text = "Bugün de Işık Taşıyıcı’nın kutsal eylemlerini tekrar etmeye devam ediyoruz."
  },
  AvgVideoCaption_117618_Content_64 = {
    Text = "...Evet, Hanımefendi Fener."
  },
  AvgVideoCaption_117618_Content_65 = {
    Text = "\"Onun Kanı günahı alır, her ruhu özgür kılar.\""
  },
  AvgVideoCaption_117618_Content_66 = {
    Text = "\"Onun Kanı günahı alır, her ruhu özgür kılar.\""
  },
  AvgVideoCaption_117618_Content_67 = {
    Text = "\"Ama dünya hâlâ sonsuz Karanlık’a bürünmüş durumda,\""
  },
  AvgVideoCaption_117618_Content_68 = {
    Text = "\"bu yüzden kendi Bedenini o kutsal alevle tutuşturdu...\""
  },
  AvgVideoCaption_117618_Content_69 = {
    Text = "\"Ama dünya hâlâ sonsuz Karanlık’a bürünmüş durumda,\""
  },
  AvgVideoCaption_117618_Content_7 = {
    Text = "Ah, göğe hasret iki küçük kuşun gerçekten dokunaklı bir hikâyesi."
  },
  AvgVideoCaption_117618_Content_70 = {
    Text = "\"bu yüzden kendi Bedenini o kutsal alevle tutuşturdu...\""
  },
  AvgVideoCaption_117618_Content_71 = {
    Text = "Mum mu? Onu nerede buldun?"
  },
  AvgVideoCaption_117618_Content_72 = {
    Text = "Hah! Elbette, en kurnaz olan benim!"
  },
  AvgVideoCaption_117618_Content_73 = {
    Text = "Gece olunca bu el yazması kitaba gizlice bir Gözetleme yapabiliriz."
  },
  AvgVideoCaption_117618_Content_74 = {
    Text = "Yakalanmamak için saklanmalıyız..."
  },
  AvgVideoCaption_117618_Content_75 = {
    Text = "Hah... Acele etmeliyim. Oymaya devam etmem gerek... Anılarımızı oymaya..."
  },
  AvgVideoCaption_117618_Content_76 = {
    Text = "Nerede kalmıştım? Evet, gizlice uçmayı öğrendiğimiz zamandaydı..."
  },
  AvgVideoCaption_117618_Content_77 = {
    Text = "ve sonra uçup gittik... nereye gitmiştik?"
  },
  AvgVideoCaption_117618_Content_78 = {
    Text = "Pollux! O aptal beynini kullan! Düşün! Unutamazsın!"
  },
  AvgVideoCaption_117618_Content_79 = {
    Text = "Kesinlikle yapamazsın..."
  },
  AvgVideoCaption_117618_Content_8 = {
    Text = "Madem bu işe yaramaz şeyler bu kadar baş belası, belki de onları tamamen ortadan kaldırmalıyız?"
  },
  AvgVideoCaption_117618_Content_80 = {
    Text = "Bugün de Işık Taşıyıcı’nın kutsal eylemlerini tekrar etmeye devam ediyoruz."
  },
  AvgVideoCaption_117618_Content_81 = {
    Text = "Evet... Leydi Fener."
  },
  AvgVideoCaption_117618_Content_82 = {
    Text = "\"Büyük ışık, Onun bedeninden fışkırdı,\""
  },
  AvgVideoCaption_117618_Content_83 = {
    Text = "\"Eti ve Kemikleri, ateşin içinde Saf Gümüş’e dönüştü.\""
  },
  AvgVideoCaption_117618_Content_84 = {
    Text = "\"Büyük ışık, Onun bedeninden fışkırdı,\""
  },
  AvgVideoCaption_117618_Content_85 = {
    Text = "\"Eti ve Kemikleri, ateşin içinde Saf Gümüş’e dönüştü.\""
  },
  AvgVideoCaption_117618_Content_86 = {
    Text = "\"Gümüş etini ve kemiklerini de indirdi,\""
  },
  AvgVideoCaption_117618_Content_87 = {
    Text = "\"ve onları, günahlarının kefareti için yeryüzündeki doğrulara bahşetti...\""
  },
  AvgVideoCaption_117618_Content_88 = {
    Text = "\"Gümüş etini ve kemiklerini de indirdi,\""
  },
  AvgVideoCaption_117618_Content_89 = {
    Text = "\"ve onları, günahlarının kefareti için yeryüzündeki doğrulara bahşetti...\""
  },
  AvgVideoCaption_117618_Content_9 = {
    Text = "Bekleyin! Hanımefendi Fener, lütfen! Lütfen yeniden düşünün!"
  },
  AvgVideoCaption_117618_Content_90 = {
    Text = "Pollux! Çok fena kan akıtıyorsun..."
  },
  AvgVideoCaption_117618_Content_91 = {
    Text = "B-Belki de onlarla birlikte geri dönmeliyiz..."
  },
  AvgVideoCaption_117618_Content_92 = {
    Text = "Hayır! Acele et! Durma! Geri dönersek, sadece daha fazlasını yitiririz..."
  },
  AvgVideoCaption_117618_Content_93 = {
    Text = "Pollux... Pollux..."
  },
  AvgVideoCaption_117618_Content_94 = {Text = "Ah..."},
  AvgVideoCaption_117618_Content_95 = {
    Text = "Ne yapmalıyım...?"
  },
  AvgVideoCaption_117618_Content_96 = {
    Text = "Doğru, kalkmam gerek, daha çok şey oymam gerek..."
  },
  AvgVideoCaption_117618_Content_97 = {
    Text = "Neredeydi...?"
  },
  AvgVideoCaption_117618_Content_98 = {
    Text = "Burada değil, burada değil..."
  },
  AvgVideoCaption_117618_Content_99 = {
    Text = "Evet, yatağın altında..."
  },
  AvgVideoCaption_117956_Content_1 = {
    Text = "Bir bakayım,"
  },
  AvgVideoCaption_117956_Content_10 = {
    Text = "Hey! Sen! Olduğun yerde kal!"
  },
  AvgVideoCaption_117956_Content_100 = {
    Text = "Bu rüzgâr değildir, ama hafiftir, çok yakındır, gitgide daha da yaklaşır,"
  },
  AvgVideoCaption_117956_Content_101 = {
    Text = "sanki biri bedenini sürükleyerek, ağır ağır kapına doğru sürünüyordur."
  },
  AvgVideoCaption_117956_Content_102 = {
    Text = "Tak, tak, tak. Biri kapını çalıyor!"
  },
  AvgVideoCaption_117956_Content_103 = {
    Text = "Öylesine korkarsın ki battaniyene büzülür, titreyerek, orada değilmişsin gibi yaparsın."
  },
  AvgVideoCaption_117956_Content_104 = {
    Text = "Çok geçmeden, vurma sesi kesildi,"
  },
  AvgVideoCaption_117956_Content_105 = {
    Text = "geride ağır ve huzursuz bir sessizlik bırakarak."
  },
  AvgVideoCaption_117956_Content_106 = {
    Text = "Kendini tutamayıp battaniyenin altından gözetliyorsun..."
  },
  AvgVideoCaption_117956_Content_107 = {
    Text = "kapı aralık!"
  },
  AvgVideoCaption_117956_Content_108 = {
    Text = "Başını eğersin, ve Karanlıktan Karanlığa bir gölge hemen yatağının yanındadır!"
  },
  AvgVideoCaption_117956_Content_109 = {
    Text = "Çığlık atmak istiyorsun, ama artık çok geç."
  },
  AvgVideoCaption_117956_Content_11 = {
    Text = "Öhöm, az önce aldığın o balkabağı şekerlerinden birazını ver bakayım!"
  },
  AvgVideoCaption_117956_Content_110 = {
    Text = "Buz sarkıtı kadar soğuk Eddie’nin elleri bileğini kavrıyor,"
  },
  AvgVideoCaption_117956_Content_111 = {
    Text = "ve kara şimşek gibi hızla üstüne atılıyor!"
  },
  AvgVideoCaption_117956_Content_112 = {
    Text = "Hissediyorsun! Tozun, küfün kokusunu,"
  },
  AvgVideoCaption_117956_Content_113 = {
    Text = "ve mide bulandıran, hastalıklı bir şeker kokusunu!"
  },
  AvgVideoCaption_117956_Content_114 = {
    Text = "Eddie'nin elleri aniden, şekeri sakladığın yere uzanır!"
  },
  AvgVideoCaption_117956_Content_115 = {
    Text = "Yastığın altında! Sırt çantasında! Ne kadar iyi saklarsan sakla!"
  },
  AvgVideoCaption_117956_Content_116 = {
    Text = "ÇAT! LOK! Yiyor! Delirmiş gibi yiyor!"
  },
  AvgVideoCaption_117956_Content_117 = {
    Text = "Çikolataların! Yumuşak şekerlerin! Lolipopların!"
  },
  AvgVideoCaption_117956_Content_118 = {
    Text = "Tek bir tanesi bile kurtulamaz! Çıkan ses, kemiklerin çatırdamasına benzer!"
  },
  AvgVideoCaption_117956_Content_119 = {
    Text = "Şekeri bitirdikten sonra gideceğini mi sanıyorsun?"
  },
  AvgVideoCaption_117956_Content_12 = {
    Text = "Neden mi? Çünkü benim asil..."
  },
  AvgVideoCaption_117956_Content_120 = {
    Text = "Hayır! Onun açlığı... daha yeni yeni kabarıyor!"
  },
  AvgVideoCaption_117956_Content_121 = {
    Text = "Yeterli değil, yetmez... Daha tatlı, en tatlısını istiyorum..."
  },
  AvgVideoCaption_117956_Content_122 = {
    Text = "Eddie’nin tamahkâr bakışı sana kilitlenmiş!"
  },
  AvgVideoCaption_117956_Content_123 = {
    Text = "Şurup bulaşmış o buz gibi el, yüzüne doğru uzanıyor!"
  },
  AvgVideoCaption_117956_Content_124 = {
    Text = "Parmağı göz kapağına dokunuyor ve bir \"pıt!\" ile"
  },
  AvgVideoCaption_117956_Content_125 = {
    Text = "en çok şekerimsi bulduğunu alır; yuvarlak, sıcak olanı..."
  },
  AvgVideoCaption_117956_Content_126 = {
    Text = "gözbebeklerin!"
  },
  AvgVideoCaption_117956_Content_127 = {
    Text = "Sonra... Çıt! Gluk!"
  },
  AvgVideoCaption_117956_Content_128 = {
    Text = "En tatlı sandığı o \"balı\" buldu,"
  },
  AvgVideoCaption_117956_Content_129 = {
    Text = "kafatasının içinde saklı olanı..."
  },
  AvgVideoCaption_117956_Content_13 = {
    Text = "Hey! Sakın kaçmaya kalkmayın! Siz terbiyesiz veletler!"
  },
  AvgVideoCaption_117956_Content_130 = {
    Text = "Ertesi sabah, insanlar seni bulacak,"
  },
  AvgVideoCaption_117956_Content_131 = {
    Text = "ve gözlerinin olduğu yerde artık yalnızca iki boş, kara delik kalır."
  },
  AvgVideoCaption_117956_Content_132 = {
    Text = "Yastığının yanında, pırıl pırıl, tertemiz şeker ambalajları etrafa saçılmıştır."
  },
  AvgVideoCaption_117956_Content_133 = {
    Text = "odaya sakladığın bütün şekerler"
  },
  AvgVideoCaption_117956_Content_134 = {
    Text = "yok olmuş olacak—tek bir tane bile kalmayacak."
  },
  AvgVideoCaption_117956_Content_135 = {
    Text = "Bu yüzden bu gece, yatağına uzanmış, ağzına kadar dolu şeker kavanozundan memnunken,"
  },
  AvgVideoCaption_117956_Content_136 = {
    Text = "dikkatli ol—"
  },
  AvgVideoCaption_117956_Content_137 = {
    Text = "Eddie seni gizlice izliyordu..."
  },
  AvgVideoCaption_117956_Content_138 = {
    Text = "Kapıyı kilitlemek mi? Faydasız."
  },
  AvgVideoCaption_117956_Content_139 = {
    Text = "Şekeri saklamak mı? O kokusunu alır!"
  },
  AvgVideoCaption_117956_Content_14 = {
    Text = "Ne kadar da alçakça. Çocuk dövmek hiç de hanımefendice değil ama balkabağı şekerlerim..."
  },
  AvgVideoCaption_117956_Content_140 = {
    Text = "Yani, eğer korkuyorsan,"
  },
  AvgVideoCaption_117956_Content_141 = {
    Text = "bütün şekerleri bana ver... cadıya!"
  },
  AvgVideoCaption_117956_Content_142 = {
    Text = "Şeker Cadısı bu leziz şekerlerle senin yerine ilgilenecek!"
  },
  AvgVideoCaption_117956_Content_143 = {
    Text = "Şeker Cadısı da ne?"
  },
  AvgVideoCaption_117956_Content_144 = {
    Text = "Başımda cadı şapkasını görmüyor musun?"
  },
  AvgVideoCaption_117956_Content_145 = {
    Text = "Bu bir kostüm değil!"
  },
  AvgVideoCaption_117956_Content_146 = {
    Text = "Bak! Bak! Bu cadının sihri!"
  },
  AvgVideoCaption_117956_Content_147 = {
    Text = "Merak etme, Şeker Cadısı’nın kucaklayışı tüm şekerler için en iyi yurttur!"
  },
  AvgVideoCaption_117956_Content_148 = {
    Text = "Peki ne yapmalıyım?"
  },
  AvgVideoCaption_117956_Content_149 = {
    Text = "Ben hayaletlerden korkmam! O haksever cadı onu un ufak edecek..."
  },
  AvgVideoCaption_117956_Content_15 = {
    Text = "Aha! Onları biraz korkutsam yeter, hehehe..."
  },
  AvgVideoCaption_117956_Content_150 = {
    Text = "Hımm? Bileğime kim dokunup duruyor? Bunun ne kadar kaba bir şey olduğunu bilmiyor musun?"
  },
  AvgVideoCaption_117956_Content_151 = {
    Text = "Kimse yok mu?"
  },
  AvgVideoCaption_117956_Content_152 = {
    Text = "Nasıl olur? Az önce açıkça..."
  },
  AvgVideoCaption_117956_Content_153 = {
    Text = "Kim şaka yapıyor? Bu komik değil!"
  },
  AvgVideoCaption_117956_Content_154 = {
    Text = "Bekle, neye bakıyorsun?"
  },
  AvgVideoCaption_117956_Content_155 = {
    Text = "Arkamdaki bir gölge mi? Nerede? Orada kimse yok!"
  },
  AvgVideoCaption_117956_Content_156 = {
    Text = "Neden toz ve eski kıyafet kokusu alıyorum...?"
  },
  AvgVideoCaption_117956_Content_157 = {
    Text = "Hayır, bu olamaz! Bunu açıkça ben uydurdum!"
  },
  AvgVideoCaption_117956_Content_158 = {
    Text = "Neye gülüyorsunuz siz? Nesi komik bunun? İiiih!!!"
  },
  AvgVideoCaption_117956_Content_159 = {
    Text = "Göremiyorum! Gözlerim! Kim o?!"
  },
  AvgVideoCaption_117956_Content_16 = {
    Text = "Durun, siz her ne kadar tamahkâr, cimri ve mantıksız olsanız da,"
  },
  AvgVideoCaption_117956_Content_160 = {
    Text = "Bırak beni! İmda—"
  },
  AvgVideoCaption_117956_Content_161 = {
    Text = "Jenkin?! Küçük Fare?!"
  },
  AvgVideoCaption_117956_Content_162 = {
    Text = "Siz ikiniz ne zaman geldiniz?"
  },
  AvgVideoCaption_117956_Content_163 = {
    Text = "Harika! Demek az önce benimle dalga geçen sizdiniz!"
  },
  AvgVideoCaption_117956_Content_164 = {
    Text = "Be—ben hayaletlerden korkmam!"
  },
  AvgVideoCaption_117956_Content_165 = {
    Text = "Kapa çeneni! Gülmek yok!"
  },
  AvgVideoCaption_117956_Content_166 = {
    Text = "Aaah! Seni lanet fare!"
  },
  AvgVideoCaption_117956_Content_167 = {
    Text = "Koşmayı kesin! Bunun hesabını ödeteceğim!!"
  },
  AvgVideoCaption_117956_Content_17 = {
    Text = "Şeker Hayaleti’nin peşinize düşmesinden hiç mi korkmuyorsunuz?"
  },
  AvgVideoCaption_117956_Content_18 = {
    Text = "Şeker Hayaleti de ne?"
  },
  AvgVideoCaption_117956_Content_19 = {
    Text = "Hehe, biraz daha yaklaşıp koklayın."
  },
  AvgVideoCaption_117956_Content_2 = {
    Text = "Cadılar Bayramı arifesindeki afişteki son şeker durağı..."
  },
  AvgVideoCaption_117956_Content_20 = {
    Text = "Karamel kokusunun dışında,"
  },
  AvgVideoCaption_117956_Content_21 = {
    Text = "havada tozun, eski kıyafetlerin ve hafif bir küf kokusunun izlerini almıyor musunuz...?"
  },
  AvgVideoCaption_117956_Content_22 = {
    Text = "Evet, aynen öyle, biraz daha yaklaşın!"
  },
  AvgVideoCaption_117956_Content_23 = {
    Text = "Hepiniz kulaklarınızı dikip dikkatle dinlemelisiniz"
  },
  AvgVideoCaption_117956_Content_24 = {
    Text = "bu açlıktan ölen hayaletin hikâyesine..."
  },
  AvgVideoCaption_117956_Content_25 = {
    Text = "Çok, çok uzun zaman önce—"
  },
  AvgVideoCaption_117956_Content_26 = {
    Text = "muhtemelen sizin büyük büyük dedeniz daha Küçük Oğlan iken—"
  },
  AvgVideoCaption_117956_Content_27 = {
    Text = "Eddie adında bir öğrenci varmış..."
  },
  AvgVideoCaption_117956_Content_28 = {
    Text = "Evet, burada, Mythag’da yaşayan Eddie Umut."
  },
  AvgVideoCaption_117956_Content_29 = {
    Text = "Zavallı Eddie öylesine cılızdı ki,"
  },
  AvgVideoCaption_117956_Content_3 = {
    Text = "Tam da burada!"
  },
  AvgVideoCaption_117956_Content_30 = {
    Text = "eski üniforması üzerinde sarkıp dururdu,"
  },
  AvgVideoCaption_117956_Content_31 = {
    Text = "kuru dallardan yapılmış bir korkuluğu andırırdı."
  },
  AvgVideoCaption_117956_Content_32 = {
    Text = "Neden bu kadar zayıfmış?"
  },
  AvgVideoCaption_117956_Content_33 = {
    Text = "Şey, çünkü Eddie bir yetimdi."
  },
  AvgVideoCaption_117956_Content_34 = {
    Text = "Ve o zamanlar Mythag korkunç derecede küçük ve yoksuldu, bu yüzden herkes aç gezerdi!"
  },
  AvgVideoCaption_117956_Content_35 = {
    Text = "Bunların hiçbiri önemli değil. Neyse,"
  },
  AvgVideoCaption_117956_Content_36 = {
    Text = "Eddie konuşmayı sevmezdi. Hep içine kapanıktı, o tehlikeli saha görevlerine tek başına giderdi."
  },
  AvgVideoCaption_117956_Content_37 = {
    Text = "Ne yazık ki, kısa süre sonra dehşet verici bir Hastalık kaptı."
  },
  AvgVideoCaption_117956_Content_38 = {
    Text = "Koyu bir pislikle yavaş yavaş aşınan eti, yüzünde delikler açmaya başlamıştı."
  },
  AvgVideoCaption_117956_Content_39 = {
    Text = "Bazen, ufak bir dalgınlıkla, şap diye—"
  },
  AvgVideoCaption_117956_Content_4 = {
    Text = "Ne?! Neden yine bu kadar çok çocuk var?"
  },
  AvgVideoCaption_117956_Content_40 = {
    Text = "Yüzünden, hafifçe sallanarak asılı duran bir parça deri kopup düşüveriyordu..."
  },
  AvgVideoCaption_117956_Content_41 = {
    Text = "Sadece bununla kalmıyor, yavaş yavaş unutuluyordu da."
  },
  AvgVideoCaption_117956_Content_42 = {
    Text = "Yurtta hasta yatan zavallı bir ruhu"
  },
  AvgVideoCaption_117956_Content_43 = {
    Text = "kimse hatırlamazdı."
  },
  AvgVideoCaption_117956_Content_44 = {
    Text = "Sonunda Eddie o kadar zayıfladı ki, artık yemek bile yiyemez oldu."
  },
  AvgVideoCaption_117956_Content_45 = {
    Text = "ya da içecek bir şey."
  },
  AvgVideoCaption_117956_Content_46 = {
    Text = "O kadar açtı ki karnı sırtına yapışmış, boğazı ateş gibi kupkuruydu."
  },
  AvgVideoCaption_117956_Content_47 = {
    Text = "Yatağından yükselen dalga dalga ağıtlar dökmekten başka hiçbir şey yapamıyordu."
  },
  AvgVideoCaption_117956_Content_48 = {
    Text = "Bunun Şeker Hayaleti’yle ne ilgisi var?"
  },
  AvgVideoCaption_117956_Content_49 = {
    Text = "Acele etmeyin! Dinleyin, anlarsınız."
  },
  AvgVideoCaption_117956_Content_5 = {
    Text = "Mythag’in hep bu kadar çok çocuklu ailesi var mıydı?"
  },
  AvgVideoCaption_117956_Content_50 = {
    Text = "Cadılar Bayramı gecesinde,"
  },
  AvgVideoCaption_117956_Content_51 = {
    Text = "ansızın aşağı kattan hafif bir kahkaha duydu."
  },
  AvgVideoCaption_117956_Content_52 = {
    Text = "Çocuklar, \"Şeker mi şaka mı!\" diye bağırıyordu."
  },
  AvgVideoCaption_117956_Content_53 = {
    Text = "penceresinin önünden koşarak geçiyorlardı."
  },
  AvgVideoCaption_117956_Content_54 = {
    Text = "O gür kahkahalar ve hafif şeker kokusu"
  },
  AvgVideoCaption_117956_Content_55 = {
    Text = "göğsünü tırmalayan şeytani bir pençe gibiydi."
  },
  AvgVideoCaption_117956_Content_56 = {
    Text = "Neden unutulmuştu?"
  },
  AvgVideoCaption_117956_Content_57 = {
    Text = "Neden kimse ona bakmaya gelmiyordu?"
  },
  AvgVideoCaption_117956_Content_58 = {
    Text = "Unutulmuş Dehşet ve hastalığın Pain’i onu didik didik ediyordu."
  },
  AvgVideoCaption_117956_Content_59 = {
    Text = "Birden, muazzam bir arzu onu ele geçirdi."
  },
  AvgVideoCaption_117956_Content_6 = {
    Text = "Çabuk olun, çabuk olun..."
  },
  AvgVideoCaption_117956_Content_60 = {
    Text = "Bir karar verdi—deli, umutsuz bir karar."
  },
  AvgVideoCaption_117956_Content_61 = {
    Text = "Bir parça şeker bulacaktı! Tek bir tane!"
  },
  AvgVideoCaption_117956_Content_62 = {
    Text = "Eğer bu gece ölecekse, ölürken ağzında tatlı bir iz kalmalıydı."
  },
  AvgVideoCaption_117956_Content_63 = {
    Text = "Eddie, tüm gücünü toplayıp yataktan sürünerek indi, kendini parça parça ileri çekti"
  },
  AvgVideoCaption_117956_Content_64 = {
    Text = "elleri yerde sürünerek..."
  },
  AvgVideoCaption_117956_Content_65 = {
    Text = "İnce kapıyı itti, açtı"
  },
  AvgVideoCaption_117956_Content_66 = {
    Text = "ve bir gölge gibi yavaşça karanlık, soğuk merdivenlerden aşağı süzüldü."
  },
  AvgVideoCaption_117956_Content_67 = {
    Text = "Sürüne sürüne ilerledi,"
  },
  AvgVideoCaption_117956_Content_68 = {
    Text = "ama çok zayıftı, çok üşüyordu."
  },
  AvgVideoCaption_117956_Content_69 = {
    Text = "Yurt kapısına vardığında, o koca kapıyı açacak hâli kalmamıştı."
  },
  AvgVideoCaption_117956_Content_7 = {
    Text = "AAAH!! BELLİYDİ! Şeker sepeti boş!"
  },
  AvgVideoCaption_117956_Content_70 = {
    Text = "\"Kim... bana yardım edecek... kim... bana bir şeker verecek...\""
  },
  AvgVideoCaption_117956_Content_71 = {
    Text = "Kimse sesini duymadı, kimse siluetini görmedi."
  },
  AvgVideoCaption_117956_Content_72 = {
    Text = "Bir gıcırtıyla, neşeli Öğrenciler ana kapıyı itti."
  },
  AvgVideoCaption_117956_Content_73 = {
    Text = "ve sonra sayısız ayakkabı onu çiğnedi geçti."
  },
  AvgVideoCaption_117956_Content_74 = {
    Text = "\"Çıt\"—bu, Eddie’nin kemiklerinin kırılma sesiydi."
  },
  AvgVideoCaption_117956_Content_75 = {
    Text = "\"Çıtır\"—bu, Eddie’nin etinin ezilişinin sesiydi..."
  },
  AvgVideoCaption_117956_Content_76 = {
    Text = "Onun umutsuz çığlıkları, neşeli kahkahalar arasında boğuldu,"
  },
  AvgVideoCaption_117956_Content_77 = {
    Text = "ta ki yerde silik bir lekeye dönüşene dek; o özlem dolu eli hâlâ kapıya doğru uzanıyordu..."
  },
  AvgVideoCaption_117956_Content_78 = {
    Text = "Ölmeden önce, rüyasını süsleyen şekeri hiç tadamadı..."
  },
  AvgVideoCaption_117956_Content_79 = {
    Text = "Eddie öldü."
  },
  AvgVideoCaption_117956_Content_8 = {
    Text = "Şu sinir bozucu küçük çekirgeler!"
  },
  AvgVideoCaption_117956_Content_80 = {
    Text = "Ama onun açlığı... kemiğe işleyen o şeker arzusu ölmedi."
  },
  AvgVideoCaption_117956_Content_81 = {
    Text = "Koyu bir şurup gibi oyalanıp kaldı, kış rüzgârı kadar yakıcı ve acımasız."
  },
  AvgVideoCaption_117956_Content_82 = {
    Text = "Her yıl, balkabakları ışıldayıp hava şeker kokusuyla dolduğunda, Eddie..."
  },
  AvgVideoCaption_117956_Content_83 = {
    Text = "ya da daha doğrusu, Eddie’nin geride bıraktığı açlık—uyanışa geçti."
  },
  AvgVideoCaption_117956_Content_84 = {
    Text = "Artık o zavallı erkek çocuk değil;"
  },
  AvgVideoCaption_117956_Content_85 = {
    Text = "artık başka bir şeye, daha da dehşet verici bir şeye dönüşmüştür,"
  },
  AvgVideoCaption_117956_Content_86 = {
    Text = "bu kampüsün gölgelerinde pusuda bekliyor."
  },
  AvgVideoCaption_117956_Content_87 = {
    Text = "Şekerin kokusunu alabiliyor!"
  },
  AvgVideoCaption_117956_Content_88 = {
    Text = "Özellikle de sepete sakladığın, sırt çantana gizlediğin, sıcak ceplerinin derinliklerine gömdüğün o gizli hazineler!"
  },
  AvgVideoCaption_117956_Content_89 = {
    Text = "Azizler Gecesi'nde, eğer yanında çok fazla şeker taşıyorsan, eve döndüğünde"
  },
  AvgVideoCaption_117956_Content_9 = {
    Text = "Olmaz. O sınırlı üretim, çok aromalı balkabağı şekerini daha tadamadım bile!"
  },
  AvgVideoCaption_117956_Content_90 = {
    Text = "ensende bir ürperti hissedeceksin, sanki birinin soğuk nefesi az önce oradan geçmiş gibi."
  },
  AvgVideoCaption_117956_Content_91 = {
    Text = "Arkanı döndüğünde, hiçbir şey bulamayacaksın,"
  },
  AvgVideoCaption_117956_Content_92 = {
    Text = "sadece rüzgârı ve tuhaf gölgeleri..."
  },
  AvgVideoCaption_117956_Content_93 = {
    Text = "Hayır. O, peşinden gelen Eddie!"
  },
  AvgVideoCaption_117956_Content_94 = {
    Text = "Şekerin kokusuna kapılıp, sessizce peşine düşecek."
  },
  AvgVideoCaption_117956_Content_95 = {
    Text = "Tek alabildiğin koku, tozla eski giysilerin karıştığı hafif, küflü bir koku."
  },
  AvgVideoCaption_117956_Content_96 = {
    Text = "Ta ki gece yarısı gelene dek! Saat kulesi on ikinci vuruşunu çaldığında,"
  },
  AvgVideoCaption_117956_Content_97 = {
    Text = "kampüs bütünüyle susar—baykuşlar bile ötmez olur."
  },
  AvgVideoCaption_117956_Content_98 = {
    Text = "Tam o anda... kapından gelen tuhaf bir ses duyarsın."
  },
  AvgVideoCaption_117956_Content_99 = {
    Text = "\"Şaak... şaak...\""
  },
  AvgVideoCaption_122450_Content_1 = {
    Text = "<Italic:Çıkış, çıkış tam orada...>"
  },
  AvgVideoCaption_122450_Content_10 = {
    Text = "Şimdi, sapkın Kemik ve Kan yazgıya dokunsun;"
  },
  AvgVideoCaption_122450_Content_11 = {
    Text = "Sahte bir göbek bağı aracılığıyla,"
  },
  AvgVideoCaption_122450_Content_12 = {
    Text = "Bu zayıf geçidimden,"
  },
  AvgVideoCaption_122450_Content_13 = {
    Text = "Bu dünyada yeniden doğ!"
  },
  AvgVideoCaption_122450_Content_14 = {
    Text = "Bak, Gözlerini yeni açtı!"
  },
  AvgVideoCaption_122450_Content_15 = {
    Text = "Gel, sarıl bana, sevgili bebeğim..."
  },
  AvgVideoCaption_122450_Content_16 = {
    Text = "<Italic:\"Sevgilim...>"
  },
  AvgVideoCaption_122450_Content_17 = {
    Text = "<Italic:\"Sevgilim... Fa>"
  },
  AvgVideoCaption_122450_Content_18 = {
    Text = "<Italic:\"Sevgilim... <RedBold:Father>\">"
  },
  AvgVideoCaption_122450_Content_19 = {Text = "...Kaderim"},
  AvgVideoCaption_122450_Content_2 = {
    Text = "Neden kaçıyoruz?"
  },
  AvgVideoCaption_122450_Content_3 = {
    Text = "Endişelenme... burası çok güvenli"
  },
  AvgVideoCaption_122450_Content_4 = {
    Text = "<Italic:Hayır... “ilahi annen” olmak istemiyorum...>"
  },
  AvgVideoCaption_122450_Content_5 = {
    Text = "Ben bir tanrının kızıyım"
  },
  AvgVideoCaption_122450_Content_6 = {
    Text = "Hiç kimse irademe karşı gelemez"
  },
  AvgVideoCaption_122450_Content_7 = {
    Text = "Aaahh... hissediyorum..."
  },
  AvgVideoCaption_122450_Content_8 = {
    Text = "Ne kadar kusursuz bir Pain"
  },
  AvgVideoCaption_122450_Content_9 = {
    Text = "Ne kadar lekesiz bir olgunlaşma"
  },
  AvgVideoCaption_122705_Content_1 = {
    Text = "Bu, Tanrı’nın doğumundan sonraki yedi günün hikâyesidir."
  },
  AvgVideoCaption_122705_Content_10 = {
    Text = "yine de herkesin yüzü fanatik bir sevinçle aydınlanmıştı."
  },
  AvgVideoCaption_122705_Content_100 = {
    Text = "Göğsümün üzerinde yatan"
  },
  AvgVideoCaption_122705_Content_101 = {
    Text = "sadece sahte bir suretti,"
  },
  AvgVideoCaption_122705_Content_102 = {
    Text = "yanlışlıkla \"tanrı\" diye adlandırılmış bir ölü et yığını."
  },
  AvgVideoCaption_122705_Content_103 = {Text = "Neden?"},
  AvgVideoCaption_122705_Content_104 = {
    Text = "Neden bu sapkın, adaletsiz kader beni bırakmıyor?"
  },
  AvgVideoCaption_122705_Content_105 = {
    Text = "Tanrım, neden beni hep cezalandırmak zorundasın?"
  },
  AvgVideoCaption_122705_Content_106 = {Text = "Tanrı...?"},
  AvgVideoCaption_122705_Content_107 = {
    Text = "Hah! Haha! Şimdi anlıyorum!"
  },
  AvgVideoCaption_122705_Content_108 = {
    Text = "Bunu daha önce fark etmeliydim!"
  },
  AvgVideoCaption_122705_Content_109 = {
    Text = "Sen hiç de Tanrı falan değilsin, değil mi?"
  },
  AvgVideoCaption_122705_Content_11 = {
    Text = "Sevinç mi hissetmem gerekiyordu?"
  },
  AvgVideoCaption_122705_Content_110 = {
    Text = "Gerçek bir tanrı, takipçilerinin böylesi bir deliliğe çürümesine nasıl izin verebilir?"
  },
  AvgVideoCaption_122705_Content_111 = {
    Text = "Gerçek bir tanrı, nasıl olur da pis, kokuşmuş bir leş gölü olabilir?"
  },
  AvgVideoCaption_122705_Content_112 = {
    Text = "Hepsi bana yalan söyledi. Sözde tanrı Miryam..."
  },
  AvgVideoCaption_122705_Content_113 = {
    Text = "hepsi yalancı! Her şey bir yalan!"
  },
  AvgVideoCaption_122705_Content_114 = {
    Text = "Ha! Bu yalanın içinde ne kadar uzun yaşamışım."
  },
  AvgVideoCaption_122705_Content_115 = {
    Text = "Bu çürümüş et parçası için ne ağır bir bedel ödedim..."
  },
  AvgVideoCaption_122705_Content_116 = {
    Text = "Kader? Yazgı? Sadece bir sanrı..."
  },
  AvgVideoCaption_122705_Content_117 = {
    Text = "Sen kimsin, canavar... benim geleceğime hükmedecek?"
  },
  AvgVideoCaption_122705_Content_118 = {
    Text = "Bu bedeli senin için ödemedim!"
  },
  AvgVideoCaption_122705_Content_119 = {Text = "Asla!"},
  AvgVideoCaption_122705_Content_12 = {
    Text = "Sevinç çığlıkları mı atmalıydım?"
  },
  AvgVideoCaption_122705_Content_120 = {
    Text = "Geber, iğrenç canavar!"
  },
  AvgVideoCaption_122705_Content_121 = {
    Text = "Neredeyim ben?"
  },
  AvgVideoCaption_122705_Content_122 = {
    Text = "Geri döndüm... Onun doğduğu güne...?"
  },
  AvgVideoCaption_122705_Content_123 = {
    Text = "İlahi Ana! İlahi Ana!"
  },
  AvgVideoCaption_122705_Content_124 = {
    Text = "İyi çocuk, görkemli bir Kurban sundun..."
  },
  AvgVideoCaption_122705_Content_125 = {
    Text = "Haha... Geri döndüm! Yine buradayım!"
  },
  AvgVideoCaption_122705_Content_126 = {
    Text = "Kaçamam! KAÇAMIYORUM...!"
  },
  AvgVideoCaption_122705_Content_127 = {
    Text = "Yıldızların yörüngesi, en başından göğe kazınmıştı;"
  },
  AvgVideoCaption_122705_Content_128 = {
    Text = "her çatallanan yol yalnızca aynı uçuruma çıkar..."
  },
  AvgVideoCaption_122705_Content_129 = {
    Text = "Sözde Seçim’im... bundan başka bir şey değil"
  },
  AvgVideoCaption_122705_Content_13 = {
    Text = "Emin değildim."
  },
  AvgVideoCaption_122705_Content_130 = {
    Text = "kendi kendini aldatan bir doğaçlama... kaderin çoktan yazmayı bitirdiği bir senaryoda!"
  },
  AvgVideoCaption_122705_Content_131 = {
    Text = "Tanrım, madem bu saçma oyunu yeniden yazmamakta ısrar ediyorsun..."
  },
  AvgVideoCaption_122705_Content_132 = {
    Text = "Öyleyse sana bizzat tanık ettireceğim:"
  },
  AvgVideoCaption_122705_Content_133 = {
    Text = "Harekete geçirdiğin her şey"
  },
  AvgVideoCaption_122705_Content_134 = {
    Text = "kendi şanıma giden merdiven olacak!"
  },
  AvgVideoCaption_122705_Content_14 = {
    Text = "Onun doğumundan sonraki ikinci gün."
  },
  AvgVideoCaption_122705_Content_15 = {
    Text = "İlahi Ana, Fetüs için vaftiz ayinini gerçekleştirdi."
  },
  AvgVideoCaption_122705_Content_16 = {
    Text = "Rabbimiz, onun kabalığını ve ihmalini bağışlasın."
  },
  AvgVideoCaption_122705_Content_17 = {
    Text = "Siz pis hizmetkârlar, hemen çekilin!"
  },
  AvgVideoCaption_122705_Content_18 = {
    Text = "Onun gerçek suretine bakmaya yalnızca ben layığım."
  },
  AvgVideoCaption_122705_Content_19 = {
    Text = "Doğurduğum o “tanrı”yı kimsenin görmeye cesaret edemedim."
  },
  AvgVideoCaption_122705_Content_2 = {
    Text = "Onun doğuşundan sonraki birinci gün."
  },
  AvgVideoCaption_122705_Content_20 = {
    Text = "Vaftiz edilen “fetüs”, kaotik etten bir yığın, ruhsuz bir ilahiydi."
  },
  AvgVideoCaption_122705_Content_21 = {
    Text = "Demek hâlâ kusurlu olduğum için..."
  },
  AvgVideoCaption_122705_Content_22 = {
    Text = "Kimsenin bunu keşfetmesine izin veremem."
  },
  AvgVideoCaption_122705_Content_23 = {
    Text = "Zamanla, tanrı çağrıma yanıt verdiğinde, her şey yoluna girecek."
  },
  AvgVideoCaption_122705_Content_24 = {
    Text = "Onun doğumundan sonraki üçüncü gün."
  },
  AvgVideoCaption_122705_Content_25 = {
    Text = "Kutsal Cenin hâlâ gözlerini açmamıştı."
  },
  AvgVideoCaption_122705_Content_26 = {
    Text = "Yüce Tanrım, gözlerini ne zaman sonunda açacaksın?"
  },
  AvgVideoCaption_122705_Content_27 = {
    Text = "Miryam’a söz vermemiş miydin"
  },
  AvgVideoCaption_122705_Content_28 = {
    Text = "İlahi Diyar’ın dirilişini sen mi getireceksin?"
  },
  AvgVideoCaption_122705_Content_29 = {
    Text = "Onun doğuşundan sonraki dördüncü gün."
  },
  AvgVideoCaption_122705_Content_3 = {
    Text = "Kutsal Cenin, kül rengi bir kabuğun içinde doğdu."
  },
  AvgVideoCaption_122705_Content_30 = {
    Text = "Bugün mabette ayinî komünyon gerçekleştirildi."
  },
  AvgVideoCaption_122705_Content_31 = {
    Text = "Lütfen görkemini üzerimize bahşet,"
  },
  AvgVideoCaption_122705_Content_32 = {
    Text = "ve bize, Denizcilere, İlahi Diyar’ın yükselişinin koordinatlarını açıklasın."
  },
  AvgVideoCaption_122705_Content_33 = {
    Text = "Alçakgönüllülükle dirilişini ve zuhurunu bekliyoruz."
  },
  AvgVideoCaption_122705_Content_34 = {
    Text = "İlahi Diyar’ın geleceğini sordum,"
  },
  AvgVideoCaption_122705_Content_35 = {
    Text = "Onunla benim aramdaki bağı,"
  },
  AvgVideoCaption_122705_Content_36 = {
    Text = "bilmek istediğim her şeyi,"
  },
  AvgVideoCaption_122705_Content_37 = {
    Text = "ve Miryam’ın yoklamak istediği her şeyi."
  },
  AvgVideoCaption_122705_Content_38 = {
    Text = "Tanrı sessiz kaldı."
  },
  AvgVideoCaption_122705_Content_39 = {
    Text = "Onun doğuşundan sonraki beşinci gün."
  },
  AvgVideoCaption_122705_Content_4 = {
    Text = "Yıldızlar yerinde! Yıldızlar yerinde!"
  },
  AvgVideoCaption_122705_Content_40 = {
    Text = "Miryam, tanrıyla yaptığım görüşmenin sonucunu bana sordu."
  },
  AvgVideoCaption_122705_Content_41 = {Text = "Nasıl?"},
  AvgVideoCaption_122705_Content_42 = {
    Text = "Tam iki gün oldu..."
  },
  AvgVideoCaption_122705_Content_43 = {Text = "Efendim..."},
  AvgVideoCaption_122705_Content_44 = {
    Text = "Onun Sesini duydunuz mu?"
  },
  AvgVideoCaption_122705_Content_45 = {
    Text = "Elbette, elbette duydum!"
  },
  AvgVideoCaption_122705_Content_46 = {
    Text = "Böyle bir sorgulama, İlahi Ana’ya hakarettir!"
  },
  AvgVideoCaption_122705_Content_47 = {
    Text = "Murphy, Murphy, sevgili Murphy’m."
  },
  AvgVideoCaption_122705_Content_48 = {
    Text = "Efendimiz bize ne tür bir İlahi Kehanet bahşetti?"
  },
  AvgVideoCaption_122705_Content_49 = {
    Text = "O... O şöyle dedi: “İlahi Diyar az sonra yükselecek.”"
  },
  AvgVideoCaption_122705_Content_5 = {
    Text = "Rabbimiz yeniden doğdu."
  },
  AvgVideoCaption_122705_Content_50 = {
    Text = "Biliyordum, biliyordum!"
  },
  AvgVideoCaption_122705_Content_51 = {
    Text = "Sayısız yıldız kavuşumu boyunca süren bekleyişim boşa gitmedi!"
  },
  AvgVideoCaption_122705_Content_52 = {
    Text = "Efendimiz, Efendimiz sonunda sözünü tutacak!"
  },
  AvgVideoCaption_122705_Content_53 = {
    Text = "Peki, bu ne zaman olacak?"
  },
  AvgVideoCaption_122705_Content_54 = {
    Text = "İ-İlahi Diyar gelecek, bu kesin."
  },
  AvgVideoCaption_122705_Content_55 = {
    Text = "Kesin an gerçekten bu kadar mı önemli?"
  },
  AvgVideoCaption_122705_Content_56 = {
    Text = "Hayır, hayır, hayır. Tütsüyle arınmalı ve tüm soydaşlarımızı"
  },
  AvgVideoCaption_122705_Content_57 = {
    Text = "yükselişin gerçekleşeceği yere götürmeli, orada Rabbimizin zuhurunu beklemeliyiz."
  },
  AvgVideoCaption_122705_Content_58 = {
    Text = "...“Yıldızlar Doğru Konumda Olduğunda,” dedi."
  },
  AvgVideoCaption_122705_Content_59 = {
    Text = "Yıldızlar Doğru Konumda Olduğunda mı?"
  },
  AvgVideoCaption_122705_Content_6 = {
    Text = "Ey Rabbim, beni duydun, bana cevap verdin!"
  },
  AvgVideoCaption_122705_Content_60 = {
    Text = "Hangi vakitte?"
  },
  AvgVideoCaption_122705_Content_61 = {
    Text = "Bir sonrakinde mi? Yoksa ondan sonrakinde mi?"
  },
  AvgVideoCaption_122705_Content_62 = {
    Text = "Kapa çeneni! “Yıldızlar Doğru Konumda Olduğunda” dedim—"
  },
  AvgVideoCaption_122705_Content_63 = {
    Text = "tam olarak ne zaman olacağını ben nereden bileyim?!"
  },
  AvgVideoCaption_122705_Content_64 = {
    Text = "Doğru, doğru."
  },
  AvgVideoCaption_122705_Content_65 = {
    Text = "Rabbimiz, uzun hafif uykusundan henüz yeni uyandı."
  },
  AvgVideoCaption_122705_Content_66 = {
    Text = "Bilinci hâlâ Kaos içinde olmalı;"
  },
  AvgVideoCaption_122705_Content_67 = {
    Text = "Şimdiki zaman hakkında muğlak konuşması normal."
  },
  AvgVideoCaption_122705_Content_68 = {
    Text = "Yeter ki Efendimiz inecek olsun..."
  },
  AvgVideoCaption_122705_Content_69 = {
    Text = "sonunda önemsizleşecek..."
  },
  AvgVideoCaption_122705_Content_7 = {
    Text = "Senin iraden yeniden yeryüzünde yerine gelecek!"
  },
  AvgVideoCaption_122705_Content_70 = {
    Text = "Miryam kendinden geçmişti."
  },
  AvgVideoCaption_122705_Content_71 = {
    Text = "Daha önce hiç görmediğim çılgın bir Hazdı bu—"
  },
  AvgVideoCaption_122705_Content_72 = {
    Text = "ne ona ahşap oymayı Hediye ettiğimde,"
  },
  AvgVideoCaption_122705_Content_73 = {
    Text = "ne de Kutsal Cenin’i rahmime düşürdüğümde böylesini görmüştüm."
  },
  AvgVideoCaption_122705_Content_74 = {
    Text = "Onun doğuşundan sonraki altıncı gün."
  },
  AvgVideoCaption_122705_Content_75 = {
    Text = "Yüreğimdeki parlak hale, kasvetli bir bulutla gölgelendi."
  },
  AvgVideoCaption_122705_Content_76 = {
    Text = "Acaba Rabbimize, İlahi Diyar’ın nereye ineceğini sorabilir misin?"
  },
  AvgVideoCaption_122705_Content_77 = {
    Text = "Denizcileri, sunağı önceden civarda inşa etmeleri için görevlendireceğim."
  },
  AvgVideoCaption_122705_Content_78 = {
    Text = "Daha karar vermediğini söyledi! Yalnızca deniz seviyesinin altından yükseleceğini söyledi!"
  },
  AvgVideoCaption_122705_Content_79 = {
    Text = "Bu... doğru mu?"
  },
  AvgVideoCaption_122705_Content_8 = {
    Text = "Lemuria, rehberliğiniz altında ebediyen ölümsüz kalacak!"
  },
  AvgVideoCaption_122705_Content_80 = {
    Text = "E-elbette doğru!"
  },
  AvgVideoCaption_122705_Content_81 = {
    Text = "Bunu sana İlahi Ana olarak söylüyorum! Nasıl yanılıyor olabilirim?"
  },
  AvgVideoCaption_122705_Content_82 = {
    Text = "Bağışlayın. Fazla heveskârdım."
  },
  AvgVideoCaption_122705_Content_83 = {
    Text = "Seni sorgulamamalıydım, İlahi Ana."
  },
  AvgVideoCaption_122705_Content_84 = {
    Text = "O zamanlar, Lemuria’daki Kralımız"
  },
  AvgVideoCaption_122705_Content_85 = {
    Text = "da böyle hissizdi..."
  },
  AvgVideoCaption_122705_Content_86 = {
    Text = "Lütfen elini öpmeme izin ver,"
  },
  AvgVideoCaption_122705_Content_87 = {
    Text = "saygısızlığım için özür dilemek adına."
  },
  AvgVideoCaption_122705_Content_88 = {
    Text = "...Sonunda gösteriyi satmayı başardım."
  },
  AvgVideoCaption_122705_Content_89 = {
    Text = "Ama yarın ne yapacağım?"
  },
  AvgVideoCaption_122705_Content_9 = {
    Text = "Bitkindim, ruhen tükenmiştim,"
  },
  AvgVideoCaption_122705_Content_90 = {
    Text = "Neden? Bana nedenini söyleyebilir misin? Neden kurbanlarımıza, dualarımıza cevap vermeyi reddediyorsun?"
  },
  AvgVideoCaption_122705_Content_91 = {
    Text = "Miryam bana hiç inanmadı;"
  },
  AvgVideoCaption_122705_Content_92 = {
    Text = "bunu Onun Gözleri’nde görebiliyordum."
  },
  AvgVideoCaption_122705_Content_93 = {
    Text = "O, Tanrı’yı hayattayken görmüştü."
  },
  AvgVideoCaption_122705_Content_94 = {
    Text = "Yalanlarım onun üzerinde işe yaramayabilir."
  },
  AvgVideoCaption_122705_Content_95 = {
    Text = "Tanrım, kurtar beni, lütfen,"
  },
  AvgVideoCaption_122705_Content_96 = {
    Text = "tek bir söz, duama cevap ver."
  },
  AvgVideoCaption_122705_Content_97 = {
    Text = "Onun doğuşundan yedinci gün."
  },
  AvgVideoCaption_122705_Content_98 = {
    Text = "Tanrı ölmüştü."
  },
  AvgVideoCaption_122705_Content_99 = {
    Text = "Tanrı hiç doğmamıştı."
  },
  AvgVideoCaption_124223_Content_1 = {
    Text = "Müfettiş bir keresinde şöyle demişti—neydi o yine?"
  },
  AvgVideoCaption_124223_Content_10 = {
    Text = "Ah, evet, Sis Felaketi'nde, aniden \"Kadim Nesneleri\" görme yeteneğimi kaybetmiş olmama rağmen,"
  },
  AvgVideoCaption_124223_Content_100 = {
    Text = "Bir kaza mı? Bir hata mı? Yoksa başka bir şey mi?"
  },
  AvgVideoCaption_124223_Content_101 = {
    Text = "Konuş, söyle bana, neden buradayım!"
  },
  AvgVideoCaption_124223_Content_102 = {
    Text = "Kim, hangi amaçla, beni buraya getirdi!"
  },
  AvgVideoCaption_124223_Content_103 = {
    Text = "Konuşmuyorsun, öyle mi? Sorun değil, önemli değil, ağzınız yok, anlıyorum."
  },
  AvgVideoCaption_124223_Content_104 = {
    Text = "Ağzı olan insanlar bulmam gerekiyor."
  },
  AvgVideoCaption_124223_Content_105 = {
    Text = "Evet, insanlar; yoğun Sisten yapılmış Canavarlar değil."
  },
  AvgVideoCaption_124223_Content_106 = {
    Text = "Geri dönmeliyim, mutlaka geri dönmeliyim."
  },
  AvgVideoCaption_124223_Content_107 = {
    Text = "Bu lanetli yer... biraz daha kalırsam aklımı yitireceğim..."
  },
  AvgVideoCaption_124223_Content_108 = {
    Text = "28. Gün, insan buldum."
  },
  AvgVideoCaption_124223_Content_109 = {
    Text = "Ve sonunda, benim \"ruh göçümün\" sebebini çözdüm."
  },
  AvgVideoCaption_124223_Content_11 = {
    Text = "yine de eve dönmek kadar tanıdık geliyordu."
  },
  AvgVideoCaption_124223_Content_110 = {
    Text = "O tarikatçılar."
  },
  AvgVideoCaption_124223_Content_111 = {
    Text = "İlk kez \"ruh göçü\" yaşadığımda gördüğüm tarikatçılar beni çağırmış."
  },
  AvgVideoCaption_124223_Content_112 = {
    Text = "O kaçıklar buradan ayrılıp lanet olası bir \"yeni dünya\" bulmak istiyorlardı."
  },
  AvgVideoCaption_124223_Content_113 = {
    Text = "Ama bunun yerine, beni \"yeni dünya\"dan alıp buraya aktardılar."
  },
  AvgVideoCaption_124223_Content_114 = {
    Text = "Ha, ne kara mizah ama."
  },
  AvgVideoCaption_124223_Content_115 = {
    Text = "Müfettiş, aslında bu soruşturma günlüğünü sana göstermek için geri getirmek istiyordum."
  },
  AvgVideoCaption_124223_Content_116 = {
    Text = "Ama artık buna ihtiyacım yok."
  },
  AvgVideoCaption_124223_Content_117 = {
    Text = "Yeni bir planım var."
  },
  AvgVideoCaption_124223_Content_118 = {
    Text = "İnsan Kurbanları yakalamayı sevmiyorlar mı?"
  },
  AvgVideoCaption_124223_Content_119 = {
    Text = "İşte size bir tane."
  },
  AvgVideoCaption_124223_Content_12 = {
    Text = "Bu yüzden \"başka diyara geçtiğimi\" fark etmedim bile."
  },
  AvgVideoCaption_124223_Content_120 = {
    Text = "Nasıl bir performans sergilemem gerektiğini bir düşüneyim..."
  },
  AvgVideoCaption_124223_Content_121 = {
    Text = "Yardım Edin!"
  },
  AvgVideoCaption_124223_Content_122 = {
    Text = "Hayır, tadı yetmiyor, daha fazla korkuya, daha fazla umutsuzluğa ihtiyacım var..."
  },
  AvgVideoCaption_124223_Content_123 = {Text = "Elbette"},
  AvgVideoCaption_124223_Content_124 = {
    Text = "Tıpkı o Hayatta Kalanların can verirkenki çığlıkları gibi."
  },
  AvgVideoCaption_124223_Content_125 = {
    Text = "Şimdi, \"Mouchette'in Öte Diyar Soruşturma Günlüğü\" burada son buluyor."
  },
  AvgVideoCaption_124223_Content_126 = {
    Text = "Başlamakta olan ise \"Masum Kurban Tarikatçıların Yuvasını İmha Eder\" adlı oyun."
  },
  AvgVideoCaption_124223_Content_127 = {
    Text = "Müfettiş, Yurduma dönmek için elimden geleni yapacağım."
  },
  AvgVideoCaption_124223_Content_128 = {
    Text = "Ama eğer plan başarısız olursa, endişelenme, çünkü ne olursa olsun,"
  },
  AvgVideoCaption_124223_Content_129 = {
    Text = "benim Can’ım görkemli bir Son Perde ile kapanacak."
  },
  AvgVideoCaption_124223_Content_13 = {
    Text = "Sadece, bir grup siyah cüppeli insanın aniden karşımda belirdiğini gördüm,"
  },
  AvgVideoCaption_124223_Content_130 = {
    Text = "O tarikatçıların çığlıkları en iyi alkış olacak."
  },
  AvgVideoCaption_124223_Content_14 = {
    Text = "Gümüş kaplama hançerler taşıyor ve \"kurban\" dedikleri insanları avlıyorlardı."
  },
  AvgVideoCaption_124223_Content_15 = {
    Text = "Ve o kurbanların çığlıkları, ağlayışları, başımın patlayacak gibi olmasına neden oluyordu."
  },
  AvgVideoCaption_124223_Content_16 = {
    Text = "Kapa çeneni, sessiz ol!"
  },
  AvgVideoCaption_124223_Content_17 = {
    Text = "Kimse beni hiç dinlemedi."
  },
  AvgVideoCaption_124223_Content_18 = {
    Text = "Omzuma saplanmış hançeri saymazsak tabii."
  },
  AvgVideoCaption_124223_Content_19 = {
    Text = "Görünen o ki siz selamı silahla vermeyi tercih ediyorsunuz?"
  },
  AvgVideoCaption_124223_Content_2 = {
    Text = "Günlük tutmak, anıları düzenlemeye ve akıl sağlığını korumaya yardım eder."
  },
  AvgVideoCaption_124223_Content_20 = {
    Text = "Ne tesadüf, ben de."
  },
  AvgVideoCaption_124223_Content_21 = {
    Text = "Gel de sevgili baltama bir merhaba de—"
  },
  AvgVideoCaption_124223_Content_22 = {
    Text = "Parlayan☆Kasırga!"
  },
  AvgVideoCaption_124223_Content_23 = {
    Text = "Bir bir, bir diğeri... Kimsenin bilmediği o koyu sisin içinde, gönlümce deşarj oluyorum♪"
  },
  AvgVideoCaption_124223_Content_24 = {
    Text = "Kafatasını çatlat, beyninin derinliklerine in, hadi bu takipte vakit öldürelim♪"
  },
  AvgVideoCaption_124223_Content_25 = {
    Text = "Sonunda, dünya sessiz."
  },
  AvgVideoCaption_124223_Content_26 = {
    Text = "Müfettiş’in ortalığı toparlamasını bekledim."
  },
  AvgVideoCaption_124223_Content_27 = {
    Text = "Acaba bu sefer \"dürtüsel davranış\" inceleme raporunu kaç kelimeyle yazmam gerekecek..."
  },
  AvgVideoCaption_124223_Content_28 = {
    Text = "Ama ikinci gün, üçüncü gün, dördüncü gün, kimse beni bulmaya gelmedi."
  },
  AvgVideoCaption_124223_Content_29 = {
    Text = "Sadece, yoğun sisin içindeki bilinmeyen Canavarlar durmadan başıma bela açıyordu."
  },
  AvgVideoCaption_124223_Content_3 = {
    Text = "Ha, akıl sağlığı mı?"
  },
  AvgVideoCaption_124223_Content_30 = {
    Text = "Lanet olsun, şu tipler bana yemek yiyecek biraz zaman bırakamaz mı?"
  },
  AvgVideoCaption_124223_Content_31 = {
    Text = "Benim de uyumam lazım, tamam mı!"
  },
  AvgVideoCaption_124223_Content_32 = {
    Text = "Ve bu Sis Felaketi, içinden yürüyüp çıkmamız ne kadar daha sürecek!"
  },
  AvgVideoCaption_124223_Content_33 = {
    Text = "Müfettiş, senin Mouchette’in açlıktan ölüyor, susuzluktan ölüyor,"
  },
  AvgVideoCaption_124223_Content_34 = {
    Text = "bu yalnızca sis canavarlarıyla dolu Sis Felaketi’nde yorgunluktan ölüyor."
  },
  AvgVideoCaption_124223_Content_35 = {
    Text = "Neredesin sen, şu Toprak üzerinde!"
  },
  AvgVideoCaption_124223_Content_36 = {
    Text = "Çok açım, çok susadım, çok yorgunum..."
  },
  AvgVideoCaption_124223_Content_37 = {
    Text = "Böyle ölmek fazla sıradan."
  },
  AvgVideoCaption_124223_Content_38 = {
    Text = "Hayatımın yakışıklı bir sonu olacağını sanmıştım..."
  },
  AvgVideoCaption_124223_Content_39 = {
    Text = "En önemli şey şu ki,"
  },
  AvgVideoCaption_124223_Content_4 = {
    Text = "Bu dünyaya akıl almaz bir şekilde sürüklendiğimden beri, aklımı yerinde tutamıyorum."
  },
  AvgVideoCaption_124223_Content_40 = {
    Text = "Yalnız... kalmak istemiyorum..."
  },
  AvgVideoCaption_124223_Content_41 = {
    Text = "Hmm, hangi güne kadar yazmıştım?"
  },
  AvgVideoCaption_124223_Content_42 = {
    Text = "Ah, Beşinci Gün."
  },
  AvgVideoCaption_124223_Content_43 = {
    Text = "Ben, Mouchette, hâlâ bu sıkıcı dünyada hayatta kalıyorum."
  },
  AvgVideoCaption_124223_Content_44 = {
    Text = "Sis Felaketi’ndeki \"yerli hayatta kalanlar\" beni kurtardı."
  },
  AvgVideoCaption_124223_Content_45 = {
    Text = "Birbirimizi ıskalayan onca lafın ardından,"
  },
  AvgVideoCaption_124223_Content_46 = {
    Text = "Sonunda \"başka bir dünyaya geçtiğimi\" fark ettim."
  },
  AvgVideoCaption_124223_Content_47 = {
    Text = "O günden sonra ne sıcak Fındıklı Kava Çayı, ne de mis kokulu Ravenlog Balık Yahnisi kaldı."
  },
  AvgVideoCaption_124223_Content_48 = {
    Text = "Sadece taş gibi sert kara ekmek ve kumla karışık bulanık su."
  },
  AvgVideoCaption_124223_Content_49 = {
    Text = "Ama aslında hiçbir şeyden şikâyet edemem."
  },
  AvgVideoCaption_124223_Content_5 = {
    Text = "Madem şimdilik geri dönemiyorum, bari vakit öldürmek için biraz eğlence bulayım..."
  },
  AvgVideoCaption_124223_Content_50 = {
    Text = "Sonuçta, bu kasaba dış dünyadan kopmuş durumda."
  },
  AvgVideoCaption_124223_Content_51 = {
    Text = "Sis Felaketi Herkes’i tuzağa düşürdü ve Herkes açlıktan zayıf düştü."
  },
  AvgVideoCaption_124223_Content_52 = {
    Text = "Ruh’ları, günbegün süren işkencede yavaş yavaş çöküyor."
  },
  AvgVideoCaption_124223_Content_53 = {
    Text = "Bence şu anki Can, \"özgürlüğü yitirmek\" dışında epey ilginç."
  },
  AvgVideoCaption_124223_Content_54 = {
    Text = "Canım sıkılınca dışarı çıkıp Canavarlar dövüyorum."
  },
  AvgVideoCaption_124223_Content_55 = {
    Text = "Ayrıca yeni erzaklar da getirebiliyorum, bir taşla iki kuş vurmuş oluyorum."
  },
  AvgVideoCaption_124223_Content_56 = {
    Text = "Şöyle diyelim, burası bir oyun alanı gibi."
  },
  AvgVideoCaption_124223_Content_57 = {
    Text = "Stres’i hafifleten Kadim Nesneler ve dinlenecek öte-dünya masalları var."
  },
  AvgVideoCaption_124223_Content_58 = {
    Text = "Ninni niyetine Herkes’in çöküşe ramak kalmış Mırıltılar’ı var."
  },
  AvgVideoCaption_124223_Content_59 = {
    Text = "Ara sıra, başları kanayana dek dövüşenleri görebiliyorum, gerçekten eğlenceli."
  },
  AvgVideoCaption_124223_Content_6 = {
    Text = "Günlük tutmak gibi sıkıcı bir şey yapacağım aklıma bile gelmezdi..."
  },
  AvgVideoCaption_124223_Content_60 = {
    Text = "Fazladan bir yudum su ya da fazladan bir ısırık ekmek için kavga etmeye ne değer, bilmiyorum."
  },
  AvgVideoCaption_124223_Content_61 = {
    Text = "Belki de bunların hiçbiri artık önemli değil."
  },
  AvgVideoCaption_124223_Content_62 = {
    Text = "Sadece içlerindeki paniği boşaltmak için bir sebep istiyorlar."
  },
  AvgVideoCaption_124223_Content_63 = {
    Text = "Gerçekten acınası ve sefil."
  },
  AvgVideoCaption_124223_Content_64 = {
    Text = "\"O olay\" yaşandığından beri ilk kez günlük yazıyorum."
  },
  AvgVideoCaption_124223_Content_65 = {
    Text = "Alex gözlerimin önünde öldü—"
  },
  AvgVideoCaption_124223_Content_66 = {
    Text = "Sis tarafından aşındırıldı, okyanusa karışan bir su damlası gibi eriyip bütünüyle yok oldu."
  },
  AvgVideoCaption_124223_Content_67 = {
    Text = "Bu ikinci Sis Aşınması vakası, yüksek Alarm gerektiriyor."
  },
  AvgVideoCaption_124223_Content_68 = {
    Text = "Daha fazla erzak toplamalı ve kalan Hayatta Kalanları sisin dışına götürmeliyim."
  },
  AvgVideoCaption_124223_Content_69 = {
    Text = "11. Gün, biraz kurutulmuş geyik eti, filizlenmiş patates ve pastırma buldum."
  },
  AvgVideoCaption_124223_Content_7 = {
    Text = "Boş ver, bunu da önceden yazılmış bir soruşturma raporu sayarım."
  },
  AvgVideoCaption_124223_Content_70 = {
    Text = "Pastırma lezzetli, ama Ravenlog Balık Yahnisi kadar iyi değil."
  },
  AvgVideoCaption_124223_Content_71 = {
    Text = "Yanında bir fincan sıcak Fındıklı Kava Çayı olsaydı daha da güzel olurdu, yazık."
  },
  AvgVideoCaption_124223_Content_72 = {Text = "13. Gün."},
  AvgVideoCaption_124223_Content_73 = {
    Text = "Biraz ekmek ve kurutulmuş geyik eti buldum, ama su yoktu."
  },
  AvgVideoCaption_124223_Content_74 = {
    Text = "Tüm kuyu suları yoğun sis tarafından kirletilmişti."
  },
  AvgVideoCaption_124223_Content_75 = {
    Text = "Ondan sonra,"
  },
  AvgVideoCaption_124223_Content_76 = {
    Text = "Anna öldü."
  },
  AvgVideoCaption_124223_Content_77 = {
    Text = "Sis tarafından aşındırılan bedeni, Herkesin gözleri önünde yok oldu."
  },
  AvgVideoCaption_124223_Content_78 = {
    Text = "16. Gün, hâlâ kurutulmuş geyik eti, yanına küçük bir torba yulaf ezmesi."
  },
  AvgVideoCaption_124223_Content_79 = {
    Text = "Küçük Betty ve küçük Susan yok artık."
  },
  AvgVideoCaption_124223_Content_8 = {
    Text = "Öyleyse, \"Mouchette'in Öte Dünya Soruşturma Günlüğü\" resmen dosyalanmıştır—"
  },
  AvgVideoCaption_124223_Content_80 = {
    Text = "Bundan böyle, artık yatma vakti masalı yok."
  },
  AvgVideoCaption_124223_Content_81 = {
    Text = "Onları duymaya ihtiyaç duyan Çocuklar artık burada değil."
  },
  AvgVideoCaption_124223_Content_82 = {
    Text = "17. Gün, hiçbir şey bulunamadı."
  },
  AvgVideoCaption_124223_Content_83 = {
    Text = "Charles'ın ruhu çöktü."
  },
  AvgVideoCaption_124223_Content_84 = {Text = "İntihar."},
  AvgVideoCaption_124223_Content_85 = {
    Text = "18. Gün, hiçbir şey bulunamadı."
  },
  AvgVideoCaption_124223_Content_86 = {
    Text = "21. Gün, kurutulmuş geyik eti, filizlenmiş patatesler... yine."
  },
  AvgVideoCaption_124223_Content_87 = {
    Text = "Ben ne yapıyorum böyle? Mouchette, amacını unuttun mu? Amacın Yurt’a dönmek."
  },
  AvgVideoCaption_124223_Content_88 = {
    Text = "Burada kabadayılık yapmak, o kurutulmuş geyik etlerini ve filizlenmiş patatesleri toplamak değil."
  },
  AvgVideoCaption_124223_Content_89 = {
    Text = "Lanet olsun bu kurutulmuş geyik etine de filizlenmiş patateslere de, varsın Cehennem’e gitsinler!"
  },
  AvgVideoCaption_124223_Content_9 = {
    Text = "Şu \"başka diyara geçiş\"in birinci gününü bir düşüneyim..."
  },
  AvgVideoCaption_124223_Content_90 = {
    Text = "Hayır, sakin ol, sakin ol."
  },
  AvgVideoCaption_124223_Content_91 = {
    Text = "Hâlâ üç Hayatta Kalan var."
  },
  AvgVideoCaption_124223_Content_92 = {
    Text = "Onları Sis menzilinin dışına çıkar, sonra Yurt’a dönme meselesini düşünürsün."
  },
  AvgVideoCaption_124223_Content_93 = {
    Text = "Hepsi bu, huysuzluk etme, Sis Felaketi’nin karşısında delirme."
  },
  AvgVideoCaption_124223_Content_94 = {
    Text = "Aaaaah—kus onları, hepsini bana kus!"
  },
  AvgVideoCaption_124223_Content_95 = {
    Text = "Seni öldüremeyeceğimi mi sanıyorsun? Hayır, hiçbir şeyden korkmuyorum, her şeyi aşabilirim."
  },
  AvgVideoCaption_124223_Content_96 = {
    Text = "Öyleyse onları geri ver, sana emrediyorum, onları geri ver!"
  },
  AvgVideoCaption_124223_Content_97 = {
    Text = "Kurtaramıyorum... neden bir tekini bile kurtaramıyorum..."
  },
  AvgVideoCaption_124223_Content_98 = {
    Text = "Yaptığım her şey tamamen anlamsızdı!"
  },
  AvgVideoCaption_124223_Content_99 = {
    Text = "Öyleyse, neden burada belirdim?"
  },
  AvgVideoCaption_126905_Content_1 = {
    Text = "Neden titriyorsun?"
  },
  AvgVideoCaption_126905_Content_10 = {
    Text = "Neyi seviyorsan gerçektir;"
  },
  AvgVideoCaption_126905_Content_100 = {
    Text = "Ben senin Mūmā’n mıyım, yoksa Bayan Xu muyum?"
  },
  AvgVideoCaption_126905_Content_101 = {
    Text = "Nānnān, hikâyeyi anladın."
  },
  AvgVideoCaption_126905_Content_102 = {
    Text = "Yapacağımız son bir şey kaldı."
  },
  AvgVideoCaption_126905_Content_103 = {
    Text = "Baba, tıpkı daha önce beni senden aldığı gibi,"
  },
  AvgVideoCaption_126905_Content_104 = {
    Text = "Birlikte olmamızı engellemek istiyor."
  },
  AvgVideoCaption_126905_Content_105 = {
    Text = "Beni parçalara ayırdı ve o şeyi elde etmek için kurban etti—"
  },
  AvgVideoCaption_126905_Content_106 = {
    Text = "Geyikleri ata, yalanları gerçeğe çeviren o şey."
  },
  AvgVideoCaption_126905_Content_107 = {
    Text = "Ama o şeyi yalnızca sana vereceğiz."
  },
  AvgVideoCaption_126905_Content_108 = {
    Text = "Ho Fong’u bir kenara at."
  },
  AvgVideoCaption_126905_Content_109 = {
    Text = "O rüyaları bir kenara at."
  },
  AvgVideoCaption_126905_Content_11 = {
    Text = "Neden nefret ediyorsan sahte kılınabilir."
  },
  AvgVideoCaption_126905_Content_110 = {
    Text = "Tamamen, bütünüyle... yanıma gel.\nTamamen, bütünüyle... Mūmā'na geri dön."
  },
  AvgVideoCaption_126905_Content_111 = {
    Text = "Ve sonra, bu tatlı armağanın sonsuza dek senin kalmasını sağlayacağım."
  },
  AvgVideoCaption_126905_Content_112 = {
    Text = "Biz seninle olacağız..."
  },
  AvgVideoCaption_126905_Content_113 = {
    Text = "...daima ve sonsuza dek."
  },
  AvgVideoCaption_126905_Content_12 = {Text = "Neden?"},
  AvgVideoCaption_126905_Content_13 = {
    Text = "Sanki dalıp gidiyormuşsun gibi görünüyorsun, küçük Yasemin’im."
  },
  AvgVideoCaption_126905_Content_14 = {
    Text = "Merak ediyorum, böyle bir anda bir insan anne ne yapardı?"
  },
  AvgVideoCaption_126905_Content_15 = {
    Text = "Sana bir uyku vakti hikâyesi anlatacağım."
  },
  AvgVideoCaption_126905_Content_16 = {
    Text = "Çok, çok uzun zaman önce,"
  },
  AvgVideoCaption_126905_Content_17 = {
    Text = "Doğunun en görkemli krallığında,"
  },
  AvgVideoCaption_126905_Content_18 = {
    Text = "Genç bir Kral tahtına oturmuştu."
  },
  AvgVideoCaption_126905_Content_19 = {
    Text = "O tahtın altında,"
  },
  AvgVideoCaption_126905_Content_2 = {
    Text = "Zavallı, acınası şey."
  },
  AvgVideoCaption_126905_Content_20 = {
    Text = "On binlerin üstünde, ama birinin ardından gelen bir Yüksek Vezir duruyordu."
  },
  AvgVideoCaption_126905_Content_21 = {
    Text = "Kralın gücüne göz dikmişti."
  },
  AvgVideoCaption_126905_Content_22 = {
    Text = "Krallıktaki her ruh bunu bilirdi,"
  },
  AvgVideoCaption_126905_Content_23 = {
    Text = "Ama beklediler; Kralın yanında mı, Vezirin ardında mı duracaklarına karar veremediler."
  },
  AvgVideoCaption_126905_Content_24 = {
    Text = "Bir “Neden?” daha."
  },
  AvgVideoCaption_126905_Content_25 = {
    Text = "Ah... ne kadar da baş belası bir insan yavrusu."
  },
  AvgVideoCaption_126905_Content_26 = {
    Text = "Çünkü Kalabalığın en sıkı nerede toplandığını görmek istiyorlardı."
  },
  AvgVideoCaption_126905_Content_27 = {
    Text = "Güç tuhaf bir şeydir; Güçlü olanı eşsiz kılar, zayıf olanı ise daha da sefil."
  },
  AvgVideoCaption_126905_Content_28 = {
    Text = "Başın yine mi ağrıyor?"
  },
  AvgVideoCaption_126905_Content_29 = {
    Text = "Yakında... yakında hastalığın iyileşecek."
  },
  AvgVideoCaption_126905_Content_3 = {
    Text = "Bu daha mı iyi hissettiriyor, küçük Yaseminim?"
  },
  AvgVideoCaption_126905_Content_30 = {
    Text = "Gel, yavrumu biraz olsun nasıl rahatlatacağımı bilirim."
  },
  AvgVideoCaption_126905_Content_31 = {
    Text = "Tek yapman gereken gevşemek..."
  },
  AvgVideoCaption_126905_Content_32 = {
    Text = "İşte böyle."
  },
  AvgVideoCaption_126905_Content_33 = {Text = "Şimdi..."},
  AvgVideoCaption_126905_Content_34 = {
    Text = "Nerede kalmıştık?"
  },
  AvgVideoCaption_126905_Content_35 = {
    Text = "Halkın seçme vakti çabucak geldi."
  },
  AvgVideoCaption_126905_Content_36 = {Text = "O gün,"},
  AvgVideoCaption_126905_Content_37 = {
    Text = "Yabancı bir tüccar nadir bir şey getirdi."
  },
  AvgVideoCaption_126905_Content_38 = {
    Text = "Dört çevik, ince toynağı vardı,"
  },
  AvgVideoCaption_126905_Content_39 = {
    Text = "Uzun bir çift boynuzla ve erik çiçeği benekleriyle alacalanmış bir postla birlikte."
  },
  AvgVideoCaption_126905_Content_4 = {
    Text = "Yaklaş bana."
  },
  AvgVideoCaption_126905_Content_40 = {
    Text = "Vezir konuştu:"
  },
  AvgVideoCaption_126905_Content_41 = {
    Text = "\"Majesteleri, sizin için Bin-Mil Giden bir At buldum—eşi benzeri olmayan bir at.\""
  },
  AvgVideoCaption_126905_Content_42 = {
    Text = "Elbette bir at değildi."
  },
  AvgVideoCaption_126905_Content_43 = {
    Text = "Kral da böyle söyledi."
  },
  AvgVideoCaption_126905_Content_44 = {
    Text = "\"Sevgili Vezirim, şaka yapıyorsunuz. Bu apaçık bir geyik.\""
  },
  AvgVideoCaption_126905_Content_45 = {
    Text = "Aşağıdaki saraylılar kendi aralarında fısıldaşıp mırıldandılar."
  },
  AvgVideoCaption_126905_Content_46 = {
    Text = "Ama Vezir yalnızca Kral’ın bakışına sakin gözlerle karşılık verip şöyle dedi,"
  },
  AvgVideoCaption_126905_Content_47 = {
    Text = "\"Hazretleri, bu bir at.\""
  },
  AvgVideoCaption_126905_Content_48 = {
    Text = "Vezir’in yanında duranlar da birer birer söze katılmaya başladılar."
  },
  AvgVideoCaption_126905_Content_49 = {
    Text = "\"Evet, bu bir at.\""
  },
  AvgVideoCaption_126905_Content_5 = {
    Text = "Senin için içine dinleneceğin bir bulut koparacağım..."
  },
  AvgVideoCaption_126905_Content_50 = {
    Text = "\"Bir at tam olarak böyle görünür.\""
  },
  AvgVideoCaption_126905_Content_51 = {
    Text = "\"Ne muazzam bir at! Böylesine soylu bir bineğe sahip olduğunuz için tebrikler, Majesteleri.\""
  },
  AvgVideoCaption_126905_Content_52 = {
    Text = "İster Vezir’in erişiminden duyulan dehşet yüzünden olsun, ister dalkavukların azgınlığından,"
  },
  AvgVideoCaption_126905_Content_53 = {
    Text = "Onun bir geyik olduğunu söyleyen az sayıdaki ses, hızla gelgitin içinde boğuldu."
  },
  AvgVideoCaption_126905_Content_54 = {
    Text = "Ve o gelgitin ortasında, herkesin gözleri önünde, geyik değişmeye başladı."
  },
  AvgVideoCaption_126905_Content_55 = {
    Text = "Erik çiçeği benekleri çatlayıp bölündü; boynuzları yumuşadı, soldu ve kopup düştü."
  },
  AvgVideoCaption_126905_Content_56 = {
    Text = "Kemikleri uzarken inledi."
  },
  AvgVideoCaption_126905_Content_57 = {
    Text = "Derisinden sızan kan, parmaklarının arasında pıhtılaşıp ağır toynaklara dönüştü."
  },
  AvgVideoCaption_126905_Content_58 = {
    Text = "Bu kanlı ucube salonda dikiliyordu,"
  },
  AvgVideoCaption_126905_Content_59 = {
    Text = "Grotesk, uyumsuz bir kişneme salıvererek."
  },
  AvgVideoCaption_126905_Content_6 = {
    Text = "Evet, Rüyasız Diyar’da böyle şeyler pek de hayret verici sayılmaz."
  },
  AvgVideoCaption_126905_Content_60 = {
    Text = "Vezir onu okşadı, soğukkanlı ve sakindi."
  },
  AvgVideoCaption_126905_Content_61 = {
    Text = "Kral, tahtında dehşetle donakaldı."
  },
  AvgVideoCaption_126905_Content_62 = {
    Text = "Halk sonunda nerede durması gerektiğini anladı."
  },
  AvgVideoCaption_126905_Content_63 = {
    Text = "O günden sonra,"
  },
  AvgVideoCaption_126905_Content_64 = {
    Text = "Ata dönüşmüş geyiğin çarpık gölgesi Kral’ı izliyordu."
  },
  AvgVideoCaption_126905_Content_65 = {
    Text = "Artık kimse Hazretleri’ni umursamadı."
  },
  AvgVideoCaption_126905_Content_66 = {
    Text = "Kimse onun düşüncelerini umursamadı."
  },
  AvgVideoCaption_126905_Content_67 = {
    Text = "Canavar onu eziyet ederken, boğazından kopan feryatlara kimse kulak asmadı."
  },
  AvgVideoCaption_126905_Content_68 = {
    Text = "Çünkü ister arzudan, ister dehşetten, ister soğuk bir hesaplamadan doğmuş olsun,"
  },
  AvgVideoCaption_126905_Content_69 = {
    Text = "Halk Vezir’in yanında durdu."
  },
  AvgVideoCaption_126905_Content_7 = {
    Text = "Bir kokusu var; yumuşak ve serin."
  },
  AvgVideoCaption_126905_Content_70 = {
    Text = "Onun bir at olduğunu söyledi, ve öyle oldu. Bir geyik bile attır."
  },
  AvgVideoCaption_126905_Content_71 = {
    Text = "Böylece Kral, Kral olarak kaldı..."
  },
  AvgVideoCaption_126905_Content_72 = {
    Text = "Sırf, ağzını açıp Kral’ın artık var olmadığını söylemediği içindi."
  },
  AvgVideoCaption_126905_Content_73 = {
    Text = "Küçük Yasemin, o hikâyede ne tattın?"
  },
  AvgVideoCaption_126905_Content_74 = {
    Text = "Heh heh... Hahahaha!"
  },
  AvgVideoCaption_126905_Content_75 = {
    Text = "Benim kıymetli bǎobèi’m,"
  },
  AvgVideoCaption_126905_Content_76 = {
    Text = "En sevgili, canım evladım."
  },
  AvgVideoCaption_126905_Content_77 = {
    Text = "Evet... bu tatlılık."
  },
  AvgVideoCaption_126905_Content_78 = {
    Text = "Kalabalık senin yanında olduğu sürece,"
  },
  AvgVideoCaption_126905_Content_79 = {
    Text = "Güç avuçlarının içinde olduğu sürece,"
  },
  AvgVideoCaption_126905_Content_8 = {
    Text = "Evet, tatlı sevgilim, elbette bu bir bulut."
  },
  AvgVideoCaption_126905_Content_80 = {
    Text = "Hakikat, Yalan—hatta Doğru ve Yanlış bile—yalnızca senin keyfince var olur."
  },
  AvgVideoCaption_126905_Content_81 = {
    Text = "Kralların ve sıradanların iradesi, yüzleştikleri dehşetler..."
  },
  AvgVideoCaption_126905_Content_82 = {
    Text = "Onların hiçbir önemi yok."
  },
  AvgVideoCaption_126905_Content_83 = {
    Text = "Bu şehir senin oyuncağın olacak."
  },
  AvgVideoCaption_126905_Content_84 = {
    Text = "Dünya... senin oyuncağın olacak."
  },
  AvgVideoCaption_126905_Content_85 = {
    Text = "Çok ama çok yorgunsun."
  },
  AvgVideoCaption_126905_Content_86 = {
    Text = "Tutunacak kesin bir şey istemektesin, ve neden istemeyesin ki?"
  },
  AvgVideoCaption_126905_Content_87 = {
    Text = "Güç emniyettir. Güç tatlılıktır, benim küçük Yasemin’im."
  },
  AvgVideoCaption_126905_Content_88 = {
    Text = "Eğer Onun bir bulut olduğuna inanırsan, O bir Bulut’tur."
  },
  AvgVideoCaption_126905_Content_89 = {
    Text = "Yanında birini istemen hâlinde, o kişi orada kalacaktır, daima ve sonsuza dek."
  },
  AvgVideoCaption_126905_Content_9 = {Text = "Şşş—"},
  AvgVideoCaption_126905_Content_90 = {Text = "Hm?"},
  AvgVideoCaption_126905_Content_91 = {
    Text = "Ah... bu fazla mı karmaşık?"
  },
  AvgVideoCaption_126905_Content_92 = {
    Text = "Ne kadar küçük, yumuşak, kırılgan bir şey."
  },
  AvgVideoCaption_126905_Content_93 = {
    Text = "Sırf ait olacağın bir yer için,"
  },
  AvgVideoCaption_126905_Content_94 = {
    Text = "Yalnızlıktan kaçış için,"
  },
  AvgVideoCaption_126905_Content_95 = {
    Text = "Her şeyi yapardın."
  },
  AvgVideoCaption_126905_Content_96 = {
    Text = "Gel. Kollarıma gel."
  },
  AvgVideoCaption_126905_Content_97 = {
    Text = "Rüyasız Diyar’dakilerin rüyalara ihtiyacı yoktur."
  },
  AvgVideoCaption_126905_Content_98 = {
    Text = "Gerçeklikte her şeye sahip olacaksın."
  },
  AvgVideoCaption_126905_Content_99 = {
    Text = "Neye inanıyorsun, benim Küçük Yasemin’im?"
  },
  AvgVideoCaption_131662_Content_1 = {
    Text = "Soğuk... çok soğuk..."
  },
  AvgVideoCaption_131662_Content_10 = {
    Text = "bilincin henüz @3 zihinsel uzamından ayrılmadığı muhtemeldir."
  },
  AvgVideoCaption_131662_Content_100 = {
    Text = "felaket... felaket... FELAKET..."
  },
  AvgVideoCaption_131662_Content_101 = {
    Text = "Koş, koş!"
  },
  AvgVideoCaption_131662_Content_102 = {
    Text = "Şimdi git, şimdi git!"
  },
  AvgVideoCaption_131662_Content_103 = {
    Text = "Kocaman ateş topu..."
  },
  AvgVideoCaption_131662_Content_104 = {
    Text = "otuzuncu kez..."
  },
  AvgVideoCaption_131662_Content_105 = {
    Text = "kırkıncı mı?"
  },
  AvgVideoCaption_131662_Content_106 = {
    Text = "Koş... bükülmüş,"
  },
  AvgVideoCaption_131662_Content_107 = {
    Text = "çok soğuk... çok soğuk..."
  },
  AvgVideoCaption_131662_Content_108 = {
    Text = "Dost... Coalsie..."
  },
  AvgVideoCaption_131662_Content_109 = {
    Text = "Özür dilerim... Çok özür dilerim..."
  },
  AvgVideoCaption_131662_Content_11 = {
    Text = "@3 gün sonra denek dilsel kavrayış sergiledi."
  },
  AvgVideoCaption_131662_Content_110 = {
    Text = "Girdap. Girdaba gitmeliyim."
  },
  AvgVideoCaption_131662_Content_111 = {
    Text = "Girdap... gidip onları kurtarmalıyım."
  },
  AvgVideoCaption_131662_Content_112 = {
    Text = "Vortice... onları kurtarmalıyım..."
  },
  AvgVideoCaption_131662_Content_113 = {
    Text = "Soğuk, soğuk!"
  },
  AvgVideoCaption_131662_Content_114 = {
    Text = "Gürültü ne kadar da yüksek!"
  },
  AvgVideoCaption_131662_Content_115 = {Text = "Ama..."},
  AvgVideoCaption_131662_Content_116 = {
    Text = "Vortice isteyecek! ONLARI KURTARACAK!"
  },
  AvgVideoCaption_131662_Content_117 = {
    Text = "Uyandırıcı O-1841"
  },
  AvgVideoCaption_131662_Content_118 = {
    Text = "Uyandırıcı O-1841"
  },
  AvgVideoCaption_131662_Content_119 = {
    Text = "beni duyabiliyor musun?"
  },
  AvgVideoCaption_131662_Content_12 = {
    Text = "Mythag Koleji'nin Uyandırma Bölümü temas protokollerini başlattı."
  },
  AvgVideoCaption_131662_Content_120 = {
    Text = "Farkedilmese de,"
  },
  AvgVideoCaption_131662_Content_121 = {
    Text = "@4 sensörleri, gücünüzün farkında olmadan çevredeki tüm maddeyi bozduğunu gösteriyor."
  },
  AvgVideoCaption_131662_Content_122 = {
    Text = "Bizi uyardığın için teşekkür ederiz."
  },
  AvgVideoCaption_131662_Content_123 = {
    Text = "Eğer iş birliği yapmaya hazırsan,"
  },
  AvgVideoCaption_131662_Content_124 = {
    Text = "Mythag sana yardım edebilir."
  },
  AvgVideoCaption_131662_Content_125 = {
    Text = "Sürekli olarak muhafaza aygıtlarını geliştirerek,"
  },
  AvgVideoCaption_131662_Content_126 = {
    Text = "girdabın enerjisini sınırlı bir alana aktarabilir ve boşaltabilirsiniz,"
  },
  AvgVideoCaption_131662_Content_127 = {
    Text = "onu etkisiz hâle getiriyoruz."
  },
  AvgVideoCaption_131662_Content_128 = {
    Text = "Girdap... transfer?"
  },
  AvgVideoCaption_131662_Content_129 = {
    Text = "Ama aktarım koordinatları mutlaka sizin üzerinizde merkezlenmiş olmalı."
  },
  AvgVideoCaption_131662_Content_13 = {
    Text = "Ah, ah... AAHHHHH—!"
  },
  AvgVideoCaption_131662_Content_130 = {
    Text = "Cihaz üzerinde sürekli kontrolü sürdürmek zorundasınız."
  },
  AvgVideoCaption_131662_Content_131 = {
    Text = "Girdap... transfer."
  },
  AvgVideoCaption_131662_Content_132 = {
    Text = "Yapamam... incitemem..."
  },
  AvgVideoCaption_131662_Content_133 = {
    Text = "arkadaşları incitemem... Coalsie!"
  },
  AvgVideoCaption_131662_Content_134 = {
    Text = "Moskstraumen"
  },
  AvgVideoCaption_131662_Content_135 = {Text = "transfer"},
  AvgVideoCaption_131662_Content_136 = {Text = "bana."},
  AvgVideoCaption_131662_Content_137 = {Text = "Bekle..."},
  AvgVideoCaption_131662_Content_138 = {
    Text = "Uyandıran O-1841, sen—"
  },
  AvgVideoCaption_131662_Content_139 = {
    Text = "Girdap... transfer... bana."
  },
  AvgVideoCaption_131662_Content_14 = {
    Text = "Sakin, sakin. Sakin ol."
  },
  AvgVideoCaption_131662_Content_140 = {
    Text = "Kimseye... zarar vermeyecek..."
  },
  AvgVideoCaption_131662_Content_141 = {
    Text = "Dalga biçimleri düz çizgiye döndü..."
  },
  AvgVideoCaption_131662_Content_142 = {
    Text = "Gücü kendi bedenine mi aktardın?"
  },
  AvgVideoCaption_131662_Content_143 = {Text = "Ama..."},
  AvgVideoCaption_131662_Content_144 = {
    Text = "aklın alamayacağı bir Pain çekeceksin..."
  },
  AvgVideoCaption_131662_Content_145 = {Text = "Vortice"},
  AvgVideoCaption_131662_Content_146 = {
    Text = "Korkmuyorum."
  },
  AvgVideoCaption_131662_Content_147 = {
    Text = "Coalsie... sarılma."
  },
  AvgVideoCaption_131662_Content_148 = {
    Text = "Coalsie... bir sarılma... mutlu!"
  },
  AvgVideoCaption_131662_Content_149 = {
    Text = "Vortice... mutlu!"
  },
  AvgVideoCaption_131662_Content_15 = {
    Text = "Sana zarar vermeyeceğim."
  },
  AvgVideoCaption_131662_Content_16 = {
    Text = "Beni anlayabiliyorsun, değil mi?"
  },
  AvgVideoCaption_131662_Content_17 = {
    Text = "Endişelenme; burada güvendesin."
  },
  AvgVideoCaption_131662_Content_18 = {
    Text = "Biz bir araştırma enstitüsündeniz—ben Araştırmacı Irene Caldwell."
  },
  AvgVideoCaption_131662_Content_19 = {
    Text = "O girdapta sana ne oldu?"
  },
  AvgVideoCaption_131662_Content_2 = {
    Text = "Sesler, sesler... ne kadar sessiz..."
  },
  AvgVideoCaption_131662_Content_20 = {
    Text = "Olayı yeniden kurgulayabilmemiz için bilgilerinize acilen ihtiyacımız var."
  },
  AvgVideoCaption_131662_Content_21 = {
    Text = "Lütfen, bu güçlendirilmiş Gümüş Çekirdek mikrofona konuşun."
  },
  AvgVideoCaption_131662_Content_22 = {
    Text = "İçeriği daha sonra @1 teknolojisini kullanarak çözümlemeye çalışacağız."
  },
  AvgVideoCaption_131662_Content_23 = {Text = "Ne oldu..."},
  AvgVideoCaption_131662_Content_24 = {Text = "Gemi,"},
  AvgVideoCaption_131662_Content_25 = {
    Text = "deniz suyu..."
  },
  AvgVideoCaption_131662_Content_26 = {
    Text = "suda gemi..."
  },
  AvgVideoCaption_131662_Content_27 = {
    Text = "dönüyor, dönüyor..."
  },
  AvgVideoCaption_131662_Content_28 = {
    Text = "Düş, asla düşme. Ne yukarı, ne aşağı, ne sol, ne sağ... yok,"
  },
  AvgVideoCaption_131662_Content_29 = {
    Text = "her şey dönüyor..."
  },
  AvgVideoCaption_131662_Content_3 = {
    Text = "Hareketsiz. Hareketsiz. Hareketsiz. Hareketsiz. Hareketsiz. Hareketsiz."
  },
  AvgVideoCaption_131662_Content_30 = {
    Text = "...hatırlamak istemiyorum; artık orada değilim."
  },
  AvgVideoCaption_131662_Content_31 = {Text = "Bu iyi..."},
  AvgVideoCaption_131662_Content_32 = {
    Text = "Ama... ama... kulaklarımda, ses hâlâ orada..."
  },
  AvgVideoCaption_131662_Content_33 = {Text = "Neden?"},
  AvgVideoCaption_131662_Content_34 = {
    Text = "Ses yok... girdap... ses yok."
  },
  AvgVideoCaption_131662_Content_35 = {
    Text = "Ama Vortice’nin kulaklarında ses var—kocaman, kocaman bir ses!"
  },
  AvgVideoCaption_131662_Content_36 = {
    Text = "Vortice... Vortice umut eder ki... bu ses Vortice’nin kafasının içindeki bir ses değildir..."
  },
  AvgVideoCaption_131662_Content_37 = {
    Text = "Ne tuhaf... ama neden? Coalsie, biliyor musun?"
  },
  AvgVideoCaption_131662_Content_38 = {
    Text = "Ah... ah... doğru..."
  },
  AvgVideoCaption_131662_Content_39 = {Text = "Ben..."},
  AvgVideoCaption_131662_Content_4 = {
    Text = "Burası neresi? Ben neredeyim? Ses... sıcaklık... ver bana..."
  },
  AvgVideoCaption_131662_Content_40 = {
    Text = "artık orada değilim."
  },
  AvgVideoCaption_131662_Content_41 = {
    Text = "Artık Coalsie yok."
  },
  AvgVideoCaption_131662_Content_42 = {
    Text = "Su, su... ama su..."
  },
  AvgVideoCaption_131662_Content_43 = {
    Text = "kulaklar, su..."
  },
  AvgVideoCaption_131662_Content_44 = {
    Text = "My-thag'dayım..."
  },
  AvgVideoCaption_131662_Content_45 = {
    Text = "ama güneş, güneş... ne kadar parlak..."
  },
  AvgVideoCaption_131662_Content_46 = {
    Text = "Güneş, yine parlak."
  },
  AvgVideoCaption_131662_Content_47 = {
    Text = "Mama Papa dedi ki... güneş parlak, gölgeler, yönler."
  },
  AvgVideoCaption_131662_Content_48 = {
    Text = "Dönüyor, dönüyor... gölgeler, dönüyor."
  },
  AvgVideoCaption_131662_Content_49 = {
    Text = "Hayır! Hayır!! HAYIR!!! Gölgeler dönmez!!!!"
  },
  AvgVideoCaption_131662_Content_5 = {
    Text = "Coalsie... Nautila...!"
  },
  AvgVideoCaption_131662_Content_50 = {
    Text = "Yukarı! Aşağı! Herkes dönüyor! HERKES DÖNÜYOR!!!!!!"
  },
  AvgVideoCaption_131662_Content_51 = {
    Text = "Hayır! Hayır!! Neden?! NEDEN?!"
  },
  AvgVideoCaption_131662_Content_52 = {
    Text = "Kaçtım! KAÇTIM!"
  },
  AvgVideoCaption_131662_Content_53 = {
    Text = "Ben... kaçtım..."
  },
  AvgVideoCaption_131662_Content_54 = {Text = "Mythag..."},
  AvgVideoCaption_131662_Content_55 = {Text = "oda..."},
  AvgVideoCaption_131662_Content_56 = {
    Text = "güneş parlak..."
  },
  AvgVideoCaption_131662_Content_57 = {
    Text = "on üç kere..."
  },
  AvgVideoCaption_131662_Content_58 = {
    Text = "Hayır, hayır, odada pencere yok!"
  },
  AvgVideoCaption_131662_Content_59 = {
    Text = "Kocaman ateş topu..."
  },
  AvgVideoCaption_131662_Content_6 = {
    Text = "Uyandırıcı O-1841"
  },
  AvgVideoCaption_131662_Content_60 = {
    Text = "PARLAMAYACAK! PARLAMAYACAK!"
  },
  AvgVideoCaption_131662_Content_61 = {
    Text = "AAAAAAAAAAHHH—!"
  },
  AvgVideoCaption_131662_Content_62 = {
    Text = "Girdap! Girdap! Su! Su!"
  },
  AvgVideoCaption_131662_Content_63 = {
    Text = "İçimde! Su! O! Su!"
  },
  AvgVideoCaption_131662_Content_64 = {
    Text = "Hâlâ burada! Hâlâ burada! Girdap biliyor!"
  },
  AvgVideoCaption_131662_Content_65 = {
    Text = "Girdap biliyor, O hâlâ burada!"
  },
  AvgVideoCaption_131662_Content_66 = {
    Text = "Kurtar beni... kurtar Girdap’ı..."
  },
  AvgVideoCaption_131662_Content_67 = {
    Text = "Hayır, Girdap kayboldu..."
  },
  AvgVideoCaption_131662_Content_68 = {
    Text = "Ben... kayboldum..."
  },
  AvgVideoCaption_131662_Content_69 = {Text = "Ah!"},
  AvgVideoCaption_131662_Content_7 = {
    Text = "Moskstraumen Girdabı'nın altındaki aşındırıcı bir yarıktan çıkarılan Gümüş Çekirdek."
  },
  AvgVideoCaption_131662_Content_70 = {
    Text = "ah, ah, AAAAAAAAAAAAHHHHHHHHH!!!!!!"
  },
  AvgVideoCaption_131662_Content_71 = {
    Text = "Hah, hah..."
  },
  AvgVideoCaption_131662_Content_72 = {
    Text = "kaçış... koşu..."
  },
  AvgVideoCaption_131662_Content_73 = {
    Text = "beni geri koy... at beni... uzağa... uzağa..."
  },
  AvgVideoCaption_131662_Content_74 = {
    Text = "Girdap... kimseye zarar vermek istemiyor..."
  },
  AvgVideoCaption_131662_Content_75 = {
    Text = "Girdap korkuyor... yalnız..."
  },
  AvgVideoCaption_131662_Content_76 = {
    Text = "ama... herkes ölüyor..."
  },
  AvgVideoCaption_131662_Content_77 = {
    Text = "Gülüşler, yemek, bana veriyorlar..."
  },
  AvgVideoCaption_131662_Content_78 = {
    Text = "ama onları alamıyorum."
  },
  AvgVideoCaption_131662_Content_79 = {
    Text = "Gitmeliyim, gitmeliyim! Yoksa,"
  },
  AvgVideoCaption_131662_Content_8 = {
    Text = "Başlangıçta, O-1841 büyük ölçüde katatonikti ve güçlü yıkıcı eğilimler sergiliyordu."
  },
  AvgVideoCaption_131662_Content_80 = {
    Text = "boğulacağım..."
  },
  AvgVideoCaption_131662_Content_81 = {
    Text = "Coalsie, görmek istiyor."
  },
  AvgVideoCaption_131662_Content_82 = {
    Text = "Dost, görmek istiyor..."
  },
  AvgVideoCaption_131662_Content_83 = {
    Text = "ama Coalsie yok..."
  },
  AvgVideoCaption_131662_Content_84 = {
    Text = "dost yok..."
  },
  AvgVideoCaption_131662_Content_85 = {
    Text = "hayır... yapma... yapma..."
  },
  AvgVideoCaption_131662_Content_86 = {
    Text = "Lütfen sakin ol, Girdap."
  },
  AvgVideoCaption_131662_Content_87 = {
    Text = "Mythag Uyandırma Araştırma Merkezi’ndesin."
  },
  AvgVideoCaption_131662_Content_88 = {
    Text = "Burada çok güvendesin."
  },
  AvgVideoCaption_131662_Content_89 = {
    Text = "Konuşmanı ön inceleme ile çözdük,"
  },
  AvgVideoCaption_131662_Content_9 = {
    Text = "Ara sıra denek @2 dilinde mırıldanarak şiddetli Sayıklama belirtileri gösterdi;"
  },
  AvgVideoCaption_131662_Content_90 = {
    Text = "ama birçok terim hâlâ karanlık."
  },
  AvgVideoCaption_131662_Content_91 = {
    Text = "Bu yüzden, bizim—"
  },
  AvgVideoCaption_131662_Content_92 = {
    Text = "Hayır... hayır, yüzler! Yüzler!"
  },
  AvgVideoCaption_131662_Content_93 = {
    Text = "Yüz yok! Göremiyorum!"
  },
  AvgVideoCaption_131662_Content_94 = {
    Text = "Su örtmüş... bükülmüş! Onları göremiyorum!"
  },
  AvgVideoCaption_131662_Content_95 = {
    Text = "Canavarlar! Canavarlar! HAYIIIIIIIR!!!!!"
  },
  AvgVideoCaption_131662_Content_96 = {
    Text = "Siz... iyi insanlar..."
  },
  AvgVideoCaption_131662_Content_97 = {
    Text = "canavarlar... canavarlar..."
  },
  AvgVideoCaption_131662_Content_98 = {
    Text = "Normal yüzler..."
  },
  AvgVideoCaption_131662_Content_99 = {
    Text = "bükülmüş... girdap..."
  },
  AvgVideoCaption_134291_Content_1 = {Text = "Kader"},
  AvgVideoCaption_134291_Content_10 = {
    Text = "Kendi ellerimle dokunmuşlardı"
  },
  AvgVideoCaption_134291_Content_11 = {Text = "Onlar…"},
  AvgVideoCaption_134291_Content_12 = {
    Text = "Hehehehe…"
  },
  AvgVideoCaption_134291_Content_13 = {
    Text = "Kimse Kadere karşı gelemez, sevgili ablacığım"
  },
  AvgVideoCaption_134291_Content_14 = {
    Text = "Hepimiz bir sonraki ipliğe parçalanacağız"
  },
  AvgVideoCaption_134291_Content_15 = {
    Text = "Tüm kaderler çoktan tayin edildi"
  },
  AvgVideoCaption_134291_Content_16 = {
    Text = "Yargılayan"
  },
  AvgVideoCaption_134291_Content_17 = {Text = "Kurtaran"},
  AvgVideoCaption_134291_Content_18 = {Text = "Efendi"},
  AvgVideoCaption_134291_Content_19 = {Text = "Tutsak…"},
  AvgVideoCaption_134291_Content_2 = {
    Text = "Küçük ve Kırılgan bir tanrı"
  },
  AvgVideoCaption_134291_Content_20 = {
    Text = "Bana ait olan rol"
  },
  AvgVideoCaption_134291_Content_21 = {
    Text = "Asla benim seçimim değildi"
  },
  AvgVideoCaption_134291_Content_22 = {
    Text = "Ama senin seçimin de değildi…"
  },
  AvgVideoCaption_134291_Content_23 = {
    Text = "Sevgili Kader"
  },
  AvgVideoCaption_134291_Content_24 = {
    Text = "Benimle birlikte adım at"
  },
  AvgVideoCaption_134291_Content_25 = {
    Text = "Bize kader olarak çizilen sahneye"
  },
  AvgVideoCaption_134291_Content_3 = {
    Text = "Sayısız iplik serdiler"
  },
  AvgVideoCaption_134291_Content_4 = {
    Text = "Dünya için önceden belirlenmiş Yollar ördüler"
  },
  AvgVideoCaption_134291_Content_5 = {
    Text = "Çocuklar için en yumuşak Beşiği dokudular"
  },
  AvgVideoCaption_134291_Content_6 = {Text = "Şiir"},
  AvgVideoCaption_134291_Content_7 = {Text = "Dans"},
  AvgVideoCaption_134291_Content_8 = {Text = "Savaş…"},
  AvgVideoCaption_134291_Content_9 = {
    Text = "Sıradan günler"
  },
  AvgVideoCaption_134292_Content_1 = {
    Text = "Gel yanıma otur, Nefraea."
  },
  AvgVideoCaption_134292_Content_10 = {
    Text = "sahnedeki kadın çok hüzünlü görünüyor..."
  },
  AvgVideoCaption_134292_Content_100 = {
    Text = "Bu bedel..."
  },
  AvgVideoCaption_134292_Content_101 = {
    Text = "dayanılmaz bir ağırlıkta olsa bile."
  },
  AvgVideoCaption_134292_Content_102 = {
    Text = "Yani sonsuza dek tezgâhın başında kalmayı mı tercih ediyorsun,"
  },
  AvgVideoCaption_134292_Content_103 = {
    Text = "sadece dünyayı karanlığa düşmekten korumak için..."
  },
  AvgVideoCaption_134292_Content_104 = {
    Text = "Bazen merak ediyorum..."
  },
  AvgVideoCaption_134292_Content_105 = {
    Text = "sence çok mu inatçıyım?"
  },
  AvgVideoCaption_134292_Content_106 = {
    Text = "Seni anlıyorum, ablacığım..."
  },
  AvgVideoCaption_134292_Content_107 = {
    Text = "Sadece—böyle acı çektiğini görmek istemiyorum."
  },
  AvgVideoCaption_134292_Content_108 = {
    Text = "Bu, tek başına taşıman gereken bir şey olmamalı..."
  },
  AvgVideoCaption_134292_Content_109 = {
    Text = "Ablacığım,"
  },
  AvgVideoCaption_134292_Content_11 = {
    Text = "Sevdiği biri tarafından mı terk edilmiş?"
  },
  AvgVideoCaption_134292_Content_110 = {
    Text = "bugün beni buraya bu operayı izlemem için getirdin..."
  },
  AvgVideoCaption_134292_Content_111 = {
    Text = "bana söylemek istediğin bu muydu?"
  },
  AvgVideoCaption_134292_Content_112 = {
    Text = "Kader benim ebedi kafesim, Nefraea."
  },
  AvgVideoCaption_134292_Content_113 = {
    Text = "Sonunda tek istediğim, yalnızlığımı görmen..."
  },
  AvgVideoCaption_134292_Content_114 = {
    Text = "gerçekten güvendiğim tek ruh olarak."
  },
  AvgVideoCaption_134292_Content_115 = {Text = "Güven mi?"},
  AvgVideoCaption_134292_Content_116 = {
    Text = "Ama... ben hep senin ipliklerini karıştırıyor gibiyim."
  },
  AvgVideoCaption_134292_Content_117 = {
    Text = "Bilerek yapmıyorum..."
  },
  AvgVideoCaption_134292_Content_118 = {
    Text = "ama her sana yaklaştığımda, bir şeyleri bozuyorum..."
  },
  AvgVideoCaption_134292_Content_119 = {
    Text = "O düzgün, parlayan iplikler—"
  },
  AvgVideoCaption_134292_Content_12 = {
    Text = "İnsanın acısı"
  },
  AvgVideoCaption_134292_Content_120 = {
    Text = "ben yakınındayken hep çözülüyorlar..."
  },
  AvgVideoCaption_134292_Content_121 = {
    Text = "Özür dilerim, ablacığım. Neden olduğunu bilmiyorum..."
  },
  AvgVideoCaption_134292_Content_122 = {
    Text = "Güzelliğin hiçbir zaman senin suçun olmadı,"
  },
  AvgVideoCaption_134292_Content_123 = {
    Text = "Çünkü sen güzelsin, Nefraea."
  },
  AvgVideoCaption_134292_Content_124 = {
    Text = "Ve bu kader kafesi, güzel şeyleri kıskanır."
  },
  AvgVideoCaption_134292_Content_125 = {
    Text = "Ha... haha... hahaha..."
  },
  AvgVideoCaption_134292_Content_126 = {
    Text = "sevgili ablam."
  },
  AvgVideoCaption_134292_Content_127 = {
    Text = "Sana olan sevgim, sana olan ilgim—ne kadar farklı olursak olalım, hiçbiri asla azalmadı."
  },
  AvgVideoCaption_134292_Content_128 = {
    Text = "Gözettiğim tüm hayatları derinden seviyorum,"
  },
  AvgVideoCaption_134292_Content_129 = {
    Text = "tıpkı seni sevdiğim gibi—beni gerçekten anlayan tek kişi..."
  },
  AvgVideoCaption_134292_Content_13 = {
    Text = "aşktan ve terk edilmekten çok daha derinlere uzanır,"
  },
  AvgVideoCaption_134292_Content_130 = {
    Text = "Teşekkür ederim, ablacığım..."
  },
  AvgVideoCaption_134292_Content_131 = {
    Text = "...O halde şimdi uyu, ölümün içinde, sevgili kardeşim."
  },
  AvgVideoCaption_134292_Content_132 = {
    Text = "A-ablacığım?"
  },
  AvgVideoCaption_134292_Content_133 = {
    Text = "Neden... <Italic:neden?>"
  },
  AvgVideoCaption_134292_Content_134 = {
    Text = "Beni bağışla, Nefraea..."
  },
  AvgVideoCaption_134292_Content_135 = {
    Text = "Kader ağını korumak için,"
  },
  AvgVideoCaption_134292_Content_136 = {
    Text = "yanlış yöne gideni koparmam gerekiyor."
  },
  AvgVideoCaption_134292_Content_137 = {
    Text = "Katlanılmaz bedel... öyleyse..."
  },
  AvgVideoCaption_134292_Content_138 = {
    Text = "Ödemek zorunda olduğun bedel benim, öyle mi?"
  },
  AvgVideoCaption_134292_Content_139 = {
    Text = "Heh... Heheheh..."
  },
  AvgVideoCaption_134292_Content_14 = {
    Text = "sevgili Nefraea."
  },
  AvgVideoCaption_134292_Content_140 = {
    Text = "Büyüklüğe götüreni seç,"
  },
  AvgVideoCaption_134292_Content_141 = {
    Text = "kirli ve önemsiz olanı at—"
  },
  AvgVideoCaption_134292_Content_142 = {
    Text = "bu sensin, değil mi... her zaman senin tercihin bu oldu..."
  },
  AvgVideoCaption_134292_Content_143 = {
    Text = "İkiyüzlü. Hain... Bana ihanet ettin..."
  },
  AvgVideoCaption_134292_Content_144 = {
    Text = "Bana ihanet ettin..."
  },
  AvgVideoCaption_134292_Content_145 = {
    Text = "Kendine ihanet ettin, kız kardeşim..."
  },
  AvgVideoCaption_134292_Content_146 = {
    Text = "Benden nefret et."
  },
  AvgVideoCaption_134292_Content_147 = {
    Text = "Beni terk et."
  },
  AvgVideoCaption_134292_Content_148 = {
    Text = "Değer verdiklerin için acı çekmek zorunda olmadığın bir yere git,"
  },
  AvgVideoCaption_134292_Content_149 = {Text = "Nefraea..."},
  AvgVideoCaption_134292_Content_15 = {Text = "O..."},
  AvgVideoCaption_134292_Content_150 = {
    Text = "Bu— <Italic:tüm bunlar>—kaçamayacağım kader bu."
  },
  AvgVideoCaption_134292_Content_151 = {
    Text = "İkiyüzlü. Hain... Bana ihanet ettin..."
  },
  AvgVideoCaption_134292_Content_152 = {
    Text = "Bana ihanet ettin..."
  },
  AvgVideoCaption_134292_Content_153 = {
    Text = "Kendine ihanet ettin!"
  },
  AvgVideoCaption_134292_Content_154 = {
    Text = "Bir gün değer verdiğin her şeyi yok edeceksin..."
  },
  AvgVideoCaption_134292_Content_155 = {
    Text = "kendine yalan söylediğin bu kaderle birlikte... kız kardeşim..."
  },
  AvgVideoCaption_134292_Content_156 = {
    Text = "Benden nefret et, Nefraea."
  },
  AvgVideoCaption_134292_Content_157 = {
    Text = "Ama bu dünyanın barındırdığı her lütuf"
  },
  AvgVideoCaption_134292_Content_158 = {
    Text = "sonunda merhamet göstermeyen bir kaderle karşılığını bulacak."
  },
  AvgVideoCaption_134292_Content_159 = {
    Text = "Çark dönüyor. Her zaman döndü."
  },
  AvgVideoCaption_134292_Content_16 = {
    Text = "Ağlıyor... kader karşısındaki çaresizliği için."
  },
  AvgVideoCaption_134292_Content_160 = {
    Text = "Seni bırakmaktan başka çarem yok—tekrar, tekrar ve tekrar."
  },
  AvgVideoCaption_134292_Content_161 = {
    Text = "Yine de, neden dokuduğumu hatırladığım sürece..."
  },
  AvgVideoCaption_134292_Content_162 = {
    Text = "senin anlayışın olmadan bile,"
  },
  AvgVideoCaption_134292_Content_163 = {
    Text = "her şeyden vazgeçmiş olsam bile—"
  },
  AvgVideoCaption_134292_Content_164 = {
    Text = "yine de yapardım."
  },
  AvgVideoCaption_134292_Content_165 = {
    Text = "Bu, Dokuyucu olarak taşıdığım yük."
  },
  AvgVideoCaption_134292_Content_166 = {
    Text = "Bu, yürümek zorunda olduğum yalnızlık."
  },
  AvgVideoCaption_134292_Content_167 = {
    Text = "Bırak kader..."
  },
  AvgVideoCaption_134292_Content_168 = {
    Text = "ikimizi de sonsuza dek birbirimize bağlasın."
  },
  AvgVideoCaption_134292_Content_17 = {
    Text = "Pek akıllı birine benzemiyor."
  },
  AvgVideoCaption_134292_Content_18 = {
    Text = "Tek yapması gereken senin gibi birine dua etmek—kaderi değiştirebilecek birine."
  },
  AvgVideoCaption_134292_Content_19 = {
    Text = "Değil mi, ablacığım?"
  },
  AvgVideoCaption_134292_Content_2 = {
    Text = "Ablacığım, beni tiyatrona ilk kez getiriyorsun!"
  },
  AvgVideoCaption_134292_Content_20 = {
    Text = "Kader bana örme gücünü bahşetti."
  },
  AvgVideoCaption_134292_Content_21 = {
    Text = "Ama her ruha huzurunu vermek... bu benim bile gücümü aşar."
  },
  AvgVideoCaption_134292_Content_22 = {
    Text = "Bu dünyada güzel kaderler var."
  },
  AvgVideoCaption_134292_Content_23 = {
    Text = "Ama her zaman, başka birinin yerine, başka yere düşmesi gereken çılgınlığı ve yıkımı taşımak zorunda kalanlar olur."
  },
  AvgVideoCaption_134292_Content_24 = {
    Text = "Bu kader ağını ben örüyorum,"
  },
  AvgVideoCaption_134292_Content_25 = {
    Text = "sayısız hayatın sevinçlerini ve acılarını ipliğe eğiriyorum."
  },
  AvgVideoCaption_134292_Content_26 = {
    Text = "Ama her şey söylenip yapıldığında..."
  },
  AvgVideoCaption_134292_Content_27 = {
    Text = "Kendi senaryomda beceriksiz bir oyuncudan başka bir şey değilim."
  },
  AvgVideoCaption_134292_Content_28 = {
    Text = "Bu doğru olamaz—"
  },
  AvgVideoCaption_134292_Content_29 = {
    Text = "sen kadere hükmeden birisin, ablacığım!"
  },
  AvgVideoCaption_134292_Content_3 = {
    Text = "Ne izleyeceğiz? Bir oyun mu? Bir bale mi?"
  },
  AvgVideoCaption_134292_Content_30 = {
    Text = "Her ipliğin ucunda kaotik boşluk yatar."
  },
  AvgVideoCaption_134292_Content_31 = {
    Text = "Kaderin efendisi"
  },
  AvgVideoCaption_134292_Content_32 = {
    Text = "sonunda yalnızca onun hizmetkârıdır..."
  },
  AvgVideoCaption_134292_Content_33 = {Text = "Nefraea..."},
  AvgVideoCaption_134292_Content_34 = {Text = "Nefraea,"},
  AvgVideoCaption_134292_Content_35 = {
    Text = "belki de..."
  },
  AvgVideoCaption_134292_Content_36 = {
    Text = "bu yalnızlığı gerçekten anlayabilecek tek kişi sensin."
  },
  AvgVideoCaption_134292_Content_37 = {
    Text = "Demek senin bile... yapamadığın şeyler var..."
  },
  AvgVideoCaption_134292_Content_38 = {
    Text = "Her şeyi tam olarak anlamıyorum..."
  },
  AvgVideoCaption_134292_Content_39 = {
    Text = "ama ne olursa olsun,"
  },
  AvgVideoCaption_134292_Content_4 = {
    Text = "Söyle bana!"
  },
  AvgVideoCaption_134292_Content_40 = {
    Text = "her zaman yanında olacağım, ablacığım!"
  },
  AvgVideoCaption_134292_Content_41 = {
    Text = "Sanırım anlamaya başlıyorum, ablacığım..."
  },
  AvgVideoCaption_134292_Content_42 = {Text = "Abla..."},
  AvgVideoCaption_134292_Content_43 = {
    Text = "Bu şarkıcı—"
  },
  AvgVideoCaption_134292_Content_44 = {
    Text = "gidecek yeri olmayan solmuş bir yaprak,"
  },
  AvgVideoCaption_134292_Content_45 = {
    Text = "kaderin uygun gördüğü yere savrulan..."
  },
  AvgVideoCaption_134292_Content_46 = {
    Text = "Ne kadar da acı..."
  },
  AvgVideoCaption_134292_Content_47 = {Text = "Nefraea..."},
  AvgVideoCaption_134292_Content_48 = {
    Text = "Eğer yazmak sana düşseydi,"
  },
  AvgVideoCaption_134292_Content_49 = {
    Text = "ona nasıl bir kader biçerdin?"
  },
  AvgVideoCaption_134292_Content_5 = {
    Text = "Sus. Başlamak üzere."
  },
  AvgVideoCaption_134292_Content_50 = {
    Text = "Hmm. Sanırım ona tüm trajedilerin en büyüğünü yazardım!"
  },
  AvgVideoCaption_134292_Content_51 = {
    Text = "Bir kenara atılmış bir kadın."
  },
  AvgVideoCaption_134292_Content_52 = {
    Text = "Bir başkasının gölgesinde durmak için yazılmış bir figüran..."
  },
  AvgVideoCaption_134292_Content_53 = {
    Text = "Hikâyesini yeniden yazacak olsam, her şeyi ateşe verirdim—"
  },
  AvgVideoCaption_134292_Content_54 = {
    Text = "ona acı veren her şeyi, onu bağlayan her şeyi,"
  },
  AvgVideoCaption_134292_Content_55 = {
    Text = "son zerresine kadar her adaletsizliği—hepsini küle çevirirdim!"
  },
  AvgVideoCaption_134292_Content_56 = {
    Text = "Kederli bir şey, azgın bir şey—gürültü ve çöküşle dolu..."
  },
  AvgVideoCaption_134292_Content_57 = {
    Text = "O tür bir güzellik, kendini hiçliğe kadar yakan türden,"
  },
  AvgVideoCaption_134292_Content_58 = {
    Text = "ona yakışan tek son bu!"
  },
  AvgVideoCaption_134292_Content_59 = {
    Text = "Evet. İşte orada, Nefraea."
  },
  AvgVideoCaption_134292_Content_6 = {
    Text = "Bu gece... bir opera var."
  },
  AvgVideoCaption_134292_Content_60 = {
    Text = "Sen hâlâ inanıyorsun"
  },
  AvgVideoCaption_134292_Content_61 = {
    Text = "kaderin yıkımla sona ermesi gerektiğine."
  },
  AvgVideoCaption_134292_Content_62 = {
    Text = "Kalbinde taşıdığın güzel bir hayal uğruna—"
  },
  AvgVideoCaption_134292_Content_63 = {
    Text = "mükemmel bir son uğruna—"
  },
  AvgVideoCaption_134292_Content_64 = {
    Text = "dünyanın yıkımla son bulmasına değer..."
  },
  AvgVideoCaption_134292_Content_65 = {
    Text = "Ne—hiç öyle demek istemedim!"
  },
  AvgVideoCaption_134292_Content_66 = {
    Text = "Ben sadece tutkunun sönmesinin ardından gelen acılığı seviyorum..."
  },
  AvgVideoCaption_134292_Content_67 = {
    Text = "Tıpkı senin eksiksiz ve mükemmel bir sonu sevdiğin gibi!"
  },
  AvgVideoCaption_134292_Content_68 = {
    Text = "Ama ablacığım,"
  },
  AvgVideoCaption_134292_Content_69 = {
    Text = "eğer kader zaten yıkıma yazılmışsa, neden direnesin ki?"
  },
  AvgVideoCaption_134292_Content_7 = {
    Text = "Kaderin tutsağı bir kadın,"
  },
  AvgVideoCaption_134292_Content_70 = {
    Text = "Onların kendileri için yazılmış yıkıma doğru yürümelerine izin vermek... bunda bir güzellik yok mu?"
  },
  AvgVideoCaption_134292_Content_71 = {
    Text = "Kaderin çarkı merhametsizce döner,"
  },
  AvgVideoCaption_134292_Content_72 = {
    Text = "ve sen bile onun nerede duracağını değiştiremezsin."
  },
  AvgVideoCaption_134292_Content_73 = {
    Text = "Neden ağı örmeye devam ediyorsun? Neden bu kadar nankör bir şeye tutunuyorsun?"
  },
  AvgVideoCaption_134292_Content_74 = {
    Text = "Kaderin çarkı gerçekten de merhametsizdir."
  },
  AvgVideoCaption_134292_Content_75 = {
    Text = "Ama yok etmek için dönmez."
  },
  AvgVideoCaption_134292_Content_76 = {
    Text = "Hayatın kendi düzeni içinde devam edebilmesi için döner."
  },
  AvgVideoCaption_134292_Content_77 = {
    Text = "Şu sahnenin üzerindekine bak."
  },
  AvgVideoCaption_134292_Content_78 = {
    Text = "Kader tarafından terk edilmiş,"
  },
  AvgVideoCaption_134292_Content_79 = {
    Text = "acılar içinde ezilmiş,"
  },
  AvgVideoCaption_134292_Content_8 = {
    Text = "kurtuluşunu bekliyor."
  },
  AvgVideoCaption_134292_Content_80 = {
    Text = "kendi çaresizliği ve yıkımı için gözyaşı döken..."
  },
  AvgVideoCaption_134292_Content_81 = {
    Text = "Yine de hiç bırakmadı,"
  },
  AvgVideoCaption_134292_Content_82 = {
    Text = "güzel sonlara inanmayı bıraktığında bile."
  },
  AvgVideoCaption_134292_Content_83 = {
    Text = "Eğer bırakacak olsaydı—"
  },
  AvgVideoCaption_134292_Content_84 = {
    Text = "o zaman her şey, taşıdığı her kader, tüm anlamını yitirirdi."
  },
  AvgVideoCaption_134292_Content_85 = {
    Text = "Tüm bu ıssızlığın ortasında,"
  },
  AvgVideoCaption_134292_Content_86 = {
    Text = "geriye kalan umudu koruyan biri her zaman olmalı,"
  },
  AvgVideoCaption_134292_Content_87 = {
    Text = "sevgili ablam."
  },
  AvgVideoCaption_134292_Content_88 = {
    Text = "Sanırım şimdi anlıyorum, ablam..."
  },
  AvgVideoCaption_134292_Content_89 = {
    Text = "O sahnede ağlayan kişi—sen değil misin?"
  },
  AvgVideoCaption_134292_Content_9 = {
    Text = "<Italic:\"Cruda sorte,\"> zalim kader..."
  },
  AvgVideoCaption_134292_Content_90 = {
    Text = "Dünyanın acılar altında ezilişini izledim,"
  },
  AvgVideoCaption_134292_Content_91 = {
    Text = "gün be gün—her ruh, o sessiz ve tekrarlayan çekişle sonuna doğru sürükleniyor."
  },
  AvgVideoCaption_134292_Content_92 = {
    Text = "O sonsuz karanlık. O sınırsız yalnızlık..."
  },
  AvgVideoCaption_134292_Content_93 = {
    Text = "Böyle bir geleceği yaşayanlara geri vermek,"
  },
  AvgVideoCaption_134292_Content_94 = {
    Text = "hayatın kendisine ihanetten başka bir şey olmazdı."
  },
  AvgVideoCaption_134292_Content_95 = {
    Text = "Her kalp atışına değer verdiğim için,"
  },
  AvgVideoCaption_134292_Content_96 = {
    Text = "dökülen her gözyaşına..."
  },
  AvgVideoCaption_134292_Content_97 = {
    Text = "dünyayı boşluğa sürüklenmesine göz yummaya gönlüm razı olmuyor."
  },
  AvgVideoCaption_134292_Content_98 = {
    Text = "Bu benim seçimim."
  },
  AvgVideoCaption_134292_Content_99 = {
    Text = "Ve bedelini ödeyeceğim."
  },
  AvgVideoCaption_139854_Content_1 = {
    Text = "Birinci Mektup"
  },
  AvgVideoCaption_139854_Content_10 = {
    Text = "İşte buna \"Aşk\" denir herhalde"
  },
  AvgVideoCaption_139854_Content_11 = {
    Text = "Her anın bir Son'u vardır."
  },
  AvgVideoCaption_139854_Content_12 = {
    Text = "Hikayeler ebedi değildir."
  },
  AvgVideoCaption_139854_Content_13 = {
    Text = "Şimdiki ben, tam burada, bu anda gibiyim."
  },
  AvgVideoCaption_139854_Content_14 = {
    Text = "Defalarca derinden hissettim ki,"
  },
  AvgVideoCaption_139854_Content_15 = {
    Text = "Burası @3'in olmadığı evren, değil mi?"
  },
  AvgVideoCaption_139854_Content_16 = {
    Text = "Üçüncü Mektup"
  },
  AvgVideoCaption_139854_Content_17 = {
    Text = "\"Ben\" hakkındaki şeyleri yavaş yavaş hatırlamaya başladım."
  },
  AvgVideoCaption_139854_Content_18 = {
    Text = "Şimdiki olaylar hakkında da çok daha fazlasını anlar oldum."
  },
  AvgVideoCaption_139854_Content_19 = {
    Text = "Buradaki uygarlık oldukça geri kalmış gibi görünüyor."
  },
  AvgVideoCaption_139854_Content_2 = {
    Text = "Şu an, bilincim tam burada."
  },
  AvgVideoCaption_139854_Content_20 = {
    Text = "Ama bunun da kendine göre ilginç yönleri var. Sevmediğimi söyleyemem doğrusu."
  },
  AvgVideoCaption_139854_Content_21 = {
    Text = "Teknolojinin ve benzeri şeylerin daha gelişmiş olacağını sanıyordum…"
  },
  AvgVideoCaption_139854_Content_22 = {
    Text = "Bunların ötesinde, her zaman daha önemli bir şey olduğunu hissediyorum, acaba o nedir?"
  },
  AvgVideoCaption_139854_Content_23 = {
    Text = "Son derece önemli bir şey. Son derece değerli biri."
  },
  AvgVideoCaption_139854_Content_24 = {
    Text = "Anlamadığımda Kaygı duyuyorum, ama yine de daha fazlasını öğrenmek istiyorum."
  },
  AvgVideoCaption_139854_Content_25 = {
    Text = "Çabucak öğrenmek istiyorum. Çabucak görüşmek istiyorum. O nedir ki?"
  },
  AvgVideoCaption_139854_Content_26 = {
    Text = "Sadece bunu düşünmek bile çok mutlu ediyor beni."
  },
  AvgVideoCaption_139854_Content_27 = {
    Text = "Keşke beni bulabilseydin…"
  },
  AvgVideoCaption_139854_Content_28 = {
    Text = "Dördüncü Mektup"
  },
  AvgVideoCaption_139854_Content_29 = {
    Text = "Türlü türlü anılar içime doldu."
  },
  AvgVideoCaption_139854_Content_3 = {
    Text = "Burası çok yabancı ve çok ıssız."
  },
  AvgVideoCaption_139854_Content_30 = {
    Text = "Sanki güçlü bir Güç tarafından saldırıya uğrıyormuşum gibi"
  },
  AvgVideoCaption_139854_Content_31 = {
    Text = "Son derece soğuk, sanki bedenim Parçalanıyormuş gibi"
  },
  AvgVideoCaption_139854_Content_32 = {
    Text = "Son derece mutlu, sanki tüm vücudum ateş gibi yanıyormuş gibi"
  },
  AvgVideoCaption_139854_Content_33 = {
    Text = "Dehşet dolu anılar, neşeli anılar, sevinçli anılar, hüzünlü anılar"
  },
  AvgVideoCaption_139854_Content_34 = {
    Text = "Ama en önemli anı yalnızca bir tanedir."
  },
  AvgVideoCaption_139854_Content_35 = {
    Text = "Değerli seninle birlikte geçirdiğim anılar."
  },
  AvgVideoCaption_139854_Content_36 = {
    Text = "Bu anılar acaba nerededir…"
  },
  AvgVideoCaption_139854_Content_37 = {
    Text = "Beşinci Mektup"
  },
  AvgVideoCaption_139854_Content_38 = {
    Text = "Bir çöl kadar geniş bir yer."
  },
  AvgVideoCaption_139854_Content_39 = {
    Text = "Etrafta tek bir ot, tek bir ağaç bile yok."
  },
  AvgVideoCaption_139854_Content_4 = {
    Text = "Sen de bu gezegenin bir yerinde misin?"
  },
  AvgVideoCaption_139854_Content_40 = {
    Text = "Eğer bir karahindiba tohumu böyle bir çöle düşseydi."
  },
  AvgVideoCaption_139854_Content_41 = {
    Text = "Rüzgârın taşıdığı o küçük tohum, memleketinden çok uzaklara sürüklendi,"
  },
  AvgVideoCaption_139854_Content_42 = {
    Text = "acaba o minicik tohum neler düşünüyordur?"
  },
  AvgVideoCaption_139854_Content_43 = {
    Text = "Eğer, o çölde — tek bir kişi bile olsa"
  },
  AvgVideoCaption_139854_Content_44 = {
    Text = "çiçekleri seven biri olduğunu bilseydi,"
  },
  AvgVideoCaption_139854_Content_45 = {
    Text = "\"Karahindiba çiçeği ne kadar güzel\" diyerek,"
  },
  AvgVideoCaption_139854_Content_46 = {
    Text = "eğer hep yanında olabilseydi,"
  },
  AvgVideoCaption_139854_Content_47 = {
    Text = "sonsuza dek, yanı başımda,"
  },
  AvgVideoCaption_139854_Content_48 = {
    Text = "eğer sen orada olsaydın…"
  },
  AvgVideoCaption_139854_Content_49 = {
    Text = "Teşekkür ederim..."
  },
  AvgVideoCaption_139854_Content_5 = {
    Text = "İkinci Mektup"
  },
  AvgVideoCaption_139854_Content_50 = {
    Text = "Unutmayacağım…"
  },
  AvgVideoCaption_139854_Content_6 = {
    Text = "Önemli biriyle karşılaştığım anı hatırlıyorum."
  },
  AvgVideoCaption_139854_Content_7 = {
    Text = "O bakışlarda yalnızca ufak bir şaşkınlık vardı…"
  },
  AvgVideoCaption_139854_Content_8 = {
    Text = "Ne Korku vardı, ne de Açgözlülük"
  },
  AvgVideoCaption_139854_Content_9 = {
    Text = "Her zaman bana çok nazikçe davrandı"
  },
  AvgVideoCaption_139855_Content_1 = {
    Text = "Beni hatırlıyor musun?"
  },
  AvgVideoCaption_139855_Content_2 = {
    Text = "Sevgi Caro'ya dönüştüğünde"
  },
  AvgVideoCaption_139855_Content_3 = {
    Text = "Bu bize ait olan"
  },
  AvgVideoCaption_139855_Content_4 = {Text = "Güzel"},
  AvgVideoCaption_139855_Content_5 = {
    Text = "Ama acımasız bir dünya"
  },
  AvgVideoCaption_139855_Content_6 = {
    Text = "Heh heh, heh heh heh heh"
  },
  AvgVideoCaption_139855_Content_7 = {Text = "Ve bir de"},
  AvgVideoCaption_139855_Content_8 = {
    Text = "Kavuşma adını taşıyan"
  },
  AvgVideoCaption_139855_Content_9 = {
    Text = "Küçücük bir mucize"
  },
  AvgVideoCaption_143591_Content_1 = {
    Text = "Bu İfadeyi takınmana gerek yok"
  },
  AvgVideoCaption_143591_Content_10 = {
    Text = "Belki hâlâ Öfke içindeyken benden istediğinizi alabilirdiniz"
  },
  AvgVideoCaption_143591_Content_11 = {
    Text = "İnanın bana, Karanlığı, acıyı, Kan bağlarının Ayrılığını denedim"
  },
  AvgVideoCaption_143591_Content_12 = {
    Text = "Sanga mercanların sizin kemiklerinizle birlikte büyümesini de denedim"
  },
  AvgVideoCaption_143591_Content_13 = {
    Text = "Deniz suyunun derinizi Aşındırmasını"
  },
  AvgVideoCaption_143591_Content_14 = {
    Text = "Midyelerin Caronuzu kemirmesini"
  },
  AvgVideoCaption_143591_Content_15 = {
    Text = "Sizin acınız ne kadar artarsa"
  },
  AvgVideoCaption_143591_Content_16 = {
    Text = "Benimkinin de o kadar azalacağını sanıyordum"
  },
  AvgVideoCaption_143591_Content_17 = {
    Text = "Ama olmadı"
  },
  AvgVideoCaption_143591_Content_18 = {
    Text = "Bir hata yaptım"
  },
  AvgVideoCaption_143591_Content_19 = {
    Text = "Benim hatam"
  },
  AvgVideoCaption_143591_Content_2 = {
    Text = "Sizin o acınası ve gülünç saçma fikirlerinizi biliyorum"
  },
  AvgVideoCaption_143591_Content_20 = {
    Text = "Sizin aptallığınız ve kör inancınız anlaşılması güç Dehşet felaketler yaydığı hâlde bile"
  },
  AvgVideoCaption_143591_Content_21 = {
    Text = "Her şeyi bu hale getiren"
  },
  AvgVideoCaption_143591_Content_22 = {
    Text = "Sizi hâlâ insan olarak görüyorum"
  },
  AvgVideoCaption_143591_Content_23 = {
    Text = "Ne kadar kirli bir acı olursa"
  },
  AvgVideoCaption_143591_Content_24 = {
    Text = "O kadar büyük bir ödül olur sizin gibi pis şeyler için"
  },
  AvgVideoCaption_143591_Content_25 = {
    Text = "İster bedenin acısı"
  },
  AvgVideoCaption_143591_Content_26 = {
    Text = "İster ruhun çilesi olsun"
  },
  AvgVideoCaption_143591_Content_27 = {
    Text = "Hepsi sizi kendi Fedakârlığınızın son derece yüce olduğuna inandırıyor"
  },
  AvgVideoCaption_143591_Content_28 = {
    Text = "Ölümünüzün ardından o iğrenç ve alçak tanrınızın sizi sözde yeni dünyaya götüreceğine"
  },
  AvgVideoCaption_143591_Content_29 = {Text = "Yani..."},
  AvgVideoCaption_143591_Content_3 = {Text = "Anlıyorum"},
  AvgVideoCaption_143591_Content_30 = {
    Text = "Ah, tıpkı gördüğün gibi"
  },
  AvgVideoCaption_143591_Content_31 = {
    Text = "Sévinie, Tristan, Cyril, Nash… her biri"
  },
  AvgVideoCaption_143591_Content_32 = {
    Text = "Senin yüce inancın uğruna seninle birlikte ölüme gittiğini sandığın o insanlar"
  },
  AvgVideoCaption_143591_Content_33 = {
    Text = "Hepsi burada"
  },
  AvgVideoCaption_143591_Content_34 = {
    Text = "Senden daha Adanmış ve Şevkli, yerinde ölen Sévinie"
  },
  AvgVideoCaption_143591_Content_35 = {
    Text = "Utangaç, kararlı, kendi Bağırsaklarını eritmiş olan Cyril…"
  },
  AvgVideoCaption_143591_Content_36 = {
    Text = "Uçurum hakkında hiçbir şey bilmiyorsunuz"
  },
  AvgVideoCaption_143591_Content_37 = {
    Text = "Gel, derin bir nefes al"
  },
  AvgVideoCaption_143591_Content_38 = {Text = "Dinlen"},
  AvgVideoCaption_143591_Content_39 = {
    Text = "Hoş geldin."
  },
  AvgVideoCaption_143591_Content_4 = {
    Text = "Biraz acı istiyorsunuz"
  },
  AvgVideoCaption_143591_Content_40 = {
    Text = "Şimdi anladın mı, av"
  },
  AvgVideoCaption_143591_Content_41 = {
    Text = "Uçurum… vahşi bir katliam getirmez"
  },
  AvgVideoCaption_143591_Content_42 = {
    Text = "Hayal ettiğin o coşkulu Kan ve ateş yok"
  },
  AvgVideoCaption_143591_Content_43 = {
    Text = "Yalnızca milyarlarca ton deniz suyu"
  },
  AvgVideoCaption_143591_Content_44 = {
    Text = "Bu gezegenle birlikte uyanmış kadim maddeler"
  },
  AvgVideoCaption_143591_Content_45 = {
    Text = "Sizi sonsuza dek bastıracak"
  },
  AvgVideoCaption_143591_Content_46 = {
    Text = "Sizi saracak"
  },
  AvgVideoCaption_143591_Content_47 = {
    Text = "Sonsuz masmavi Karanlığın içinde"
  },
  AvgVideoCaption_143591_Content_48 = {
    Text = "Benden başka"
  },
  AvgVideoCaption_143591_Content_49 = {
    Text = "Hiçbir tanrı sizi herhangi bir yere kurtaramaz"
  },
  AvgVideoCaption_143591_Content_5 = {
    Text = "Sizi coşturan bir ceza"
  },
  AvgVideoCaption_143591_Content_50 = {
    Text = "Artık kaçmanın hiçbir yolu kalmayacak"
  },
  AvgVideoCaption_143591_Content_51 = {
    Text = "Defalarca ölseniz bile"
  },
  AvgVideoCaption_143591_Content_52 = {
    Text = "İster Tristan gibi"
  },
  AvgVideoCaption_143591_Content_53 = {
    Text = "Kendi boğazınızı parçalayın"
  },
  AvgVideoCaption_143591_Content_54 = {
    Text = "İster akıllı Nash'i örnek alın"
  },
  AvgVideoCaption_143591_Content_55 = {
    Text = "Kendi dilinizi çiğnemeye çalışın"
  },
  AvgVideoCaption_143591_Content_56 = {
    Text = "İstediğiniz kadar deneyin"
  },
  AvgVideoCaption_143591_Content_57 = {
    Text = "Kaçamazsınız"
  },
  AvgVideoCaption_143591_Content_58 = {
    Text = "Yalnızca yavaş yavaş çürüyeceksiniz"
  },
  AvgVideoCaption_143591_Content_59 = {
    Text = "Ve yeniden uyanacaksınız"
  },
  AvgVideoCaption_143591_Content_6 = {
    Text = "Ve sonunda hiçe sayılan ölümlerinizle"
  },
  AvgVideoCaption_143591_Content_60 = {
    Text = "Ben bundan sıkılana kadar"
  },
  AvgVideoCaption_143591_Content_61 = {
    Text = "Acı hissetmek bile sizin için bir lüks olacak"
  },
  AvgVideoCaption_143591_Content_62 = {
    Text = "Ebwynnos'ta yalnızca bir kural vardır"
  },
  AvgVideoCaption_143591_Content_63 = {
    Text = "Alçak kurtarıcınız artık gelmeyecek, av"
  },
  AvgVideoCaption_143591_Content_64 = {
    Text = "Ben, tek ve biricik tanrıyım"
  },
  AvgVideoCaption_143591_Content_65 = {
    Text = "Diz çök ve kendini Derin Deniz'e sun"
  },
  AvgVideoCaption_143591_Content_66 = {
    Text = "Sonra uçurumda sonsuza dek acı çek"
  },
  AvgVideoCaption_143591_Content_7 = {
    Text = "Adanmışlık dolu bir öz-Kurban töreni tamamlamak istiyorsunuz"
  },
  AvgVideoCaption_143591_Content_8 = {
    Text = "Ne yazık ki"
  },
  AvgVideoCaption_143591_Content_9 = {
    Text = "Daha erken gelmeliydiniz"
  },
  AvgVideoCaption_148014_Content_1 = {
    Text = "Biri Astral Cetus'un dualarını okuyor."
  },
  AvgVideoCaption_148014_Content_10 = {
    Text = "O çılgın enerjiyi hissedebiliyorum..."
  },
  AvgVideoCaption_148014_Content_100 = {
    Text = "Bu yerdeki her ruhu koruyacağım."
  },
  AvgVideoCaption_148014_Content_101 = {
    Text = "Bu kasabaya huzur getireceğim."
  },
  AvgVideoCaption_148014_Content_102 = {
    Text = "Astral Cetus'un sevgi dolu fısıltılarını bu yere taşıyacağım..."
  },
  AvgVideoCaption_148014_Content_103 = {
    Text = "Sen... sen..."
  },
  AvgVideoCaption_148014_Content_104 = {
    Text = "O kadın..."
  },
  AvgVideoCaption_148014_Content_105 = {
    Text = "Az önce yaptığın..."
  },
  AvgVideoCaption_148014_Content_106 = {
    Text = "O üç çocuk annesiydi!"
  },
  AvgVideoCaption_148014_Content_107 = {Text = "Öyle mi?"},
  AvgVideoCaption_148014_Content_108 = {
    Text = "O zaman tebrikler onlara,"
  },
  AvgVideoCaption_148014_Content_109 = {
    Text = "çok acıdan kurtulmuş olacaklar."
  },
  AvgVideoCaption_148014_Content_11 = {
    Text = "O'na inanan tüm sadık kullar"
  },
  AvgVideoCaption_148014_Content_110 = {
    Text = "Sen... ama söz vermiştin..."
  },
  AvgVideoCaption_148014_Content_111 = {
    Text = "Sana kurtuluş, bu yere ise selamet getireceğime."
  },
  AvgVideoCaption_148014_Content_112 = {
    Text = "Sözümü tuttum, değil mi?"
  },
  AvgVideoCaption_148014_Content_113 = {Text = "Dur! Dur!"},
  AvgVideoCaption_148014_Content_114 = {
    Text = "Seçim'e birlikte katılabiliriz!"
  },
  AvgVideoCaption_148014_Content_115 = {
    Text = "Sana yardım edebilirim, yapabilirim—"
  },
  AvgVideoCaption_148014_Content_116 = {
    Text = "Cazip bir teklif,"
  },
  AvgVideoCaption_148014_Content_117 = {
    Text = "ne yazık ki sana zaten söz verdim."
  },
  AvgVideoCaption_148014_Content_118 = {
    Text = "Ve ben hiçbir zaman sözümden dönmem."
  },
  AvgVideoCaption_148014_Content_119 = {
    Text = "Bu kafalar adak olarak yeterli olmalı..."
  },
  AvgVideoCaption_148014_Content_12 = {
    Text = "bu güç tarafından yutulur."
  },
  AvgVideoCaption_148014_Content_120 = {
    Text = "yeteceklerdir..."
  },
  AvgVideoCaption_148014_Content_121 = {
    Text = "Güç hakkında hiçbir şey bilmiyorlardı,"
  },
  AvgVideoCaption_148014_Content_122 = {
    Text = "gerçek arzunu da bilmiyorlardı."
  },
  AvgVideoCaption_148014_Content_123 = {
    Text = "Ama ben biliyorum."
  },
  AvgVideoCaption_148014_Content_124 = {
    Text = "Sana gücümün kanıtını sundum."
  },
  AvgVideoCaption_148014_Content_125 = {
    Text = "Sevincini görüyorum, Astral Cetus..."
  },
  AvgVideoCaption_148014_Content_126 = {
    Text = "Demek Seçim'in kapıları böyle açılıyor..."
  },
  AvgVideoCaption_148014_Content_127 = {
    Text = "Yakında beni göreceksin."
  },
  AvgVideoCaption_148014_Content_128 = {
    Text = "Beni bekle... Leviathan."
  },
  AvgVideoCaption_148014_Content_13 = {
    Text = "Savaş, yağma, katliam, kan..."
  },
  AvgVideoCaption_148014_Content_14 = {
    Text = "Astral Cetus'un açlığının sonu yoktur."
  },
  AvgVideoCaption_148014_Content_15 = {
    Text = "Siz... Baba Tanrı'nın lütfunu reddetmek mi istiyorsunuz?"
  },
  AvgVideoCaption_148014_Content_16 = {
    Text = "Ben mi? Heh. Hayır."
  },
  AvgVideoCaption_148014_Content_17 = {
    Text = "Onların içinde çırpınıyorum, Hiyerofant."
  },
  AvgVideoCaption_148014_Content_18 = {
    Text = "İşte tam da bu yüzden buradayım."
  },
  AvgVideoCaption_148014_Content_19 = {
    Text = "Ne yazık ki"
  },
  AvgVideoCaption_148014_Content_2 = {
    Text = "Burası enfekte olanların tutulduğu tapınak mı?"
  },
  AvgVideoCaption_148014_Content_20 = {
    Text = "her inanan O'nun ezici lütfuna dayanamaz."
  },
  AvgVideoCaption_148014_Content_21 = {
    Text = "Ah, evet, evet."
  },
  AvgVideoCaption_148014_Content_22 = {
    Text = "O zavallı ama şanslı adanmışlar,"
  },
  AvgVideoCaption_148014_Content_23 = {
    Text = "Baba Tanrı'nın gücü karşısında sevinçle dolup taşan,"
  },
  AvgVideoCaption_148014_Content_24 = {
    Text = "sonra o sevincin kendisiyle çıldıran..."
  },
  AvgVideoCaption_148014_Content_25 = {
    Text = "İşte bu yüzden senin gibi bir inançlıya ihtiyacımız var"
  },
  AvgVideoCaption_148014_Content_26 = {
    Text = "Babamızın ruhunu yatıştırmak için,"
  },
  AvgVideoCaption_148014_Content_27 = {
    Text = "bu zavallı adanmışları kurtarmak için. Yalnızca sen..."
  },
  AvgVideoCaption_148014_Content_28 = {
    Text = "Sevgili inançlı,"
  },
  AvgVideoCaption_148014_Content_29 = {
    Text = "verdiğin sözü hâlâ hatırladığına eminim."
  },
  AvgVideoCaption_148014_Content_3 = {
    Text = "Aynen öyle!"
  },
  AvgVideoCaption_148014_Content_30 = {
    Text = "Tanrı'nın lütfunu taşıyamayacak kadar zayıf olanları kurtaracağıma söz verdim,"
  },
  AvgVideoCaption_148014_Content_31 = {
    Text = "ve bu kasabayı kurtarmanıza yardım edeceğime."
  },
  AvgVideoCaption_148014_Content_32 = {
    Text = "Sözümden asla dönmem."
  },
  AvgVideoCaption_148014_Content_33 = {
    Text = "Kasaba büyük bir onur duyuyor, sevgili hanımefendi."
  },
  AvgVideoCaption_148014_Content_34 = {
    Text = "Birkaç acı çekenden söz etmiştin."
  },
  AvgVideoCaption_148014_Content_35 = {
    Text = "Oysa şu an önümde en az üç yüz kişi duruyor."
  },
  AvgVideoCaption_148014_Content_36 = {
    Text = "Bu dindar bir kasabadır,"
  },
  AvgVideoCaption_148014_Content_37 = {
    Text = "Baba Tanrı dualarımızı işitti..."
  },
  AvgVideoCaption_148014_Content_38 = {
    Text = "Astral Cetus'un sesi bizi seçti!"
  },
  AvgVideoCaption_148014_Content_39 = {
    Text = "Bu bizim onurumuzdur!"
  },
  AvgVideoCaption_148014_Content_4 = {
    Text = "Astral Cetus'un en dindar tapınağına hoş geldiniz."
  },
  AvgVideoCaption_148014_Content_40 = {
    Text = "Bana gayet iyi görünüyorlar."
  },
  AvgVideoCaption_148014_Content_41 = {
    Text = "Şimdilik..."
  },
  AvgVideoCaption_148014_Content_42 = {
    Text = "Bu böyle devam ederse, hepimiz Astral Cetus'un iradesine ev sahipliği yapan kaplar haline geleceğiz."
  },
  AvgVideoCaption_148014_Content_43 = {
    Text = "O'nun fısıltılarını ilahi gibi okuyacaklar,"
  },
  AvgVideoCaption_148014_Content_44 = {
    Text = "ve O'nun işaretleri derilerinde belirmeye başlayacak..."
  },
  AvgVideoCaption_148014_Content_45 = {
    Text = "Sonunda, irademiz O'nunla birleşerek tek bir bütün olacak."
  },
  AvgVideoCaption_148014_Content_46 = {
    Text = "İstediğin tam olarak bu değil mi?"
  },
  AvgVideoCaption_148014_Content_47 = {Text = "Elbette!"},
  AvgVideoCaption_148014_Content_48 = {
    Text = "Her şeyimizi Tanrı Baba'ya sunmaktan büyük mutluluk duyarız!"
  },
  AvgVideoCaption_148014_Content_49 = {
    Text = "Ama... henüz değil."
  },
  AvgVideoCaption_148014_Content_5 = {
    Text = "Ama onlar \"enfekte\" değil."
  },
  AvgVideoCaption_148014_Content_50 = {
    Text = "Baba'nın daha fazla vahyini almayı diliyoruz..."
  },
  AvgVideoCaption_148014_Content_51 = {
    Text = "Ve ben—Tanrı Baba'nın lütfuyla—O'nun Seçimine katılacağım,"
  },
  AvgVideoCaption_148014_Content_52 = {
    Text = "ve O'nun biricik Vekili olacağım!"
  },
  AvgVideoCaption_148014_Content_53 = {
    Text = "Bu yüzden bundan önce,"
  },
  AvgVideoCaption_148014_Content_54 = {
    Text = "biri bizim adımıza ilk adımı atmak zorunda..."
  },
  AvgVideoCaption_148014_Content_55 = {
    Text = "Gelin, ey coşkulu inananlarım,"
  },
  AvgVideoCaption_148014_Content_56 = {
    Text = "bu hanımı zincirleyin ve sunağın önüne getirin!"
  },
  AvgVideoCaption_148014_Content_57 = {
    Text = "Bu anlaşmamızın bir parçası değildi."
  },
  AvgVideoCaption_148014_Content_58 = {
    Text = "Sevgili hanımefendi, bir zamanlar bana söz verdiniz"
  },
  AvgVideoCaption_148014_Content_59 = {
    Text = "her ne pahasına olursa olsun onları kurtaracağınıza,"
  },
  AvgVideoCaption_148014_Content_6 = {
    Text = "Sevgili hanımefendi."
  },
  AvgVideoCaption_148014_Content_60 = {
    Text = "bu zavallı kasabayı ve bu bahtsız inananları kurtaracağınıza."
  },
  AvgVideoCaption_148014_Content_61 = {
    Text = "Görebiliyorum"
  },
  AvgVideoCaption_148014_Content_62 = {
    Text = "içinizde kaynayan muazzam gücü."
  },
  AvgVideoCaption_148014_Content_63 = {
    Text = "Bu tam olarak Baba Tanrı'nın değer verdiği şey!"
  },
  AvgVideoCaption_148014_Content_64 = {
    Text = "Astral Cetus'a sunulacak en lezzetli adak sen olacaksın!"
  },
  AvgVideoCaption_148014_Content_65 = {
    Text = "Seni Baba Tanrı'ya sunduğumda..."
  },
  AvgVideoCaption_148014_Content_66 = {
    Text = "O'nun lütfunu alacağım..."
  },
  AvgVideoCaption_148014_Content_67 = {
    Text = "O kutsal yarışmaya gireceğim!"
  },
  AvgVideoCaption_148014_Content_68 = {
    Text = "Kendini feda et..."
  },
  AvgVideoCaption_148014_Content_69 = {
    Text = "Kendini sun ve gücünü bana bırak!"
  },
  AvgVideoCaption_148014_Content_7 = {
    Text = "Astral Cetus, büyük Baba Tanrımız."
  },
  AvgVideoCaption_148014_Content_70 = {
    Text = "Bu zavallı ruhları kurtar!"
  },
  AvgVideoCaption_148014_Content_71 = {
    Text = "Kendini feda et,"
  },
  AvgVideoCaption_148014_Content_72 = {
    Text = "ve Astral Cetus lütfeden bakışlarını üzerime çevirsin!"
  },
  AvgVideoCaption_148014_Content_73 = {
    Text = "Astral Cetus'un bahşettiği runeler"
  },
  AvgVideoCaption_148014_Content_74 = {
    Text = "bedenlerinizdeki en gizli gücü uyandırabilir"
  },
  AvgVideoCaption_148014_Content_75 = {
    Text = "ta ki sizi tamamen yutana dek."
  },
  AvgVideoCaption_148014_Content_76 = {
    Text = "Bu büyü oldukça uzun bir büyü."
  },
  AvgVideoCaption_148014_Content_77 = {
    Text = "Hehehehe…"
  },
  AvgVideoCaption_148014_Content_78 = {
    Text = "Biraz daha erken fark etmiş olsaydınız,"
  },
  AvgVideoCaption_148014_Content_79 = {
    Text = "belki bir şansınız olabilirdi."
  },
  AvgVideoCaption_148014_Content_8 = {
    Text = "Her Seçim'den önce,"
  },
  AvgVideoCaption_148014_Content_80 = {
    Text = "Ama artık çok geç."
  },
  AvgVideoCaption_148014_Content_81 = {
    Text = "Astral Cetus bizi izliyor."
  },
  AvgVideoCaption_148014_Content_82 = {
    Text = "Kardeşlerim,"
  },
  AvgVideoCaption_148014_Content_83 = {
    Text = "Kılıçlarınızı çekin"
  },
  AvgVideoCaption_148014_Content_84 = {
    Text = "ve bu adağı kabul et—"
  },
  AvgVideoCaption_148014_Content_85 = {
    Text = "Demek büyün sona erdi,"
  },
  AvgVideoCaption_148014_Content_86 = {
    Text = "ve sayınız oldukça yeterli... İyi."
  },
  AvgVideoCaption_148014_Content_87 = {Text = "İyi mi?"},
  AvgVideoCaption_148014_Content_88 = {
    Text = "Hepinizi bekliyor olmasaydım,"
  },
  AvgVideoCaption_148014_Content_89 = {
    Text = "bu kadar sıkıcı gevezeliğe katlanmazdım."
  },
  AvgVideoCaption_148014_Content_9 = {
    Text = "O'nun gücü, iradesi zayıf olanları etkisi altına alır..."
  },
  AvgVideoCaption_148014_Content_90 = {
    Text = "Rakibimin önce hamle yapmasına izin vermek benim alışkanlığım."
  },
  AvgVideoCaption_148014_Content_91 = {
    Text = "Artık tüm hazırlıklar tamamlandı..."
  },
  AvgVideoCaption_148014_Content_92 = {
    Text = "Ne?! ...Bu zincirler..."
  },
  AvgVideoCaption_148014_Content_93 = {
    Text = "Güç ve servet, istediğiniz tek şey bu..."
  },
  AvgVideoCaption_148014_Content_94 = {
    Text = "Gücün ne olduğunu bile anlamıyorsunuz. Hiç de rakip sayılmazsınız."
  },
  AvgVideoCaption_148014_Content_95 = {Text = "Yine de,"},
  AvgVideoCaption_148014_Content_96 = {
    Text = "kılıcım çok uzun süredir layık bir savaş için aç kaldı."
  },
  AvgVideoCaption_148014_Content_97 = {
    Text = "Umarım onu doyurabilirsiniz."
  },
  AvgVideoCaption_148014_Content_98 = {
    Text = "Onu öldürün!"
  },
  AvgVideoCaption_148014_Content_99 = {
    Text = "Bir zamanlar size söz vermiştim..."
  },
  AvgVideoCaption_149925_Content_1 = {
    Text = "Dünyanın en yüksek karlı dağının zirvesi..."
  },
  AvgVideoCaption_149925_Content_10 = {
    Text = "Benimle gel..."
  },
  AvgVideoCaption_149925_Content_11 = {
    Text = "Hazinelerini, dileklerini... her şeyini sun!"
  },
  AvgVideoCaption_149925_Content_12 = {
    Text = "Dileğin kabul edildi"
  },
  AvgVideoCaption_149925_Content_13 = {
    Text = "Peki şimdi..."
  },
  AvgVideoCaption_149925_Content_14 = {
    Text = "gerisini dağ tanrıçasına bırak, olur mu?"
  },
  AvgVideoCaption_149925_Content_2 = {
    Text = "işte tanrıların yaşadığı yer orası."
  },
  AvgVideoCaption_149925_Content_3 = {
    Text = "Benimle gel."
  },
  AvgVideoCaption_149925_Content_4 = {
    Text = "Karlı Dağların Hanımefendisi her dileğini yerine getirecek"
  },
  AvgVideoCaption_149925_Content_5 = {
    Text = "ve kaybettiklerini geri getir..."
  },
  AvgVideoCaption_149925_Content_6 = {
    Text = "Yedinci Rit"
  },
  AvgVideoCaption_149925_Content_7 = {
    Text = "Üçlü Yemin"
  },
  AvgVideoCaption_149925_Content_8 = {
    Text = "hacının sunuları tamamlandı"
  },
  AvgVideoCaption_149925_Content_9 = {
    Text = "Zirve tam önünde. Benimle gel..."
  },
  AvgVideoCaption_149926_Content_1 = {
    Text = "Ugh... efendim..."
  },
  AvgVideoCaption_149926_Content_10 = {
    Text = "Babam hep sarhoştu"
  },
  AvgVideoCaption_149926_Content_100 = {
    Text = "ağlamak işe yaramıyor."
  },
  AvgVideoCaption_149926_Content_101 = {
    Text = "Haydi, sizden konuşalım."
  },
  AvgVideoCaption_149926_Content_102 = {
    Text = "Tam üç sokak boyunca peşimden geldin, değil mi?"
  },
  AvgVideoCaption_149926_Content_103 = {
    Text = "İnce bileklerimi, soluk boynum gördün,"
  },
  AvgVideoCaption_149926_Content_104 = {
    Text = "ve çantamla ne kadar yavaş koştuğumu."
  },
  AvgVideoCaption_149926_Content_105 = {
    Text = "Aklın çoktan çalışmaya başlamıştı."
  },
  AvgVideoCaption_149926_Content_106 = {
    Text = "Böyle küçük bir kız"
  },
  AvgVideoCaption_149926_Content_107 = {
    Text = "kara borsada güzel bir fiyat eder."
  },
  AvgVideoCaption_149926_Content_108 = {
    Text = "Beni bu mahzene sürüklediğinde"
  },
  AvgVideoCaption_149926_Content_109 = {
    Text = "aklından geçmedi mi — ne şans?"
  },
  AvgVideoCaption_149926_Content_11 = {
    Text = "Annem hep ağlıyordu"
  },
  AvgVideoCaption_149926_Content_110 = {
    Text = "...Ama efendim, sence de değil mi..."
  },
  AvgVideoCaption_149926_Content_111 = {
    Text = "...burada dışarıdan biraz daha soğuk?"
  },
  AvgVideoCaption_149926_Content_112 = {
    Text = "Hehe... hehehe~"
  },
  AvgVideoCaption_149926_Content_113 = {
    Text = "Sorun değil."
  },
  AvgVideoCaption_149926_Content_114 = {
    Text = "Yakında her şömineden daha sıcak hissedeceksin."
  },
  AvgVideoCaption_149926_Content_115 = {
    Text = "Hikayenin son satırı,"
  },
  AvgVideoCaption_149926_Content_116 = {
    Text = "geleneksel olarak yenilene aittir."
  },
  AvgVideoCaption_149926_Content_117 = {Text = "Hehe~"},
  AvgVideoCaption_149926_Content_118 = {
    Text = "Hı hı~ Haydi efendim, söyle bana."
  },
  AvgVideoCaption_149926_Content_119 = {
    Text = "Üşüyor musun?"
  },
  AvgVideoCaption_149926_Content_12 = {
    Text = "Ocakta ateş yoktu"
  },
  AvgVideoCaption_149926_Content_13 = {
    Text = "masada ekmek yoktu."
  },
  AvgVideoCaption_149926_Content_14 = {Text = "Bir kış"},
  AvgVideoCaption_149926_Content_15 = {
    Text = "kar pencere eşiğine kadar yığılmıştı"
  },
  AvgVideoCaption_149926_Content_16 = {
    Text = "ve ben evden kovuldum..."
  },
  AvgVideoCaption_149926_Content_17 = {
    Text = "...sadece komşumuz Teyze Rosa'ya"
  },
  AvgVideoCaption_149926_Content_18 = {
    Text = "bana vuranın Babam olduğunu söylediğim için."
  },
  AvgVideoCaption_149926_Content_19 = {
    Text = "Karda yürüdüm, yürüdüm"
  },
  AvgVideoCaption_149926_Content_2 = {Text = "Lütfen..."},
  AvgVideoCaption_149926_Content_20 = {
    Text = "ayakkabılarım sırılsıklam olana kadar"
  },
  AvgVideoCaption_149926_Content_21 = {
    Text = "ve parmaklarım uyuştu."
  },
  AvgVideoCaption_149926_Content_22 = {Text = "O kadar..."},
  AvgVideoCaption_149926_Content_23 = {
    Text = "o kadar soğuktu ki..."
  },
  AvgVideoCaption_149926_Content_24 = {
    Text = "...Peki ya sen?"
  },
  AvgVideoCaption_149926_Content_25 = {
    Text = "Üşümeye başladın mı?"
  },
  AvgVideoCaption_149926_Content_26 = {
    Text = "Bu mahzendeki rüzgar"
  },
  AvgVideoCaption_149926_Content_27 = {
    Text = "sanki kemiklerine kadar işliyor gibi..."
  },
  AvgVideoCaption_149926_Content_28 = {Text = "değil mi?"},
  AvgVideoCaption_149926_Content_29 = {
    Text = "Sana söyleyeyim."
  },
  AvgVideoCaption_149926_Content_3 = {
    Text = "Bırakın beni"
  },
  AvgVideoCaption_149926_Content_30 = {
    Text = "O zamanlar bundan çok daha soğuktu—"
  },
  AvgVideoCaption_149926_Content_31 = {
    Text = "Yürümeye devam ettim"
  },
  AvgVideoCaption_149926_Content_32 = {
    Text = "ve yürüdüm"
  },
  AvgVideoCaption_149926_Content_33 = {
    Text = "ve yüzümden akan gözyaşlarım dondu kaldı."
  },
  AvgVideoCaption_149926_Content_34 = {
    Text = "Ve tam uykuya dalacakken—"
  },
  AvgVideoCaption_149926_Content_35 = {
    Text = "bir ses duydum"
  },
  AvgVideoCaption_149926_Content_36 = {
    Text = "karın altından beni çağırıyordu."
  },
  AvgVideoCaption_149926_Content_37 = {
    Text = "\"Küçük kız, neden ağlıyorsun?\""
  },
  AvgVideoCaption_149926_Content_38 = {
    Text = "\"Doğruyu söylediğin için mi?\""
  },
  AvgVideoCaption_149926_Content_39 = {
    Text = "\"Çok dürüst olduğun için...\""
  },
  AvgVideoCaption_149926_Content_4 = {
    Text = "Bunu kimseye söylemeyeceğim..."
  },
  AvgVideoCaption_149926_Content_40 = {
    Text = "\"...ve seni çöp gibi mi attılar?\""
  },
  AvgVideoCaption_149926_Content_41 = {
    Text = "Cevap vermedim."
  },
  AvgVideoCaption_149926_Content_42 = {
    Text = "Dudaklarımı bile ayıramadım."
  },
  AvgVideoCaption_149926_Content_43 = {
    Text = "Ama o dedi ki:"
  },
  AvgVideoCaption_149926_Content_44 = {
    Text = "\"Sorun değil.\""
  },
  AvgVideoCaption_149926_Content_45 = {
    Text = "\"Sana sihirli bir söz öğreteceğim—\""
  },
  AvgVideoCaption_149926_Content_46 = {
    Text = "\"onu söylersen, bir daha asla üşümezsin.\""
  },
  AvgVideoCaption_149926_Content_47 = {
    Text = "Ve böylece ben"
  },
  AvgVideoCaption_149926_Content_48 = {
    Text = "ilk yalanımı öğrendim."
  },
  AvgVideoCaption_149926_Content_49 = {Text = "O yalanla"},
  AvgVideoCaption_149926_Content_5 = {
    Text = "Sahip olduğum her şeyi size vereceğim"
  },
  AvgVideoCaption_149926_Content_50 = {
    Text = "ilk çiftlik evinin kapısını çaldım"
  },
  AvgVideoCaption_149926_Content_51 = {
    Text = "ve onlardan bir elma dolandırdım."
  },
  AvgVideoCaption_149926_Content_52 = {
    Text = "Sadece bir ısırık aldım"
  },
  AvgVideoCaption_149926_Content_53 = {
    Text = "ve geri kalanın hepsini verdim"
  },
  AvgVideoCaption_149926_Content_54 = {Text = "o sese."},
  AvgVideoCaption_149926_Content_55 = {Text = "Bilirsin"},
  AvgVideoCaption_149926_Content_56 = {
    Text = "bir insan donarak ölürken"
  },
  AvgVideoCaption_149926_Content_57 = {
    Text = "tüm vücudu kor gibi yanar."
  },
  AvgVideoCaption_149926_Content_58 = {
    Text = "Dünyadaki her ocak ateşinden daha sıcak."
  },
  AvgVideoCaption_149926_Content_59 = {
    Text = "O andan itibaren"
  },
  AvgVideoCaption_149926_Content_6 = {
    Text = "beni satmayın, tamam mı?"
  },
  AvgVideoCaption_149926_Content_60 = {
    Text = "bir daha asla üşümedim."
  },
  AvgVideoCaption_149926_Content_61 = {
    Text = "Bana sadece \"öğrettiğini\""
  },
  AvgVideoCaption_149926_Content_62 = {Text = "söyledi."},
  AvgVideoCaption_149926_Content_63 = {
    Text = "Çabuk öğrendim."
  },
  AvgVideoCaption_149926_Content_64 = {
    Text = "Dolandırdığım şeyler birikip"
  },
  AvgVideoCaption_149926_Content_65 = {
    Text = "giderek yükseldi"
  },
  AvgVideoCaption_149926_Content_66 = {
    Text = "tüm evi doldurdu."
  },
  AvgVideoCaption_149926_Content_67 = {
    Text = "Ama sonradan"
  },
  AvgVideoCaption_149926_Content_68 = {
    Text = "fark ettim—"
  },
  AvgVideoCaption_149926_Content_69 = {
    Text = "her yalan söylediğimde"
  },
  AvgVideoCaption_149926_Content_7 = {Text = "Lütfen"},
  AvgVideoCaption_149926_Content_70 = {
    Text = "eskiden kim olduğumu biraz daha az hatırlıyordum."
  },
  AvgVideoCaption_149926_Content_71 = {
    Text = "Unuttuğum ilk şey"
  },
  AvgVideoCaption_149926_Content_72 = {
    Text = "Babamın masaya vurma sesiydi."
  },
  AvgVideoCaption_149926_Content_73 = {
    Text = "Sonra Annemin ağlayan yüzü."
  },
  AvgVideoCaption_149926_Content_74 = {
    Text = "Ve ondan sonra—"
  },
  AvgVideoCaption_149926_Content_75 = {
    Text = "kendi adım."
  },
  AvgVideoCaption_149926_Content_76 = {
    Text = "Bir zamanlar merak ettim"
  },
  AvgVideoCaption_149926_Content_77 = {
    Text = "belki tüm bunlarda bir yanlışlık olup olmadığını."
  },
  AvgVideoCaption_149926_Content_78 = {
    Text = "Ama her böyle düşünmeye başladığımda"
  },
  AvgVideoCaption_149926_Content_79 = {
    Text = "kulağıma usulca fısıldardı—"
  },
  AvgVideoCaption_149926_Content_8 = {
    Text = "merhamet edin bana..."
  },
  AvgVideoCaption_149926_Content_80 = {
    Text = "\"Üşüdün mü? Biraz ısınmak ister misin?\""
  },
  AvgVideoCaption_149926_Content_81 = {
    Text = "Ve böylece ben"
  },
  AvgVideoCaption_149926_Content_82 = {
    Text = "bir yalan daha söyledi."
  },
  AvgVideoCaption_149926_Content_83 = {
    Text = "Bir tane daha, bir tane daha, bir tane daha..."
  },
  AvgVideoCaption_149926_Content_84 = {
    Text = "Birbiri ardına yalan."
  },
  AvgVideoCaption_149926_Content_85 = {
    Text = "Ne kadar basit. Ne kadar kolay."
  },
  AvgVideoCaption_149926_Content_86 = {
    Text = "Kardan öyle zahmetsizce yükselip geliyorlardı,"
  },
  AvgVideoCaption_149926_Content_87 = {
    Text = "öyle sıcak ve tatlı."
  },
  AvgVideoCaption_149926_Content_88 = {
    Text = "Ben gerçekten kimim?"
  },
  AvgVideoCaption_149926_Content_89 = {
    Text = "Ben gerçekten ben miyim?"
  },
  AvgVideoCaption_149926_Content_9 = {
    Text = "Hiç sevilmedim"
  },
  AvgVideoCaption_149926_Content_90 = {
    Text = "Karın altındaki o ses—"
  },
  AvgVideoCaption_149926_Content_91 = {
    Text = "benim kendi sesimdi"
  },
  AvgVideoCaption_149926_Content_92 = {
    Text = "ta başından beri, değil mi?"
  },
  AvgVideoCaption_149926_Content_93 = {
    Text = "Aman Tanrım— kaçmayın, efendim."
  },
  AvgVideoCaption_149926_Content_94 = {
    Text = "Zaten kaçmak için çok geç."
  },
  AvgVideoCaption_149926_Content_95 = {
    Text = "Elleriniz, ayaklarınız..."
  },
  AvgVideoCaption_149926_Content_96 = {
    Text = "Çok önce soğuktan tutup kaldı."
  },
  AvgVideoCaption_149926_Content_97 = {
    Text = "BİZ sizi ısıtmaya yardım edelim mi?"
  },
  AvgVideoCaption_149926_Content_98 = {
    Text = "Hadi, hadi."
  },
  AvgVideoCaption_149926_Content_99 = {Text = "Denedim—"},
  AvgVideoCaption_18618_Content_1 = {
    Text = "Odanın derinliklerinde, saf-beyaz bir Canavar sessizce dikiliyor."
  },
  AvgVideoCaption_18619_Content_1 = {
    Text = "Lotan'ın gözlerindeki çılgın parıltı yavaş yavaş solar, yerini donuk bir gümüş tona bırakır."
  },
  AvgVideoCaption_18619_Content_2 = {
    Text = "Bilinçsizliğini geride bırakan Lotan, başını eğmiş, alnının bir yanını tutarak şiddetli bir baş ağrısına katlanıyor gibidir."
  },
  AvgVideoCaption_18620_Content_1 = {
    Text = "Sözleri sönüp giderken, aklın ötesindeki tüm varlıklar bir anda yok oldu."
  },
  AvgVideoCaption_18621_Content_1 = {
    Text = "Elini kaldırır ve önündeki camı silip tertemiz eder."
  },
  AvgVideoCaption_18622_Content_1 = {
    Text = "Batmakta olan güneşin altın ışınları dev, saydam saat kadranını delip geçer, kız çocuğunun siluetini yaldızlar."
  },
  AvgVideoCaption_18623_Content_1 = {
    Text = "Yine, geriye yalnızca ben kaldım."
  },
  AvgVideoCaption_18624_Content_1 = {
    Text = "Bir sonraki anda, o uğursuz silüet yok olup gider."
  },
  AvgVideoCaption_18625_Content_1 = {
    Text = "O engin ve Bilinmeyen Yaratıkların huzurunda..."
  },
  AvgVideoCaption_18625_Content_10 = {
    Text = "O kelimenin duyulduğu anda, keskin, vızıldayan bir pain beynin derinliklerine saplanır."
  },
  AvgVideoCaption_18625_Content_11 = {
    Text = "Mide bulantısı midede kabarır, kusmuğun keskin kokusu burnuma hücum eder."
  },
  AvgVideoCaption_18625_Content_2 = {
    Text = "İnsanlar ne kadar da önemsiz."
  },
  AvgVideoCaption_18625_Content_3 = {
    Text = "Bu bir rüya mı?"
  },
  AvgVideoCaption_18625_Content_4 = {
    Text = "Göğsümde güçlü bir huzursuzluk kabarıyor."
  },
  AvgVideoCaption_18625_Content_5 = {
    Text = "—Mythag Üniversitesi Anahtar Mezarı, Anahtar Mezarı Töreni—"
  },
  AvgVideoCaption_18625_Content_6 = {
    Text = "\"...Mythag Üniversitesi, @2 ile mücadelede öncüdür...\""
  },
  AvgVideoCaption_18625_Content_7 = {
    Text = "\"...Mythag Üniversitesi’nde bir Müfettiş olmak için,\""
  },
  AvgVideoCaption_18625_Content_8 = {
    Text = "bu, hayatınızın geri kalanının ölüm ve delilikle iç içe geçeceği anlamına gelir..."
  },
  AvgVideoCaption_18625_Content_9 = {
    Text = "\"Son on yılda, @2 yayılma gösterdi...\""
  },
  AvgVideoCaption_18626_Content_1 = {
    Text = "Eğer bu şimdi herkese güvenlik getirebilecekse, ben razıyım."
  },
  AvgVideoCaption_18626_Content_10 = {
    Text = "Parmak uçlarında nemli bir his karıncalanır, yine de gerçek bir dokunuş hissi yoktur."
  },
  AvgVideoCaption_18626_Content_11 = {
    Text = "Gerçekliğin küçük bir parçası parmak uçlarında çözülür, sonsuza dek dünyadan silinir."
  },
  AvgVideoCaption_18626_Content_2 = {
    Text = "Artık kontrol altında olmayacağım."
  },
  AvgVideoCaption_18626_Content_3 = {
    Text = "Artık kimseye zarar vermeyeceğim."
  },
  AvgVideoCaption_18626_Content_4 = {
    Text = "Arkadaşlarımın bir daha benim yüzümden ölmesine izin vermeyeceğim."
  },
  AvgVideoCaption_18626_Content_5 = {
    Text = "Çanın çınlayışının sağladığı siper altında, Aigis bir şekilde, önünde mühürlü olması gereken camı zahmetsizce itip açmayı başarır."
  },
  AvgVideoCaption_18626_Content_6 = {
    Text = "Jenkin'e benden özür dilediğimi söyle."
  },
  AvgVideoCaption_18626_Content_7 = {
    Text = "Ona, daima arkadaş kalacağımızı söyle."
  },
  AvgVideoCaption_18626_Content_8 = {
    Text = "Aigis gözlerini kapar, kendini gitgide hafiflediğini hisseder. Ardında, Ramona umutsuzca elini gece göğüne doğru uzatır."
  },
  AvgVideoCaption_18626_Content_9 = {
    Text = "Erişim. Sıkıca tutun."
  },
  AvgVideoCaption_22146_Content_1 = {
    Text = "Dehşet verici bir felaket geldi çattı"
  },
  AvgVideoCaption_22146_Content_2 = {
    Text = "\"Çözünme\""
  },
  AvgVideoCaption_22146_Content_3 = {
    Text = "Her şeyi Yutar"
  },
  AvgVideoCaption_22146_Content_4 = {
    Text = "Anılar bile pençesinden Kaçış bulamaz."
  },
  AvgVideoCaption_22146_Content_5 = {
    Text = "Yüzyıllar sonra, sonunda bir çözüm bulduk—"
  },
  AvgVideoCaption_22146_Content_6 = {Text = "\"Gümüş\""},
  AvgVideoCaption_22146_Content_7 = {
    Text = "Bu madde, Ölü Ruh'ların Ruh'unu Uyandırabilir"
  },
  AvgVideoCaption_22146_Content_8 = {
    Text = "Bu ruhlar, son umudumuz."
  },
  AvgVideoCaption_22146_Content_9 = {
    Text = "En azından, umduğumuz bu..."
  },
  AvgVideoCaption_24281_Content_1 = {
    Text = "Tomurcuğun açılma anı sonunda geldi."
  },
  AvgVideoCaption_24724_Content_1 = {
    Text = "Başarısız oldum. Yine. Artık önemi yok."
  },
  AvgVideoCaption_24724_Content_2 = {
    Text = "Onu bulacağım. Kaç deneme gerekirse gereksin."
  },
  AvgVideoCaption_24724_Content_3 = {
    Text = "Bu dünyayı kurtaracak bir yol..."
  },
  AvgVideoCaption_24724_Content_4 = {
    Text = "Seni kurtaracak bir yol."
  },
  AvgVideoCaption_36151_Content_1 = {
    Text = "Çıkış, çıkış tam orada..."
  },
  AvgVideoCaption_36151_Content_10 = {
    Text = "Sözlerini dinle!"
  },
  AvgVideoCaption_36151_Content_11 = {
    Text = "Neden dinlemeliyim ki?!"
  },
  AvgVideoCaption_36151_Content_12 = {
    Text = "İradesine boyun eğ!"
  },
  AvgVideoCaption_36151_Content_13 = {
    Text = "Neden boyun eğeyim ki?!"
  },
  AvgVideoCaption_36151_Content_14 = {
    Text = "Kurban! İlahi Diyarı yeniden inşa et—"
  },
  AvgVideoCaption_36151_Content_15 = {
    Text = "İlahi Diyar mı? Rabbin mi? … Bunun benimle ne ilgisi var!"
  },
  AvgVideoCaption_36151_Content_16 = {
    Text = "Kurban! Bedenimi onun tahtına geri ver—"
  },
  AvgVideoCaption_36151_Content_17 = {
    Text = "Hayır! Biz... buradan birlikte çıkacağız!"
  },
  AvgVideoCaption_36151_Content_2 = {
    Text = "İlahi Ana’mız, neden gidiyorsun?"
  },
  AvgVideoCaption_36151_Content_3 = {
    Text = "<Italic:Hayır... “ilahi annen” olmak istemiyorum...>"
  },
  AvgVideoCaption_36151_Content_4 = {
    Text = "Bir vekil olarak… bir kurban olarak ölmek istemiyorum…"
  },
  AvgVideoCaption_36151_Content_5 = {
    Text = "İlahi Diyar rahmin aracılığıyla doğacak."
  },
  AvgVideoCaption_36151_Content_6 = {
    Text = "Nerede? Ne zaman olacak bu?"
  },
  AvgVideoCaption_36151_Content_7 = {
    Text = "Yıldızlar Düz Konum aldı!"
  },
  AvgVideoCaption_36151_Content_8 = {
    Text = "Yoksa... artık çok mu geç?"
  },
  AvgVideoCaption_36151_Content_9 = {
    Text = "Ama... neden?!"
  },
  AvgVideoCaption_45044_Content_1 = {
    Text = "Görünmez bir veba üzerimize çöktü"
  },
  AvgVideoCaption_45044_Content_10 = {
    Text = "\"Bize etini verecek misin?\""
  },
  AvgVideoCaption_45044_Content_11 = {
    Text = "\"Bize canını verecek misin?\""
  },
  AvgVideoCaption_45044_Content_12 = {
    Text = "\"Yaratıcı Tanrı bizim için ağlar. Çocukları için gözyaşı döker.\""
  },
  AvgVideoCaption_45044_Content_13 = {
    Text = "\"Aramızdaki en soyluların, O’nun elçileri olarak hizmet etmesini murat eder.\""
  },
  AvgVideoCaption_45044_Content_14 = {
    Text = "\"Ve onlar, bu topraklardan ıstırabı söküp atacaklar.\""
  },
  AvgVideoCaption_45044_Content_15 = {
    Text = "Onun seçilmiş Elçisi olarak..."
  },
  AvgVideoCaption_45044_Content_16 = {
    Text = "Kendimi bütünüyle adayacağım."
  },
  AvgVideoCaption_45044_Content_17 = {
    Text = "\"Neden, Piskopos, neden bugün lütuf yok?\""
  },
  AvgVideoCaption_45044_Content_18 = {
    Text = "\"Neden devam etmiyorsun? Neden bizi kurtarmıyorsun?!\""
  },
  AvgVideoCaption_45044_Content_19 = {
    Text = "\"Nasıl güçsüz olabilirsin?\""
  },
  AvgVideoCaption_45044_Content_2 = {
    Text = "Yalnızca ölüm ve umutsuzluk getiriyor"
  },
  AvgVideoCaption_45044_Content_20 = {
    Text = "\"Bizi terk ettin! Acının yayılmasına izin verdin!\""
  },
  AvgVideoCaption_45044_Content_21 = {
    Text = "\"Lütuf istiyorum! Yaşamak istiyorum! Ölmek istemiyorum!\""
  },
  AvgVideoCaption_45044_Content_22 = {
    Text = "\"Yeterli değil... Daha fazlası! DAHA FAZLASINA İHTİYACIMIZ VAR!\""
  },
  AvgVideoCaption_45044_Content_23 = {
    Text = "Ben neysem, neye sahipsem..."
  },
  AvgVideoCaption_45044_Content_24 = {
    Text = "sizi bu lanetten azat etmeye adıyorum"
  },
  AvgVideoCaption_45044_Content_25 = {
    Text = "Ruh Çobanı"
  },
  AvgVideoCaption_45044_Content_26 = {
    Text = "Esenliğiniz için... her şeyimden vazgeçeceğim"
  },
  AvgVideoCaption_45044_Content_3 = {
    Text = "Ulu Baba’nın Çocukları,"
  },
  AvgVideoCaption_45044_Content_4 = {
    Text = "kardeşlerim..."
  },
  AvgVideoCaption_45044_Content_5 = {
    Text = "Sizin acınızı kendi ruhumda açılmış bir yara gibi hissediyorum"
  },
  AvgVideoCaption_45044_Content_6 = {
    Text = "Her şeyimi feda edeceğim..."
  },
  AvgVideoCaption_45044_Content_7 = {
    Text = "bu ıstırabı dindirmek için."
  },
  AvgVideoCaption_45044_Content_8 = {
    Text = "\"Piskopos Salvador, bugün bize lütfunu bahşet!\""
  },
  AvgVideoCaption_45044_Content_9 = {
    Text = "\"Piskopos Salvador, bizi kurtaracak mısın?\""
  },
  AvgVideoCaption_50040_Content_1 = {
    Text = "Üreme. Bu, Süregidiş Yolu’nun ta kendisi"
  },
  AvgVideoCaption_50040_Content_10 = {
    Text = "Benimle bir ol"
  },
  AvgVideoCaption_50040_Content_11 = {
    Text = "Çocuklarımı dünyaya getirin"
  },
  AvgVideoCaption_50040_Content_12 = {
    Text = "Bu kum denizini boğun"
  },
  AvgVideoCaption_50040_Content_13 = {
    Text = "kanımız ve tohumumuzla!"
  },
  AvgVideoCaption_50040_Content_14 = {Text = "Etini sun"},
  AvgVideoCaption_50040_Content_15 = {
    Text = "ve Bereket Ana Ağacı'nın gövdesi ol"
  },
  AvgVideoCaption_50040_Content_16 = {
    Text = "Kanını sun"
  },
  AvgVideoCaption_50040_Content_17 = {
    Text = "Kutsal Nehir'i sulamak için"
  },
  AvgVideoCaption_50040_Content_18 = {
    Text = "yeni bir Aram'ın doğuşunu beslemek için!"
  },
  AvgVideoCaption_50040_Content_19 = {
    Text = "Üreme. Bu, Süregidiş Yolu’nun ta kendisi"
  },
  AvgVideoCaption_50040_Content_2 = {
    Text = "karanlık kıyamet çöktüğünde"
  },
  AvgVideoCaption_50040_Content_20 = {
    Text = "karanlık kıyamet çöktüğünde"
  },
  AvgVideoCaption_50040_Content_21 = {Text = "Sen..."},
  AvgVideoCaption_50040_Content_22 = {
    Text = "Bize katılacak mısın?"
  },
  AvgVideoCaption_50040_Content_23 = {
    Text = "Milyon Evladın Anası"
  },
  AvgVideoCaption_50040_Content_3 = {
    Text = "Bize katılacak mısın?"
  },
  AvgVideoCaption_50040_Content_4 = {Text = "Gel"},
  AvgVideoCaption_50040_Content_5 = {
    Text = "Artık daha fazla tahammül edemiyorum"
  },
  AvgVideoCaption_50040_Content_6 = {Text = "Buraya gel"},
  AvgVideoCaption_50040_Content_7 = {
    Text = "Bana yaklaş"
  },
  AvgVideoCaption_50040_Content_8 = {Text = "Bana dokun"},
  AvgVideoCaption_50040_Content_9 = {
    Text = "İçime gir"
  },
  AvgVideoCaption_56358_Content_1 = {
    Text = "Yağmur: bulutun gökyüzüne vedasıdır."
  },
  AvgVideoCaption_56358_Content_10 = {
    Text = "sen Bahar’sın."
  },
  AvgVideoCaption_56358_Content_11 = {
    Text = "Lütfen, benim için bir dize bestele,"
  },
  AvgVideoCaption_56358_Content_12 = {
    Text = "bahçeye sunulan bir bahar sunusu olsun."
  },
  AvgVideoCaption_56358_Content_13 = {
    Text = "Çorak hayatlarımızda, güller koyu bir kızıllıkta kök salmış."
  },
  AvgVideoCaption_56358_Content_14 = {
    Text = "\"Elimi tut,\" diye fısıldadın."
  },
  AvgVideoCaption_56358_Content_15 = {
    Text = "Parmaklarımız değdiğinde, bana bir bahçe inşa edeceksin."
  },
  AvgVideoCaption_56358_Content_16 = {
    Text = "Mütevazı krallığımızda,"
  },
  AvgVideoCaption_56358_Content_17 = {
    Text = "benim için her dikene katlanacaksın."
  },
  AvgVideoCaption_56358_Content_18 = {
    Text = "Yalvarırım, şiirimi kabul et; bu bahara dair sunuyu bahçeye armağan et."
  },
  AvgVideoCaption_56358_Content_19 = {
    Text = "Çorak hayatlarımızda, güller koyu bir kızıllıkta kök salmış."
  },
  AvgVideoCaption_56358_Content_2 = {
    Text = "Yeniden buluştuğumuzda, sana çiçekler getireceğim,"
  },
  AvgVideoCaption_56358_Content_20 = {
    Text = "Yağmur. Bahar’ın bahçeye vedasıdır."
  },
  AvgVideoCaption_56358_Content_21 = {
    Text = "Yeniden buluştuğumuzda..."
  },
  AvgVideoCaption_56358_Content_22 = {
    Text = "bana çiçekler getirecek misin?"
  },
  AvgVideoCaption_56358_Content_23 = {
    Text = "Bahara Bir Buket"
  },
  AvgVideoCaption_56358_Content_24 = {
    Text = "Son dizemizin karşılığında, onu bana getir."
  },
  AvgVideoCaption_56358_Content_3 = {
    Text = "ilk dizemizin karşılığında."
  },
  AvgVideoCaption_56358_Content_4 = {Text = "Elimi tut."},
  AvgVideoCaption_56358_Content_5 = {
    Text = "Ve parmaklarımız birbirine değdiğinde,"
  },
  AvgVideoCaption_56358_Content_6 = {
    Text = "sana bir bahçe kuracağım."
  },
  AvgVideoCaption_56358_Content_7 = {
    Text = "Mütevazı krallığımızda,"
  },
  AvgVideoCaption_56358_Content_8 = {
    Text = "senin için her dikene katlanacağım."
  },
  AvgVideoCaption_56358_Content_9 = {
    Text = "Horla, ben bahçeyim, ve sen—"
  },
  AvgVideoCaption_60917_Content_1 = {
    Text = "Müzikte gerçek ustalığa erişmek için,"
  },
  AvgVideoCaption_60917_Content_10 = {
    Text = "Göstericiler toplandı."
  },
  AvgVideoCaption_60917_Content_11 = {
    Text = "Uyumsuzluk sessizliğe karışsın."
  },
  AvgVideoCaption_60917_Content_12 = {
    Text = "Her nota, batonun çizdiği fitil yolunda dans etsin."
  },
  AvgVideoCaption_60917_Content_13 = {
    Text = "Her şey, kusursuz topluluğa doğru yakınsıyor."
  },
  AvgVideoCaption_60917_Content_14 = {
    Text = "Şimdi, kendini bırak"
  },
  AvgVideoCaption_60917_Content_15 = {
    Text = "ve bu görkemli senfoniye nüfuz et—"
  },
  AvgVideoCaption_60917_Content_16 = {
    Text = "La Minör: Son Senfoni"
  },
  AvgVideoCaption_60917_Content_17 = {
    Text = "Tiyatronun alkışı dindiğinde,"
  },
  AvgVideoCaption_60917_Content_18 = {
    Text = "Gerçek Performans..."
  },
  AvgVideoCaption_60917_Content_19 = {
    Text = "başlayacak."
  },
  AvgVideoCaption_60917_Content_2 = {
    Text = "önce mutlak denetimi sağlamak gerekir."
  },
  AvgVideoCaption_60917_Content_3 = {
    Text = "Ön Oyun başlasın!"
  },
  AvgVideoCaption_60917_Content_4 = {
    Text = "Batuta nereye kalkarsa—"
  },
  AvgVideoCaption_60917_Content_5 = {
    Text = "Her şey yankılanacak."
  },
  AvgVideoCaption_60917_Content_6 = {
    Text = "Yaylılar: trajik bir Aşama’nın başkahramanları;"
  },
  AvgVideoCaption_60917_Content_7 = {
    Text = "Unutuş’a yenik düş ya da dönüşerek yeniden doğ."
  },
  AvgVideoCaption_60917_Content_8 = {
    Text = "Nefesliler: Tehlikeli armoniler ören, azametli bir rakip."
  },
  AvgVideoCaption_60917_Content_9 = {
    Text = "Vurmalılar: Sürpriz aralıklarıyla, hayret verici bir konçerto."
  },
  AvgVideoCaption_70276_Content_1 = {
    Text = "Biz İsimsizleriz"
  },
  AvgVideoCaption_70276_Content_10 = {
    Text = "Sesim kısık ve kurumuş olsa da, adımı çağırabilir misin"
  },
  AvgVideoCaption_70276_Content_11 = {
    Text = "Kendi kanıtımı arıyorum, yaşamış olduğumun kanıtını"
  },
  AvgVideoCaption_70276_Content_12 = {
    Text = "Dünya bütünüyle solsa da, lütfen adımı çağır"
  },
  AvgVideoCaption_70276_Content_13 = {
    Text = "Kısa, gelip geçici ışığa hâlâ sıkı sıkıya tutunarak"
  },
  AvgVideoCaption_70276_Content_14 = {
    Text = "Veda edecek olsak da, adımı çağırabilir misin"
  },
  AvgVideoCaption_70276_Content_15 = {
    Text = "Yolumu aydınlatacak inancı, inancımı arıyorum"
  },
  AvgVideoCaption_70276_Content_16 = {
    Text = "Zaman bütünüyle solsa da, lütfen adımı çağır"
  },
  AvgVideoCaption_70276_Content_17 = {
    Text = "Yine de sönmeden kalacak umudu saklıyorum"
  },
  AvgVideoCaption_70276_Content_18 = {
    Text = "Dünya bütünüyle solsa da, ben de senin adını çağırabilir miyim"
  },
  AvgVideoCaption_70276_Content_19 = {
    Text = "Kısa, gelip geçici ışığa hâlâ sıkı sıkıya tutunarak"
  },
  AvgVideoCaption_70276_Content_2 = {
    Text = "Unutulmuş bir dünyadan"
  },
  AvgVideoCaption_70276_Content_20 = {
    Text = "Gümüş Anahtar Bize Yol Göstersin."
  },
  AvgVideoCaption_70276_Content_21 = {
    Text = "Gümüş Anahtar Bize Yol Göstersin."
  },
  AvgVideoCaption_70276_Content_3 = {
    Text = "Sessizce kürek çekerek"
  },
  AvgVideoCaption_70276_Content_4 = {
    Text = "Uzak göğü izleyerek"
  },
  AvgVideoCaption_70276_Content_5 = {
    Text = "Karanlık dalgalarca yutulan gümüş sabah yıldızı"
  },
  AvgVideoCaption_70276_Content_6 = {
    Text = "Soluk kayıtlar, silinmiş yüzler"
  },
  AvgVideoCaption_70276_Content_7 = {
    Text = "Sıkıca tutunmaya çabalıyoruz, ama Sakla-yamıyoruz"
  },
  AvgVideoCaption_70276_Content_8 = {
    Text = "Eriyip giden gecede, son dileğimi bırakıyorum"
  },
  AvgVideoCaption_70276_Content_9 = {
    Text = "Şafak sökmeden unutuluyoruz"
  },
  AvgVideoCaption_72086_Content_1 = {
    Text = "Başını kaldır"
  },
  AvgVideoCaption_72086_Content_10 = {
    Text = "Hiçlik onun asli niyeti değildi"
  },
  AvgVideoCaption_72086_Content_11 = {
    Text = "Fakat bilginin deliliği, onu kendi elleriyle yıkımın motorunu ateşlemeye sürüklüyor"
  },
  AvgVideoCaption_72086_Content_12 = {
    Text = "O, zihnin ormanındaki rehberdir"
  },
  AvgVideoCaption_72086_Content_13 = {
    Text = "Durmaksızın sallanan sarkacın altında"
  },
  AvgVideoCaption_72086_Content_14 = {
    Text = "işkence görmüş ruhlar içlerinden kararmış bağırsaklarını kusar"
  },
  AvgVideoCaption_72086_Content_15 = {
    Text = "Canlı biçimlerin güzelliği çürüyüp bozuldu"
  },
  AvgVideoCaption_72086_Content_16 = {
    Text = "Kader bıçağının altında, ölü ruh ile dans eder"
  },
  AvgVideoCaption_72086_Content_17 = {
    Text = "İlahi Olan’ın çocuğu, aynı zamanda İlahi Olan’ın annesidir"
  },
  AvgVideoCaption_72086_Content_18 = {
    Text = "Kıvrılan kanı ve kemiği Onun ilahi doğuşuna sunanlar"
  },
  AvgVideoCaption_72086_Content_19 = {
    Text = "ebedi bir görkeme gark olacak"
  },
  AvgVideoCaption_72086_Content_2 = {
    Text = "\"Son Perde\"sini kucaklamış bir dünyada"
  },
  AvgVideoCaption_72086_Content_20 = {
    Text = "Sayısız buzulun ve uçsuz bucaksız karlı ovaların arasında"
  },
  AvgVideoCaption_72086_Content_21 = {
    Text = "o, beyazın en saf gölgesidir"
  },
  AvgVideoCaption_72086_Content_22 = {
    Text = "...Gerçekten böyle bir saçmalığa inanır mıydın?"
  },
  AvgVideoCaption_72086_Content_23 = {
    Text = "İlahi söyleyin, inleyin ve dillerinizle ağlar örün"
  },
  AvgVideoCaption_72086_Content_24 = {
    Text = "Onun tezgâhında"
  },
  AvgVideoCaption_72086_Content_25 = {
    Text = "ipek iplikle bağlanan her kişi"
  },
  AvgVideoCaption_72086_Content_26 = {
    Text = "yalnızca kaderin bir kuklasıdır"
  },
  AvgVideoCaption_72086_Content_27 = {
    Text = "Görevi bu yerde Tamamla"
  },
  AvgVideoCaption_72086_Content_28 = {
    Text = "İlkel dünyaya Dön"
  },
  AvgVideoCaption_72086_Content_29 = {
    Text = "Nedensiz hafif uyku sona erdi"
  },
  AvgVideoCaption_72086_Content_3 = {
    Text = "Yıldızların Düz Konumu anı yaklaşıyor"
  },
  AvgVideoCaption_72086_Content_30 = {
    Text = "Bu Varlık’ın fermanıyla, Lemuria ebediyen ayakta kalacak—kırılmadan, boyun eğmeden, çürümeyecek şekilde"
  },
  AvgVideoCaption_72086_Content_31 = {
    Text = "Başını kaldır"
  },
  AvgVideoCaption_72086_Content_32 = {
    Text = "Yıldızların Düz Konum anı geldi"
  },
  AvgVideoCaption_72086_Content_4 = {
    Text = "Ah, uzaklardan gelen \"Konuk\"umuz"
  },
  AvgVideoCaption_72086_Content_5 = {
    Text = "Ahmak varlıklar çoktan toza dönüştü"
  },
  AvgVideoCaption_72086_Content_6 = {
    Text = "öyleyse bırak zekân"
  },
  AvgVideoCaption_72086_Content_7 = {
    Text = "hayatta kalma fitil yolunu beslesin"
  },
  AvgVideoCaption_72086_Content_8 = {
    Text = "Tüm ruhaniyetini ve rüyalarını sun"
  },
  AvgVideoCaption_72086_Content_9 = {
    Text = "gerçek İlahi Egemenlik’in düşüşüne"
  },
  AvgVideoCaption_76210_Content_1 = {
    Text = "Winkle, gramofonu başlat."
  },
  AvgVideoCaption_76210_Content_10 = {
    Text = "En uygun hareket tarzı, bu beyin kavanozuna doğrudan ameliyat yapmam—besin solüsyonuyla arayüzünü değiştirmem."
  },
  AvgVideoCaption_76210_Content_11 = {
    Text = "Koruyucunun bilincini çevrimiçi hâle getirmek için beyin etkinliğini zorla yükseltmek."
  },
  AvgVideoCaption_76210_Content_12 = {
    Text = "Sevgili Yavru Köpek, korkacak hiçbir şey yok."
  },
  AvgVideoCaption_76210_Content_13 = {
    Text = "Güzel. Aletler hazır. Dışarı çık."
  },
  AvgVideoCaption_76210_Content_14 = {
    Text = "Ne güzel bir beyin kıvrımı."
  },
  AvgVideoCaption_76210_Content_15 = {
    Text = "Fazla safsızlıkları uzaklaştırıyoruz..."
  },
  AvgVideoCaption_76210_Content_16 = {
    Text = "Serebral korteksin saflığını geri yüklüyoruz."
  },
  AvgVideoCaption_76210_Content_17 = {Text = "İşte..."},
  AvgVideoCaption_76210_Content_18 = {
    Text = "Kaudat Çekirdek."
  },
  AvgVideoCaption_76210_Content_19 = {
    Text = "Lentiform Çekirdek."
  },
  AvgVideoCaption_76210_Content_2 = {
    Text = "Bilinci hâlâ beyin tankına doğru düzgün bağlanamıyor mu?"
  },
  AvgVideoCaption_76210_Content_20 = {Text = "Amigdala."},
  AvgVideoCaption_76210_Content_21 = {
    Text = "Klaustrum..."
  },
  AvgVideoCaption_76210_Content_22 = {
    Text = "Tüm fonksiyonlar normal parametreler içinde çalışıyor."
  },
  AvgVideoCaption_76210_Content_23 = {
    Text = "Sevgili Yavru Köpek, beynine çok iyi bakacağım."
  },
  AvgVideoCaption_76210_Content_24 = {
    Text = "Hipokampüse gelen bir hasar yüzünden seninle paylaştığımız o değerli anıları kaybetmemiz ne büyük israf olurdu."
  },
  AvgVideoCaption_76210_Content_25 = {
    Text = "İlk tanıştığımız günü hâlâ hatırlıyorum. Beni bir Doll sanmıştın."
  },
  AvgVideoCaption_76210_Content_26 = {
    Text = "Başını kaldırıp titrek, küçücük sesinle bana \"Profesör Doll\" demiştin."
  },
  AvgVideoCaption_76210_Content_27 = {
    Text = "Sadece kendimi vakur taşıdığımı sanıyordum—meğer sen sadece saha raporunu bitirmediğin için azar işitmekten korkuyormuşsun."
  },
  AvgVideoCaption_76210_Content_28 = {
    Text = "Beyninin hangi kısmında yaşıyor o hafıza?"
  },
  AvgVideoCaption_76210_Content_29 = {
    Text = "Burada mı?"
  },
  AvgVideoCaption_76210_Content_3 = {
    Text = "Boyutları köprülemek senin için gerçekten bu kadar mı zor?"
  },
  AvgVideoCaption_76210_Content_30 = {
    Text = "...Yoksa burada mı?"
  },
  AvgVideoCaption_76210_Content_31 = {
    Text = "Haha. Pek de fark etmez."
  },
  AvgVideoCaption_76210_Content_32 = {
    Text = "Çünkü düşünmemiz gereken çok daha önemli şeyler var."
  },
  AvgVideoCaption_76210_Content_33 = {
    Text = "Aynı günün sonunda, Mythag’dan profesörle birlikte, beni bizzat ışığın ulaşmadığı karanlık derinliklere mühürledin."
  },
  AvgVideoCaption_76210_Content_34 = {
    Text = "Dört uzvum da bağlanmış, hareketim öyle kısıtlanmıştı ki, yalnızca dönmek bile boğucu geliyordu..."
  },
  AvgVideoCaption_76210_Content_35 = {
    Text = "Sen unutsan bile..."
  },
  AvgVideoCaption_76210_Content_36 = {
    Text = "Ben asla, asla unutmayacağım."
  },
  AvgVideoCaption_76210_Content_37 = {
    Text = "Dönüşsüz Cehennem'de ebediyen yok ol."
  },
  AvgVideoCaption_76210_Content_38 = {
    Text = "...Şimdi iyiyim."
  },
  AvgVideoCaption_76210_Content_39 = {
    Text = "Beni affet, Mythag'ın yavru köpeği."
  },
  AvgVideoCaption_76210_Content_4 = {
    Text = "▼▼ Teknolojinin tüm varlığını bilinç transferi araştırmasına adadığını sanıyordum. Bunun gibi küçük bir aksaklık önemsiz olmalıydı."
  },
  AvgVideoCaption_76210_Content_40 = {
    Text = "Kendimi bu kadar kaptırmamam gerekirdi."
  },
  AvgVideoCaption_76210_Content_41 = {
    Text = "Şimdi o hâlde—beyin sapını açacağım."
  },
  AvgVideoCaption_76210_Content_42 = {
    Text = "Hipotalamusuna eriş, orta beyninde gerekli düzenlemeleri yap..."
  },
  AvgVideoCaption_76210_Content_43 = {
    Text = "Ah. Sinirlerin seğiriyor."
  },
  AvgVideoCaption_76210_Content_44 = {
    Text = "Ne kadar acınası. Sana bir anestezik tentür uygulamamı ister misin?"
  },
  AvgVideoCaption_76210_Content_45 = {
    Text = "Ne yazık ki bunun için biraz fazla geç."
  },
  AvgVideoCaption_76210_Content_46 = {
    Text = "Biraz daha dayan. Neredeyse bitti, neredeyse bitti —"
  },
  AvgVideoCaption_76210_Content_47 = {
    Text = "Hmm, bir bakayım."
  },
  AvgVideoCaption_76210_Content_48 = {Text = "Nerede?"},
  AvgVideoCaption_76210_Content_49 = {Text = "Buldum."},
  AvgVideoCaption_76210_Content_5 = {
    Text = "Sana gereğinden fazla değer biçmişim."
  },
  AvgVideoCaption_76210_Content_50 = {
    Text = "Etkinlik seviyelerini eski hâline getirmek için belli ölçüde elektriksel uyarım gerekecek."
  },
  AvgVideoCaption_76210_Content_51 = {
    Text = "Gidip sersemletme tabancasını getireceğim. Kıpırdama, olur mu?"
  },
  AvgVideoCaption_76210_Content_52 = {
    Text = "Beklettiğim için özür dilerim, zavallı küçük."
  },
  AvgVideoCaption_76210_Content_53 = {
    Text = "Bunu hakkıyla hissettiğinden emin olayım..."
  },
  AvgVideoCaption_76210_Content_54 = {
    Text = "Karanlık ve ağır, tıpkı benimki gibi... mürekkep kadar siyah..."
  },
  AvgVideoCaption_76210_Content_55 = {
    Text = "Şimdi. En alt seviyeden başlıyoruz."
  },
  AvgVideoCaption_76210_Content_56 = {
    Text = "Ölümün verimli olmasını tercih ederim—hatta anlık olmasını."
  },
  AvgVideoCaption_76210_Content_57 = {
    Text = "Ama bu an, deneyimi gerçekten tatman için var. Bunu heba etmeyeceğim."
  },
  AvgVideoCaption_76210_Content_58 = {
    Text = "Tableti ilk elde ettiğim gün, onu süslü bir blöften ibaret diye bir kenara itmiştim."
  },
  AvgVideoCaption_76210_Content_59 = {
    Text = "Ve yine de, daha açılış satırını zar zor okumuştum."
  },
  AvgVideoCaption_76210_Content_6 = {
    Text = "Fark etmez. Kendim hallederim."
  },
  AvgVideoCaption_76210_Content_60 = {
    Text = "Hayır—yarım satırını."
  },
  AvgVideoCaption_76210_Content_61 = {
    Text = "Sadece o kadarı yetmişti. Hemen anlamıştım—hiç tereddütsüz, gerçek şeydi."
  },
  AvgVideoCaption_76210_Content_62 = {
    Text = "Beni ezici bir coşku dalgalanması kapladı."
  },
  AvgVideoCaption_76210_Content_63 = {
    Text = "Sana o hissi tarif edeyim. Tam olarak şu anda yaşadığın şey."
  },
  AvgVideoCaption_76210_Content_64 = {
    Text = "Neredeyse fark edilmez bir felç; soluk, kaynaksız, hiçbir yerden sızarak içeri giren."
  },
  AvgVideoCaption_76210_Content_65 = {
    Text = "Hiçbir uyarı işareti yoktu. Hiçbir tehlike hissi yoktu. Hatta, neredeyse hoş bile geliyordu..."
  },
  AvgVideoCaption_76210_Content_66 = {
    Text = "Elbette öyleydi. Bu dünyanın gerçeği—uğruna her şeyimi harcadığım nihai cevap—sanki sonunda erişim mesafeme girmişti."
  },
  AvgVideoCaption_76210_Content_67 = {
    Text = "Bala doğru çaresizce çekilen bir mahlûk gibi, okumaya devam ettim; tamahla, iştahla, durmaksızın."
  },
  AvgVideoCaption_76210_Content_68 = {
    Text = "Adım adım, tuzağın derinliklerine doğru..."
  },
  AvgVideoCaption_76210_Content_69 = {
    Text = "Ve ben düştüm."
  },
  AvgVideoCaption_76210_Content_7 = {
    Text = "Mythag'ın yavru köpeği, bunu senin şerefin say."
  },
  AvgVideoCaption_76210_Content_70 = {
    Text = "Özellikle benim için kurulmuş bir tuzak—bu kibirli, kendini haklı gören dâhi için."
  },
  AvgVideoCaption_76210_Content_71 = {
    Text = "Evet. O Tabletin tam merkezine gömülü, bir kapan çok uzun zamandır, sabırla ve sessizce bekliyordu."
  },
  AvgVideoCaption_76210_Content_72 = {
    Text = "Ve ben, hazdan ağlayarak, doğruca ona yürüdüm."
  },
  AvgVideoCaption_76210_Content_73 = {
    Text = "Gerçekte ne okuduğumu kavradığımda, artık çok geçti."
  },
  AvgVideoCaption_76210_Content_74 = {
    Text = "Her şeyi biliyordum. Cevabı biliyordum. ▼▼'yu biliyordum!!"
  },
  AvgVideoCaption_76210_Content_75 = {
    Text = "Hissedebiliyor musun?"
  },
  AvgVideoCaption_76210_Content_76 = {
    Text = "Bu dayanılmaz, kemiklere işleyen pain. Bu katlanılmaz umutsuzluk."
  },
  AvgVideoCaption_76210_Content_77 = {
    Text = "Zihni kıran türden bir umutsuzluk—zift karası, mutlak."
  },
  AvgVideoCaption_76210_Content_78 = {
    Text = "...Affet beni, Mythag'ın yavrusu. Yine kendimi kaybettim."
  },
  AvgVideoCaption_76210_Content_79 = {
    Text = "Ama için rahat olsun. Yöntem kaba olsa da, asgari etkinlik düzeyi kesinlikle sağlandı."
  },
  AvgVideoCaption_76210_Content_8 = {
    Text = "Spesifik sorun tespit edildi. Seçtiğin beyin kavanozu etkinlik seviyesi, bir Mythag Koruyucusunun bilincini sürdürmek için yetersiz."
  },
  AvgVideoCaption_76210_Content_80 = {
    Text = "Şimdi sensörü bağlayacağım."
  },
  AvgVideoCaption_76210_Content_81 = {
    Text = "Yakında, bu dünyaya gireceksin."
  },
  AvgVideoCaption_76210_Content_82 = {
    Text = "Öyleyse gözlerini açacağın ânı birlikte bekleyeceğiz. Merak ediyorum—gördüklerinin karşısına nasıl çıkacaksın?"
  },
  AvgVideoCaption_76210_Content_83 = {
    Text = "Kendimi bunu dört gözle beklerken buluyorum."
  },
  AvgVideoCaption_76210_Content_9 = {
    Text = "Ancak ikinci bir transfer, bilinç kaybı riskini kayda değer ölçüde artırır."
  },
  AvgVideoCaption_81062_Content_1 = {
    Text = "Sevgilim, beni takip et."
  },
  AvgVideoCaption_81062_Content_10 = {
    Text = "ayaklarının altında hışırdayan yapraklarla."
  },
  AvgVideoCaption_81062_Content_11 = {
    Text = "Nefesin üç saniye öncesine göre daha hafif mi?"
  },
  AvgVideoCaption_81062_Content_12 = {
    Text = "Yukarı bak..."
  },
  AvgVideoCaption_81062_Content_13 = {
    Text = "ormanların içinde bir kulübe şimdi önünde beliriyor."
  },
  AvgVideoCaption_81062_Content_14 = {
    Text = "Gıcırtılı merdivenlere adım at, o tanıdık ahşap kapıyı aç..."
  },
  AvgVideoCaption_81062_Content_15 = {
    Text = "Ateşin çıtırtısını dinle..."
  },
  AvgVideoCaption_81062_Content_16 = {
    Text = "İran halısını..."
  },
  AvgVideoCaption_81062_Content_17 = {
    Text = "koyu kızıl kadife kanepesini..."
  },
  AvgVideoCaption_81062_Content_18 = {
    Text = "Devrilmiş kadehi, dökülmüş şarabı..."
  },
  AvgVideoCaption_81062_Content_19 = {
    Text = "Tıpkı hatırladığın gibi..."
  },
  AvgVideoCaption_81062_Content_2 = {
    Text = "Karşımda, kanepenin üzerine otur."
  },
  AvgVideoCaption_81062_Content_20 = {
    Text = "Bir daha düşün..."
  },
  AvgVideoCaption_81062_Content_21 = {
    Text = "o kanepe gerçekten boş muydu?"
  },
  AvgVideoCaption_81062_Content_22 = {
    Text = "Acaba İran halısını lekeleyen gerçekten de yemekten önceki şarap mıydı?"
  },
  AvgVideoCaption_81062_Content_23 = {Text = "Sus..."},
  AvgVideoCaption_81062_Content_24 = {
    Text = "panikleme, kaçmaya çalışma."
  },
  AvgVideoCaption_81062_Content_25 = {
    Text = "Uzuvların henüz hazır değil."
  },
  AvgVideoCaption_81062_Content_26 = {
    Text = "Kulak ver..."
  },
  AvgVideoCaption_81062_Content_27 = {
    Text = "hisset—omurganın üçüncü ekleminde bir kaşıntı var mı?"
  },
  AvgVideoCaption_81062_Content_28 = {
    Text = "Ah, şimdi anıların geri geliyor..."
  },
  AvgVideoCaption_81062_Content_29 = {
    Text = "kanepedeki o çürüyen ceset—sevgili baban değil mi o?"
  },
  AvgVideoCaption_81062_Content_3 = {
    Text = "Şöminenin sıcaklığı hoşuna gidiyor mu?"
  },
  AvgVideoCaption_81062_Content_30 = {
    Text = "Unuttun mu? Unutmuş olabilir misin?"
  },
  AvgVideoCaption_81062_Content_31 = {
    Text = "Hayır, unutmadın..."
  },
  AvgVideoCaption_81062_Content_32 = {
    Text = "Hepsi sadece... şak..."
  },
  AvgVideoCaption_81062_Content_33 = {
    Text = "Sen sadece hepsini kilitleyip kaldırdın,"
  },
  AvgVideoCaption_81062_Content_34 = {
    Text = "küçük, gizli bir kutunun içinde."
  },
  AvgVideoCaption_81062_Content_35 = {
    Text = "Bu kabın sadakatini övmeliyim—"
  },
  AvgVideoCaption_81062_Content_36 = {
    Text = "yirmi yedi yıldır gerçek yüzünü gizliyor."
  },
  AvgVideoCaption_81062_Content_37 = {
    Text = "Seni neyin bağladığını merak ediyorum."
  },
  AvgVideoCaption_81062_Content_38 = {
    Text = "Kalbinin içindeki çığlıkları seslendir—"
  },
  AvgVideoCaption_81062_Content_39 = {
    Text = "arzularını, iştahlarını itiraf et."
  },
  AvgVideoCaption_81062_Content_4 = {
    Text = "Bu saat, bu kızıl kadife kanepe, tanıdık geliyor mu?"
  },
  AvgVideoCaption_81062_Content_40 = {
    Text = "Hepsini kucaklayacağız..."
  },
  AvgVideoCaption_81062_Content_41 = {
    Text = "Ahlak—ne sıkıcı bir kavram. İnsan sinapsları arasına dikilmiş ucuz bir olta misinası..."
  },
  AvgVideoCaption_81062_Content_42 = {
    Text = "Şimdi, nazikçe... nazikçe çıkarıyoruz kancayı amigdalandan... Çek... onu... dışarı..."
  },
  AvgVideoCaption_81062_Content_43 = {
    Text = "Söyle bana, sevgili dostum..."
  },
  AvgVideoCaption_81062_Content_44 = {
    Text = "Özgürlük uğruna... ve ardından kilidi açılan hazlar için—"
  },
  AvgVideoCaption_81062_Content_45 = {
    Text = "Ne yaptın?"
  },
  AvgVideoCaption_81062_Content_46 = {
    Text = "Yedi yaşındayken karanlık bodrumda geçen o otuz saniye... mumları üflediğin an..."
  },
  AvgVideoCaption_81062_Content_47 = {
    Text = "Gerçekte neyi görmekten korkuyordun?"
  },
  AvgVideoCaption_81062_Content_48 = {
    Text = "Kapının dışındaki ayak sesleri miydi..."
  },
  AvgVideoCaption_81062_Content_49 = {
    Text = "yoksa bastırdığın o gülümseme mi?"
  },
  AvgVideoCaption_81062_Content_5 = {
    Text = "Hastayı teskin etmek gayemizdir."
  },
  AvgVideoCaption_81062_Content_50 = {
    Text = "O boğulma “kazası”..."
  },
  AvgVideoCaption_81062_Content_51 = {
    Text = "kurbanın gölette çırpınırken,"
  },
  AvgVideoCaption_81062_Content_52 = {
    Text = "dudakların, ölüm dalgacıklarında parıldıyordu."
  },
  AvgVideoCaption_81062_Content_53 = {
    Text = "Şimdi, şimdi... çırpınma, sakin ol..."
  },
  AvgVideoCaption_81062_Content_54 = {
    Text = "Diğer beyefendinin nerede son bulduğunu bilmek istemezsin."
  },
  AvgVideoCaption_81062_Content_55 = {
    Text = "Sana bir ipucu—kilise bahçesindeki güller bu yıl özellikle kırmızı, öyle değil mi?"
  },
  AvgVideoCaption_81062_Content_56 = {
    Text = "Hehe. Aferin benim güzel çocuğuma."
  },
  AvgVideoCaption_81062_Content_57 = {
    Text = "Şimdi, elini benimkine koy..."
  },
  AvgVideoCaption_81062_Content_58 = {
    Text = "Evet, avucumun içinde..."
  },
  AvgVideoCaption_81062_Content_59 = {
    Text = "Dikkatle bak."
  },
  AvgVideoCaption_81062_Content_6 = {
    Text = "Şimdi sarkacı geç, ve bakışlarımla buluş."
  },
  AvgVideoCaption_81062_Content_60 = {
    Text = "Buna hâlâ bir el diyebilir misin?"
  },
  AvgVideoCaption_81062_Content_61 = {
    Text = "Yeni kitin dış iskeletin..."
  },
  AvgVideoCaption_81062_Content_62 = {
    Text = "...yakında bu zayıf, çaresiz kabuğu kaplayacak."
  },
  AvgVideoCaption_81062_Content_63 = {
    Text = "Şşş... bağırma."
  },
  AvgVideoCaption_81062_Content_64 = {
    Text = "Ses tellerini zorlama—henüz tam olarak dönüşmediler..."
  },
  AvgVideoCaption_81062_Content_65 = {
    Text = "Ahlakın zincirleri..."
  },
  AvgVideoCaption_81062_Content_66 = {
    Text = "Tek tek çıkıyorlar,"
  },
  AvgVideoCaption_81062_Content_67 = {
    Text = "tıpkı eski derisini atan bir yılan gibi..."
  },
  AvgVideoCaption_81062_Content_68 = {
    Text = "Az sonra özgürlüğüne kavuşacaksın..."
  },
  AvgVideoCaption_81062_Content_69 = {
    Text = "Sana kurtuluş bahşedeceğim..."
  },
  AvgVideoCaption_81062_Content_7 = {
    Text = "Derin bir nefes al—"
  },
  AvgVideoCaption_81062_Content_70 = {
    Text = "Evet... irislerin kusursuz altıgen dizilere bölünsün..."
  },
  AvgVideoCaption_81062_Content_71 = {
    Text = "Uyanan bu kadim kabı yüceltelim..."
  },
  AvgVideoCaption_81062_Content_72 = {
    Text = "Çürüyen geçmişe veda etmek için..."
  },
  AvgVideoCaption_81062_Content_73 = {
    Text = "haydi toplumsal maskeyi derişik sülfürik aside yatıralım..."
  },
  AvgVideoCaption_81062_Content_74 = {
    Text = "Gülünç banka hesapların ve diplomalarınla birlikte..."
  },
  AvgVideoCaption_81062_Content_75 = {
    Text = "onların, bir böcek yuvasının humusu gibi çözünüşünü izle."
  },
  AvgVideoCaption_81062_Content_76 = {
    Text = "Çok iyi, çok iyi..."
  },
  AvgVideoCaption_81062_Content_77 = {
    Text = "Derin bir nefes al."
  },
  AvgVideoCaption_81062_Content_78 = {
    Text = "Şimdi, benimle birlikte tekrar et:"
  },
  AvgVideoCaption_81062_Content_79 = {
    Text = "Homo sapiens'in aşağı gen zincirini kendi isteğimle soyup atıyorum..."
  },
  AvgVideoCaption_81062_Content_8 = {
    Text = "ateşin bileklerinden yukarı doğru tırmandığını hissedebiliyor musun?"
  },
  AvgVideoCaption_81062_Content_80 = {
    Text = "sinapsları böcek yuvası bulutuna bağlıyorum..."
  },
  AvgVideoCaption_81062_Content_81 = {
    Text = "Bizim için insanlık, yalnızca gülünç bir taklitten ibaret..."
  },
  AvgVideoCaption_81062_Content_82 = {
    Text = "tıpkı yaprak taklidi yapan bir kelebek gibi..."
  },
  AvgVideoCaption_81062_Content_83 = {
    Text = "Şimdi, böcek yuvasının ebedî rahmine dönme vakti."
  },
  AvgVideoCaption_81062_Content_84 = {
    Text = "En son ne zaman kalp atışını duydun?"
  },
  AvgVideoCaption_81062_Content_85 = {
    Text = "Sürünün kanatları, o zavallı ritmin yerini aldı..."
  },
  AvgVideoCaption_81062_Content_86 = {
    Text = "O eski, karbonlaşan cesede elveda de..."
  },
  AvgVideoCaption_81062_Content_87 = {
    Text = "Sen, hukuki anlamda “ölü” olan..."
  },
  AvgVideoCaption_81062_Content_88 = {
    Text = "on dakika içinde ilk böcek yuvası döllenme keseni alacaksın."
  },
  AvgVideoCaption_81062_Content_89 = {
    Text = "Gözlerini kapa"
  },
  AvgVideoCaption_81062_Content_9 = {
    Text = "Şimdi kendini Hyde Park’ta yürürken hayal et,"
  },
  AvgVideoCaption_81062_Content_90 = {
    Text = "Karanlığı kucakla"
  },
  AvgVideoCaption_81062_Content_91 = {
    Text = "Şimdi, gerçek gözlerini açma vakti..."
  },
  AvgVideoCaption_81062_Content_92 = {
    Text = "Tebrikler... artık Tanrı’ya herhangi bir insandan daha yakınsın"
  },
  AvgVideoCaption_81062_Content_93 = {
    Text = "360 derecelik bileşik gözlerden, kozmik Gerçek’i görerek..."
  },
  AvgVideoCaption_81062_Content_94 = {
    Text = "Ley Hattı’nın derinliklerindeki milyarlarca kalbin Rezonans’ına Hoş Geldin..."
  },
  AvgVideoCaption_81062_Content_95 = {
    Text = "Sen, Onların kusursuz aracı olacaksın..."
  },
  AvgVideoCaption_81062_Content_96 = {
    Text = "Yurduna hoş geldin."
  },
  AvgVideoCaption_81283_Content_1 = {
    Text = "Senin Pain’in..."
  },
  AvgVideoCaption_81283_Content_10 = {
    Text = "Ruhuna dokunayım—"
  },
  AvgVideoCaption_81283_Content_11 = {
    Text = "her gizli ıstıraba, her gömülü özleme."
  },
  AvgVideoCaption_81283_Content_12 = {
    Text = "Ah, işte geldik..."
  },
  AvgVideoCaption_81283_Content_13 = {
    Text = "Seansın en sevdiğim kısmına ulaştık."
  },
  AvgVideoCaption_81283_Content_14 = {
    Text = "Senin ağıdın, senin dehşetin, senin çaresizliğin—"
  },
  AvgVideoCaption_81283_Content_15 = {
    Text = "nörotransmitterlerin öyle... büyüleyici gerçekleri ele veriyor ki."
  },
  AvgVideoCaption_81283_Content_16 = {
    Text = "Ama bu yalnızca yüzey."
  },
  AvgVideoCaption_81283_Content_17 = {
    Text = "Daha derine inelim."
  },
  AvgVideoCaption_81283_Content_18 = {
    Text = "Katman katman, psişeni çözeceğiz."
  },
  AvgVideoCaption_81283_Content_19 = {
    Text = "Bana en ince işlenmiş umutsuzluğunu, en leziz çırpınışlarını göster..."
  },
  AvgVideoCaption_81283_Content_2 = {
    Text = "onu kendi acım gibi hissediyorum."
  },
  AvgVideoCaption_81283_Content_20 = {
    Text = "tefekkürüm için..."
  },
  AvgVideoCaption_81283_Content_21 = {
    Text = "...Ah, affınıza sığınırım."
  },
  AvgVideoCaption_81283_Content_22 = {
    Text = "Son hastayla... biraz fazla ileri gitmiş olabilirim."
  },
  AvgVideoCaption_81283_Content_23 = {
    Text = "Lütfen içeri gir. Konuğum ol."
  },
  AvgVideoCaption_81283_Content_24 = {
    Text = "Zihnin bu küçük yolculuğuna başlayalım."
  },
  AvgVideoCaption_81283_Content_3 = {
    Text = "O umutsuz yenilenme arzusunu anlıyorum."
  },
  AvgVideoCaption_81283_Content_4 = {
    Text = "Gel, her şeyi bana bırak."
  },
  AvgVideoCaption_81283_Content_5 = {
    Text = "Seni iyileştireceğim..."
  },
  AvgVideoCaption_81283_Content_6 = {
    Text = "en hakiki benliğini açığa çıkaracağım."
  },
  AvgVideoCaption_81283_Content_7 = {
    Text = "Şimdi, gevşe..."
  },
  AvgVideoCaption_81283_Content_8 = {
    Text = "Bana en içteki benliğini göster."
  },
  AvgVideoCaption_81283_Content_9 = {
    Text = "Bilinçdışını bana teslim et."
  },
  AvgVideoCaption_84327_Content_1 = {
    Text = "Batıyoruz! Aç şu lanet kapıyı!"
  },
  AvgVideoCaption_84327_Content_10 = {
    Text = "Artık Nautilus’un tek \"yolcusu\" o."
  },
  AvgVideoCaption_84327_Content_100 = {
    Text = "Ama artık insan değilim."
  },
  AvgVideoCaption_84327_Content_101 = {
    Text = "Böylece, beni çağıran kişi"
  },
  AvgVideoCaption_84327_Content_102 = {
    Text = "Bana yol gösterdi. Beni sahiplendi."
  },
  AvgVideoCaption_84327_Content_103 = {
    Text = "Boğulmuş krallık, karanlık akıntılarda tarihini fısıldadı."
  },
  AvgVideoCaption_84327_Content_104 = {
    Text = "Çatlamış put bana tek gerçek ilahi varlığı gösterdi."
  },
  AvgVideoCaption_84327_Content_105 = {
    Text = "Artık gerçeklik ve sanrılar birdir."
  },
  AvgVideoCaption_84327_Content_106 = {
    Text = "Tanrı için her şey boştur. Her şey anlamsızdır."
  },
  AvgVideoCaption_84327_Content_107 = {
    Text = "Deniz kucaklar, boğar, bana dönüşür."
  },
  AvgVideoCaption_84327_Content_108 = {
    Text = "Kapının ötesinde, sonsuz boşluklar görüyorum."
  },
  AvgVideoCaption_84327_Content_109 = {
    Text = "Derinlik zihnimi suyla doldurdu."
  },
  AvgVideoCaption_84327_Content_11 = {
    Text = "Sen... sen beni kurtardın mı?"
  },
  AvgVideoCaption_84327_Content_110 = {
    Text = "Düşünce çözünmeye başlar."
  },
  AvgVideoCaption_84327_Content_111 = {
    Text = "Bedenim gelgite boyun eğer."
  },
  AvgVideoCaption_84327_Content_112 = {
    Text = "Sonsuz bir hiçlik okyanusu..."
  },
  AvgVideoCaption_84327_Content_113 = {
    Text = "Artık bu, benim tek gerçek rotam."
  },
  AvgVideoCaption_84327_Content_12 = {
    Text = "Nautilus’a hoş geldin."
  },
  AvgVideoCaption_84327_Content_13 = {
    Text = "Ben Seyrüseferci Corposant."
  },
  AvgVideoCaption_84327_Content_14 = {
    Text = "Lütfen bu gemiye ve düzenine saygı göster."
  },
  AvgVideoCaption_84327_Content_15 = {
    Text = "Can filikanın numarasını ezberle—kamara anahtarına kazınmış olanı."
  },
  AvgVideoCaption_84327_Content_16 = {
    Text = "Her ne kadar kanuna göre, korsanlar böyle ayrıcalıkları yitirse de."
  },
  AvgVideoCaption_84327_Content_17 = {
    Text = "Özür dilerim."
  },
  AvgVideoCaption_84327_Content_18 = {
    Text = "Ha? Bu lanet anahtarla falan ilgili değil!"
  },
  AvgVideoCaption_84327_Content_19 = {
    Text = "Burası... Burası deniz!"
  },
  AvgVideoCaption_84327_Content_2 = {
    Text = "Yardım edin! Lütfen... yardım edin..."
  },
  AvgVideoCaption_84327_Content_20 = {
    Text = "Suyun altında nefes alıyorum! Ve bir şekilde hâlâ hayattayım!"
  },
  AvgVideoCaption_84327_Content_21 = {
    Text = "Tanrı... Herhalde delirdim."
  },
  AvgVideoCaption_84327_Content_22 = {
    Text = "Uyardıkları gibi... O lanetli fildişi put aklımı paramparça etti."
  },
  AvgVideoCaption_84327_Content_23 = {
    Text = "Ne put var! Ne Lemuria! Hepsi yalan! Bir rüya!"
  },
  AvgVideoCaption_84327_Content_24 = {
    Text = "Uyandığımda... yurdumda olacağım."
  },
  AvgVideoCaption_84327_Content_25 = {
    Text = "Yurt... evet, yurt..."
  },
  AvgVideoCaption_84327_Content_26 = {
    Text = "Artık içinde bulunduğun durumun farkında olmalısın."
  },
  AvgVideoCaption_84327_Content_27 = {
    Text = "Burası batmış Nautilus—burası derinlik."
  },
  AvgVideoCaption_84327_Content_28 = {
    Text = "Yakında, okyanusun dibine uzanacağız."
  },
  AvgVideoCaption_84327_Content_29 = {
    Text = "Canını elimden geldiğince uzatacağım."
  },
  AvgVideoCaption_84327_Content_3 = {
    Text = "Günlerden 12 Eylül’dü."
  },
  AvgVideoCaption_84327_Content_30 = {
    Text = "Ama seyrüseferci ve son tayfa olarak,"
  },
  AvgVideoCaption_84327_Content_31 = {
    Text = "Sana kendi sınırlarımı itiraf etmeliyim."
  },
  AvgVideoCaption_84327_Content_32 = {
    Text = "Sonrasında, korsan sustu."
  },
  AvgVideoCaption_84327_Content_33 = {
    Text = "Artık kaçma girişimi yoktu. Sadece su basmış lumbozun önünde dikildi,"
  },
  AvgVideoCaption_84327_Content_34 = {
    Text = "Sadece ötesindeki boşluğa mırıldandı."
  },
  AvgVideoCaption_84327_Content_35 = {
    Text = "Bazen gülerdi."
  },
  AvgVideoCaption_84327_Content_36 = {
    Text = "Bazense sayıklardı."
  },
  AvgVideoCaption_84327_Content_37 = {
    Text = "“Lemuria!” diye çığlık atardı."
  },
  AvgVideoCaption_84327_Content_38 = {
    Text = "“Lemuria beni çağırıyor!”"
  },
  AvgVideoCaption_84327_Content_39 = {
    Text = "Ya da “Anne... yurt...” diye inlerdi."
  },
  AvgVideoCaption_84327_Content_4 = {
    Text = "Nautilus, 791 gündür bir hayalet gemi gibi sürükleniyor."
  },
  AvgVideoCaption_84327_Content_40 = {
    Text = "Lemuria... yurt..."
  },
  AvgVideoCaption_84327_Content_41 = {
    Text = "Lemuria’ya dönmeliyim..."
  },
  AvgVideoCaption_84327_Content_42 = {
    Text = "Tüm uzun yolculuklarımda, \"Lemuria\" hiçbir haritada yoktu."
  },
  AvgVideoCaption_84327_Content_43 = {
    Text = "Korkarım tek yolcum"
  },
  AvgVideoCaption_84327_Content_44 = {
    Text = "artık denizcinin deliliğinden mustarip."
  },
  AvgVideoCaption_84327_Content_45 = {
    Text = "Denizin yaygın bir marazı."
  },
  AvgVideoCaption_84327_Content_46 = {
    Text = "Bir zamanlar cerrahımız Ralph’ın dediği gibi:"
  },
  AvgVideoCaption_84327_Content_47 = {
    Text = "\"Ölümlü zihin,"
  },
  AvgVideoCaption_84327_Content_48 = {
    Text = "derini kavrayamayacak kadar zayıf, kırılır.\""
  },
  AvgVideoCaption_84327_Content_49 = {
    Text = "Biz denizde yelken açmıyoruz,"
  },
  AvgVideoCaption_84327_Content_5 = {
    Text = "Issız kalmış korsanın kaçış girişimi başarısız oldu."
  },
  AvgVideoCaption_84327_Content_50 = {
    Text = "ama içinde—Nautilus’la birlikte karanlığa gömülerek."
  },
  AvgVideoCaption_84327_Content_51 = {
    Text = "Herhangi bir ruhu rayından çıkarmaya yeter."
  },
  AvgVideoCaption_84327_Content_52 = {
    Text = "Kendim de dahil..."
  },
  AvgVideoCaption_84327_Content_53 = {
    Text = "Ölü olsam da ruhum bu gemiye tutunuyor."
  },
  AvgVideoCaption_84327_Content_54 = {
    Text = "Korsanı kurtardım ve şimdi hayaletler beni de musallat biliyor."
  },
  AvgVideoCaption_84327_Content_55 = {
    Text = "Nautilus’un dönüşünü görüyorum..."
  },
  AvgVideoCaption_84327_Content_56 = {
    Text = "Ve onun batışını görüyorum..."
  },
  AvgVideoCaption_84327_Content_57 = {
    Text = "İlk başta, akıl yerindeydi."
  },
  AvgVideoCaption_84327_Content_58 = {
    Text = "Sanrılar ve gerçeklik ayrı kaldı."
  },
  AvgVideoCaption_84327_Content_59 = {Text = "Ta ki..."},
  AvgVideoCaption_84327_Content_6 = {
    Text = "Nautilus uçurumun derinliklerine daldıkça..."
  },
  AvgVideoCaption_84327_Content_60 = {
    Text = "Duydum onu... Onu duydum..."
  },
  AvgVideoCaption_84327_Content_61 = {
    Text = "Bize sesleniyor!"
  },
  AvgVideoCaption_84327_Content_62 = {
    Text = "Kaybolmuş olanlara, o rehberlik eder."
  },
  AvgVideoCaption_84327_Content_63 = {
    Text = "Özlem duyanlara, o karşılık verir."
  },
  AvgVideoCaption_84327_Content_64 = {
    Text = "Evet! Rehberim ol! Beni sahiplen!"
  },
  AvgVideoCaption_84327_Content_65 = {
    Text = "Yüce Rab, beni Lemuria’ya götür... İlahi krallığına!"
  },
  AvgVideoCaption_84327_Content_66 = {
    Text = "Sonsuz saadete, bitimsiz cana kavuşacağım yere!"
  },
  AvgVideoCaption_84327_Content_67 = {
    Text = "Yurda döneceğim! YURDUMA DÖNÜYORUM!"
  },
  AvgVideoCaption_84327_Content_68 = {
    Text = "Gerçekten de Ralph doğru söylemişti:"
  },
  AvgVideoCaption_84327_Content_69 = {
    Text = "\"Hiçbir ölümlü zihin denizin derinliğini kuşatamaz.\""
  },
  AvgVideoCaption_84327_Content_7 = {
    Text = "Doğrusunu istersen, korsanlardan tiksinirim."
  },
  AvgVideoCaption_84327_Content_70 = {
    Text = "İşte o tek gözlü kent yükseldiğinde,"
  },
  AvgVideoCaption_84327_Content_71 = {
    Text = "bunu sayıklamanın bir oyunu sandım."
  },
  AvgVideoCaption_84327_Content_72 = {
    Text = "Kelimelerin ve isimlerin ötesindeki bir şehir,"
  },
  AvgVideoCaption_84327_Content_73 = {
    Text = "seabed üzerindeki yaşlı parıltısı yayılıyordu."
  },
  AvgVideoCaption_84327_Content_74 = {
    Text = "Orada, karanlığın içinde, uyuyordu—bekleyiş içinde."
  },
  AvgVideoCaption_84327_Content_75 = {
    Text = "Sessiz. Hasta."
  },
  AvgVideoCaption_84327_Content_76 = {
    Text = "Bizi, yakalanmış sinekleri, ağına düşeceğimiz anı bekliyor."
  },
  AvgVideoCaption_84327_Content_77 = {Text = "Lemuria!"},
  AvgVideoCaption_84327_Content_78 = {
    Text = "Bu, LEMURIA!"
  },
  AvgVideoCaption_84327_Content_79 = {
    Text = "O çağırıyor! O ÇAĞIRIYOR!"
  },
  AvgVideoCaption_84327_Content_8 = {
    Text = "Bir geminin güvenli çıkışını tehdit eden herkes benim düşmanımdır."
  },
  AvgVideoCaption_84327_Content_80 = {
    Text = "Geri dönün! Gitmeyin!"
  },
  AvgVideoCaption_84327_Content_81 = {
    Text = "...Dinlemedi. Böylece benden önceki son yolcu da öldü."
  },
  AvgVideoCaption_84327_Content_82 = {
    Text = "Yalnızca fildişi put kaldı geriye."
  },
  AvgVideoCaption_84327_Content_83 = {
    Text = "Artık aklı başında seçimi biliyorum..."
  },
  AvgVideoCaption_84327_Content_84 = {Text = "Ama..."},
  AvgVideoCaption_84327_Content_85 = {
    Text = "Bir seyrüsefercinin görevi denizi bilmektir."
  },
  AvgVideoCaption_84327_Content_86 = {
    Text = "Zihnin haritaları yalan söylediğinde,"
  },
  AvgVideoCaption_84327_Content_87 = {
    Text = "kişi kaçmamalı, düzeltmelidir."
  },
  AvgVideoCaption_84327_Content_88 = {
    Text = "<Red:O hâlde, ona yaklaş>"
  },
  AvgVideoCaption_84327_Content_89 = {
    Text = "Hakikati haritalamak için, yapmam gereken..."
  },
  AvgVideoCaption_84327_Content_9 = {Text = "Ama..."},
  AvgVideoCaption_84327_Content_90 = {
    Text = "Hatanın ne olduğunu bilmeliyim. Mahiyetini kavramalıyım."
  },
  AvgVideoCaption_84327_Content_91 = {
    Text = "Bu yüzden, bir tanrının hafif uykuya yattığı bu diyarda yürümeliyim."
  },
  AvgVideoCaption_84327_Content_92 = {
    Text = "<Red:O hâlde, ona karşılık ver>"
  },
  AvgVideoCaption_84327_Content_93 = {
    Text = "Hiçbir toprak rotası saadete götürmez."
  },
  AvgVideoCaption_84327_Content_94 = {
    Text = "Yalnızca teslim olanlar ilahiliğe göz atar."
  },
  AvgVideoCaption_84327_Content_95 = {
    Text = "<Red:O hâlde, ona teslim ol!>"
  },
  AvgVideoCaption_84327_Content_96 = {
    Text = "<Red:Her şeyini sun!>"
  },
  AvgVideoCaption_84327_Content_97 = {
    Text = "Sonra—sunudan sonra—gördüm ki..."
  },
  AvgVideoCaption_84327_Content_98 = {
    Text = "Yıldızları cüceleştiren, adsız, biçimsiz olanı..."
  },
  AvgVideoCaption_84327_Content_99 = {
    Text = "\"Hiçbir ölümlü zihin denizin derinliğini kuşatamaz.\""
  },
  AvgVideoCaption_90244_Content_1 = {
    Text = "Hah... Hah..."
  },
  AvgVideoCaption_90244_Content_10 = {
    Text = "Kesikler derin... Kanatlar’ın kanla birbirine yapışmış."
  },
  AvgVideoCaption_90244_Content_100 = {
    Text = "el yazmasında olup da hiç görmediğimiz o kadar çok yer var ki. Gitmek istiyorum."
  },
  AvgVideoCaption_90244_Content_101 = {
    Text = "Bir gün gideceğiz. Bundan eminim."
  },
  AvgVideoCaption_90244_Content_102 = {
    Text = "Sonunda şövalye prensesi onun krallığına geri götürdü."
  },
  AvgVideoCaption_90244_Content_103 = {
    Text = "Onları karşılayan sokaklara çiçek yağdı."
  },
  AvgVideoCaption_90244_Content_104 = {
    Text = "Adı, görkemle tüm diyara yayıldı."
  },
  AvgVideoCaption_90244_Content_105 = {
    Text = "Ah. Demek mesele bu."
  },
  AvgVideoCaption_90244_Content_106 = {
    Text = "Hikâye bittikten sonra ne olduğunu hep merak ederim."
  },
  AvgVideoCaption_90244_Content_107 = {
    Text = "Ağabey, sence şövalyenin başına ne geldi?"
  },
  AvgVideoCaption_90244_Content_108 = {
    Text = "Şan, servet ve prensesin aşkını elde etti mi?"
  },
  AvgVideoCaption_90244_Content_109 = {
    Text = "Bilmiyorum..."
  },
  AvgVideoCaption_90244_Content_11 = {
    Text = "Önce kiri temizleyeceğim."
  },
  AvgVideoCaption_90244_Content_110 = {
    Text = "Ama en azından şan kazandı."
  },
  AvgVideoCaption_90244_Content_111 = {
    Text = "Sonra, prensesi ta uzaklardan kurtardıktan sonra,"
  },
  AvgVideoCaption_90244_Content_112 = {
    Text = "kral onu ödüllendirmiş olmalı, değil mi?"
  },
  AvgVideoCaption_90244_Content_113 = {
    Text = "Doğru, kral cimri birine benzemiyor."
  },
  AvgVideoCaption_90244_Content_114 = {
    Text = "Onunla birlikte şatodan kaçtı, bütün o toprakları dolaştı—"
  },
  AvgVideoCaption_90244_Content_115 = {
    Text = "belki prenses de ona vurulmuştur?"
  },
  AvgVideoCaption_90244_Content_116 = {
    Text = "Hmm... olabilir."
  },
  AvgVideoCaption_90244_Content_117 = {
    Text = "Şövalye hiçbir şey istemediğini söylese de,"
  },
  AvgVideoCaption_90244_Content_118 = {
    Text = "yine de her şeye sahip oldu."
  },
  AvgVideoCaption_90244_Content_119 = {
    Text = "Cesur insanlar gerçekten de... sonunda... her şeyle... yüz yüze kalıyor..."
  },
  AvgVideoCaption_90244_Content_12 = {
    Text = "...Acıyor, değil mi? Üzgünüm... Daha nazik olacağım."
  },
  AvgVideoCaption_90244_Content_120 = {
    Text = "(Uyumuş... Bu kaçış günleri onu iyice yıpratmış olmalı.)"
  },
  AvgVideoCaption_90244_Content_121 = {
    Text = "(Bu kadar çok kanat kayboldu... Ah, şu hâlâ sağlam.)"
  },
  AvgVideoCaption_90244_Content_122 = {
    Text = "(Bunu saklayacağım—belki sonra Pollux’tan bir kolye yaparım.)"
  },
  AvgVideoCaption_90244_Content_123 = {
    Text = "(Ay ne kadar yuvarlak, yıldızlar ne kadar parlak...)"
  },
  AvgVideoCaption_90244_Content_124 = {
    Text = "(Tıpkı kitaptaki gibi... Cesurlar gerçekten her şeye sahip olur mu?)"
  },
  AvgVideoCaption_90244_Content_125 = {
    Text = "(Hikâyeler yalan söylemez... değil mi?)"
  },
  AvgVideoCaption_90244_Content_126 = {
    Text = "(İyi geceler, Şövalye Pollux.)"
  },
  AvgVideoCaption_90244_Content_13 = {
    Text = "Ş-Şey, sorun yok."
  },
  AvgVideoCaption_90244_Content_14 = {
    Text = "O değiştirme ayiniyle kıyaslayınca... beni yardıklarında,"
  },
  AvgVideoCaption_90244_Content_15 = {
    Text = "ve organlarıma mühürler oyduklarında... bunun hiçbir şeyi yok."
  },
  AvgVideoCaption_90244_Content_16 = {
    Text = "...Evet. En çok acıya katlanan hep sendin."
  },
  AvgVideoCaption_90244_Content_17 = {
    Text = "(Lanet olsun, bunu söylememeliydim...)"
  },
  AvgVideoCaption_90244_Content_18 = {
    Text = "Artık hepsi geçmişte kaldı, Abi."
  },
  AvgVideoCaption_90244_Content_19 = {
    Text = "O zamanlar hiçbir şeye söz hakkımız yoktu. Ama şimdi... özgürüz!"
  },
  AvgVideoCaption_90244_Content_2 = {
    Text = "Canavar artık burada peşimize düşmemeli."
  },
  AvgVideoCaption_90244_Content_20 = {
    Text = "Lütfen, el yazmasındaki hikâyelerden birini yine anlat bana."
  },
  AvgVideoCaption_90244_Content_21 = {
    Text = "Her ayinden sonra yaptığın gibi. Dinlerken Pain kayboluyor."
  },
  AvgVideoCaption_90244_Content_22 = {Text = "Tamam"},
  AvgVideoCaption_90244_Content_23 = {
    Text = "O halde... sana efsanevi Şövalye'nin macerasının hikâyesini anlatayım."
  },
  AvgVideoCaption_90244_Content_24 = {
    Text = "Şövalye sonunda kaleye ulaştı ve gölgeli canavarla yüzleşti—"
  },
  AvgVideoCaption_90244_Content_25 = {
    Text = "prensesin nerede olduğunu bilmek için direterek."
  },
  AvgVideoCaption_90244_Content_26 = {
    Text = "Koyu yeşil yaratık dev gibiydi, muazzam bir kütleydi."
  },
  AvgVideoCaption_90244_Content_27 = {
    Text = "Titreşen bedeninin derinliklerinden Grotesk bir kükreme saldı."
  },
  AvgVideoCaption_90244_Content_28 = {
    Text = "Baltasını havaya kaldırdı."
  },
  AvgVideoCaption_90244_Content_29 = {
    Text = "Soğuk parıltı, hilal Ay gibi Sessiz Koridor’u yarıp geçti."
  },
  AvgVideoCaption_90244_Content_3 = {
    Text = "Bir ara verelim. Ah..."
  },
  AvgVideoCaption_90244_Content_30 = {
    Text = "Cesur şövalye yerinden kıpırdamadan durdu,"
  },
  AvgVideoCaption_90244_Content_31 = {
    Text = "Rüzgârda kıpırdayan tek şey, Altın saçlarıydı."
  },
  AvgVideoCaption_90244_Content_32 = {
    Text = "Balta bir Uluma ile aşağı indi—yalnızca şövalyenin boynuna varmadan durmak için."
  },
  AvgVideoCaption_90244_Content_33 = {
    Text = "\"Bu, sözünü tuttuğun için hak ettiğin darbe,\""
  },
  AvgVideoCaption_90244_Content_34 = {
    Text = "diye hırıltıyla konuştu canavar, Sesi paslı metalin sürtünmesine benzer."
  },
  AvgVideoCaption_90244_Content_35 = {
    Text = "\"Bugünkü düellodan kaçmadın. Şövalye unvanına yaraşır.\""
  },
  AvgVideoCaption_90244_Content_36 = {
    Text = "Ah! Tıpkı bugün canavarın bizi yenmesine izin vermeyişimiz gibi!"
  },
  AvgVideoCaption_90244_Content_37 = {
    Text = "İkinci savuruş aşağı indi—"
  },
  AvgVideoCaption_90244_Content_38 = {
    Text = "...ama yine, bir kıl payı kala durdu; şövalyenin tenini yalnızca hafifçe sıyırıp geçti..."
  },
  AvgVideoCaption_90244_Content_39 = {
    Text = "Pollux, en uzun uçuş Kanadın bile yırtıldı."
  },
  AvgVideoCaption_90244_Content_4 = {
    Text = "Pollux! Kanatların çok kötü yaralanmış..."
  },
  AvgVideoCaption_90244_Content_40 = {
    Text = "Onlara hep çok iyi baktın..."
  },
  AvgVideoCaption_90244_Content_41 = {
    Text = "Önemli değil. Kanatlar yeniden çıkar. Artık özgürlüğün nişanı onlar."
  },
  AvgVideoCaption_90244_Content_42 = {
    Text = "Tıpkı bir şövalyeninki gibi, değil mi?"
  },
  AvgVideoCaption_90244_Content_43 = {
    Text = "Evet, doğru... Yara artık temiz."
  },
  AvgVideoCaption_90244_Content_44 = {
    Text = "Kanatların darmadağın olmuş... İzin ver, düzelteyim."
  },
  AvgVideoCaption_90244_Content_45 = {
    Text = "Teşekkürler, Şövalye Castor!"
  },
  AvgVideoCaption_90244_Content_46 = {
    Text = "Şimdi lütfen! Macera hikâyesine devam edin!"
  },
  AvgVideoCaption_90244_Content_47 = {
    Text = "Pekâlâ, başlıyoruz."
  },
  AvgVideoCaption_90244_Content_48 = {
    Text = "Canavarın gözlerinde bir şükran parıltısı çaktı."
  },
  AvgVideoCaption_90244_Content_49 = {
    Text = "\"Bu, çocuğumu kurtardığın için... sonra da ondan anahtarı çalıp gizlice şatıma sızdığın için cezalandırmandır.\""
  },
  AvgVideoCaption_90244_Content_5 = {
    Text = "Lanet olsun... Onu engellemeliydim. Keşke—"
  },
  AvgVideoCaption_90244_Content_50 = {
    Text = "Şövalye birden her şeyi anladı."
  },
  AvgVideoCaption_90244_Content_51 = {
    Text = "\"Nehirdeki o kız çocuğu... O senin çocuğundu!\""
  },
  AvgVideoCaption_90244_Content_52 = {
    Text = "Canavar başını salladı."
  },
  AvgVideoCaption_90244_Content_53 = {
    Text = "\"Evet. Ve son darbe... gerçek savaşımız olacak.\""
  },
  AvgVideoCaption_90244_Content_54 = {
    Text = "Şövalye kılıcını kaldırıp selam verdi, bıçağı göğe doğru uzanmıştı."
  },
  AvgVideoCaption_90244_Content_55 = {
    Text = "Ama tam o anda, canavarın silueti aniden yok oldu."
  },
  AvgVideoCaption_90244_Content_56 = {
    Text = "Dikkatle, şövalye ilerledi."
  },
  AvgVideoCaption_90244_Content_57 = {
    Text = "Çarpık bir gölge, artık bomboş olan şatonun üzerine sürünerek yayıldı."
  },
  AvgVideoCaption_90244_Content_58 = {
    Text = "Yalnızca canavarın boş sesi yankılandı:"
  },
  AvgVideoCaption_90244_Content_59 = {
    Text = "\"Cesur şövalye... seni dövüşmeye iten nedir?"
  },
  AvgVideoCaption_90244_Content_6 = {
    Text = "Böyle söyleme, Pollux. Bu, ilk kez dışarı çıkışımızdı."
  },
  AvgVideoCaption_90244_Content_60 = {
    Text = "\"Şan için mi? Övgü için mi?\""
  },
  AvgVideoCaption_90244_Content_61 = {
    Text = "Onu çevreleyerek bir halk belirdi,"
  },
  AvgVideoCaption_90244_Content_62 = {
    Text = "sayısız yüz, cesaretini överken ışıl ışıl gülümsüyordu."
  },
  AvgVideoCaption_90244_Content_63 = {
    Text = "Şövalye düşü gördü, içini okudu—"
  },
  AvgVideoCaption_90244_Content_64 = {
    Text = "İfadesi sarsılmadan, onları yarıp geçti."
  },
  AvgVideoCaption_90244_Content_65 = {
    Text = "\"Öyleyse, ödüller ve zenginlikler için mi?\""
  },
  AvgVideoCaption_90244_Content_66 = {
    Text = "Mütevazı bir hizmetkâr yaklaştı,"
  },
  AvgVideoCaption_90244_Content_67 = {
    Text = "parıldayan paralar ve kızıl ışığa bulanmış mücevherli bir taç sunuyorlardı—"
  },
  AvgVideoCaption_90244_Content_68 = {
    Text = "Yere kapanarak gizli hazineyi sundu."
  },
  AvgVideoCaption_90244_Content_69 = {
    Text = "Şövalye, zenginlik ve güç sembollerine göz ucuyla bile bakmadı."
  },
  AvgVideoCaption_90244_Content_7 = {
    Text = "Hem, buradan sağ çıktık, değil mi? Neşelen! Harika iş çıkardık!"
  },
  AvgVideoCaption_90244_Content_70 = {
    Text = "Hizmetkârın düşünü tek bir darbeyle biçip dağıttı."
  },
  AvgVideoCaption_90244_Content_71 = {
    Text = "Canavar alayla sırıttı: \"Öyle mi? Yoksa... prensesin aşkı için mi?\""
  },
  AvgVideoCaption_90244_Content_72 = {
    Text = "Prenses onun önünde belirdi—"
  },
  AvgVideoCaption_90244_Content_73 = {
    Text = "uzun kirpikleri kanat çırparken, onun kollarına yaslanmış, gözleri rüya doluydu."
  },
  AvgVideoCaption_90244_Content_74 = {
    Text = "Şövalye bıçağını onun düşünün içinden savurdu."
  },
  AvgVideoCaption_90244_Content_75 = {
    Text = "\"Hayır. Hiçbiri değil. Ben acıyı sona erdirmek için dövüşüyorum—başkalarının bir daha asla dövüşmek zorunda kalmaması için!\""
  },
  AvgVideoCaption_90244_Content_76 = {
    Text = "Şövalyenin sözleri silinip giderken,"
  },
  AvgVideoCaption_90244_Content_77 = {
    Text = "sayısız gölgeli uzantı ve canlıymış gibi görünen düşler yok olup gitti."
  },
  AvgVideoCaption_90244_Content_78 = {
    Text = "Bir şangırtıyla, kılıcı canavarın baltasına çarptı ve onu havaya savurdu."
  },
  AvgVideoCaption_90244_Content_79 = {
    Text = "\"Merhametini, sadakatini ve iffeti kanıtladın.\""
  },
  AvgVideoCaption_90244_Content_8 = {
    Text = "...Haklısın. Önce yarana bakmama izin ver."
  },
  AvgVideoCaption_90244_Content_80 = {
    Text = "\"Şimdi, prensesi götürebilirsin.\""
  },
  AvgVideoCaption_90244_Content_81 = {
    Text = "Dehşet verici hayalet, duman kıvrımlarına çözündü,"
  },
  AvgVideoCaption_90244_Content_82 = {
    Text = "geride yalnızca, pasla yeşile dönmüş kadim bir zırh bırakarak."
  },
  AvgVideoCaption_90244_Content_83 = {
    Text = "Şövalye zırha derin bir saygıyla eğildi,"
  },
  AvgVideoCaption_90244_Content_84 = {
    Text = "sonra spiral merdivenleri adım adım tırmandı."
  },
  AvgVideoCaption_90244_Content_85 = {
    Text = "Şatonun zirvesinde prensesi buldu."
  },
  AvgVideoCaption_90244_Content_86 = {
    Text = "Şatoda kapana kısılmış... O da bir zamanlar tıpkı bizim gibiydi."
  },
  AvgVideoCaption_90244_Content_87 = {
    Text = "Ama bizi kurtarmaya hiçbir şövalye gelmedi..."
  },
  AvgVideoCaption_90244_Content_88 = {
    Text = "Kendimizi kurtardık."
  },
  AvgVideoCaption_90244_Content_89 = {
    Text = "Kendi şövalyelerimiz olduk!"
  },
  AvgVideoCaption_90244_Content_9 = {Text = "Elbette."},
  AvgVideoCaption_90244_Content_90 = {
    Text = "Aynen! Hahaha!"
  },
  AvgVideoCaption_90244_Content_91 = {
    Text = "Yani, eğer prenses bir kılıç kaldıracak kadar cesur olsaydı,"
  },
  AvgVideoCaption_90244_Content_92 = {
    Text = "bu hikâye hiç şövalyeye ihtiyaç duymazdı."
  },
  AvgVideoCaption_90244_Content_93 = {
    Text = "Doğru, ama burada şövalye yine de prensesi kurtardı."
  },
  AvgVideoCaption_90244_Content_94 = {
    Text = "Onu atının terkisine aldı, uçsuz bucaksız ay ışıklı göğün altında dörtnala sürdü."
  },
  AvgVideoCaption_90244_Content_95 = {
    Text = "Sonsuz çayırları ve berrak dereleri aştılar,"
  },
  AvgVideoCaption_90244_Content_96 = {
    Text = "heybetli sıradağların ve gür ormanların yanından geçti."
  },
  AvgVideoCaption_90244_Content_97 = {
    Text = "Çayırlar, sıradağlar..."
  },
  AvgVideoCaption_90244_Content_98 = {
    Text = "Nereye gitsek acaba?"
  },
  AvgVideoCaption_90244_Content_99 = {
    Text = "Ve deniz, çöller, tarlalar ve meralar—"
  },
  AvgVideoCaption_96010_Content_1 = {
    Text = "Ah, Hoş Geldin, Bay Pickman."
  },
  AvgVideoCaption_96010_Content_10 = {Text = "Ama..."},
  AvgVideoCaption_96010_Content_100 = {Text = "Elbette"},
  AvgVideoCaption_96010_Content_101 = {
    Text = "Yemeye devam edin, Bay Pickman. Yiyin."
  },
  AvgVideoCaption_96010_Content_102 = {
    Text = "Etini ve Kemiğini parçala, kalbini kopar."
  },
  AvgVideoCaption_96010_Content_103 = {
    Text = "Kulağında yalvaran Ruh'ları dinle."
  },
  AvgVideoCaption_96010_Content_104 = {
    Text = "Şahit olduğun her sahneyi sadakatle kaydet..."
  },
  AvgVideoCaption_96010_Content_105 = {
    Text = "Bir gulyabani olmanın görkeminin tadını çıkar."
  },
  AvgVideoCaption_96010_Content_106 = {
    Text = "Tebamın son ferdine kadar..."
  },
  AvgVideoCaption_96010_Content_107 = {
    Text = "bu zalim ebediyet için yaşar!"
  },
  AvgVideoCaption_96010_Content_108 = {
    Text = "Ah, bu enfes akşam yemeği de sona ermeli."
  },
  AvgVideoCaption_96010_Content_109 = {
    Text = "Ama bu seneki Ruh Bayramı'nda, eminim senden de görkemli bir sanat eseri göreceğiz."
  },
  AvgVideoCaption_96010_Content_11 = {
    Text = "Açık konuşmama izin verin, Bay Pickman,"
  },
  AvgVideoCaption_96010_Content_110 = {
    Text = "Necrovia Şehri'ne hoş geldin, geleceğin maestroları..."
  },
  AvgVideoCaption_96010_Content_111 = {
    Text = "Bay Pickman."
  },
  AvgVideoCaption_96010_Content_12 = {
    Text = "geçmiş çalışmalarınızın hepsi klişe birer çöptü,"
  },
  AvgVideoCaption_96010_Content_13 = {
    Text = "ahmak kalabalığın zevklerine zincirlenmişti."
  },
  AvgVideoCaption_96010_Content_14 = {
    Text = "Ve tam da bu yüzden sizi buraya davet ettim."
  },
  AvgVideoCaption_96010_Content_15 = {
    Text = "Büyük şenliğimiz bir başyapıt talep ediyor,"
  },
  AvgVideoCaption_96010_Content_16 = {
    Text = "ve siz... sizin Gerçek Sanat’ın ne olduğunu görmeniz gerekiyor."
  },
  AvgVideoCaption_96010_Content_17 = {
    Text = "Bir insan cesedi mi?"
  },
  AvgVideoCaption_96010_Content_18 = {
    Text = "Bu da mı..."
  },
  AvgVideoCaption_96010_Content_19 = {
    Text = "Kokuyu alıyor musun?"
  },
  AvgVideoCaption_96010_Content_2 = {
    Text = "Lütfen oturun."
  },
  AvgVideoCaption_96010_Content_20 = {
    Text = "Meşe, sedir ve vetiverin zinde ruh kokusu."
  },
  AvgVideoCaption_96010_Content_21 = {
    Text = "Üç yüzyıldır bu tabuta batmış durumda,"
  },
  AvgVideoCaption_96010_Content_22 = {
    Text = "bu yüzden bu geceki ana yemek olma onurunu kazandı."
  },
  AvgVideoCaption_96010_Content_23 = {
    Text = "Şimdi, birkaç gerekli hazırlık:"
  },
  AvgVideoCaption_96010_Content_24 = {
    Text = "Boyun ve omurga boyunca yarım inçlik bir kesim,"
  },
  AvgVideoCaption_96010_Content_25 = {
    Text = "eti kemikten ayırıyorum..."
  },
  AvgVideoCaption_96010_Content_26 = {
    Text = "Ne yapıyorsun? Onun organları..."
  },
  AvgVideoCaption_96010_Content_27 = {
    Text = "SİKTİR! Bu kadar, ben yokum!..."
  },
  AvgVideoCaption_96010_Content_28 = {
    Text = "Ne yapıyorsun... Bırak beni!"
  },
  AvgVideoCaption_96010_Content_29 = {
    Text = "Şşş. Sessiz olun, Bay Ressam."
  },
  AvgVideoCaption_96010_Content_3 = {
    Text = "Gulyabani kralının malikanesinde görülecek bir Gerçek Sanat’tan söz edildiğini duydum."
  },
  AvgVideoCaption_96010_Content_30 = {
    Text = "Malzememin ruhunu rahatsız ettin ve sanatsal çabamı sekteye uğratıyorsun."
  },
  AvgVideoCaption_96010_Content_31 = {
    Text = "Özellikle organlarının sağlam bırakılmasını emretmiştim."
  },
  AvgVideoCaption_96010_Content_32 = {
    Text = "Bir bedenin içindeyken, birbirine dolanmış ve kirli olurlar."
  },
  AvgVideoCaption_96010_Content_33 = {
    Text = "Ama uygun hazırlığın ardından, yemeğin en asil ve en ilgi çekici parçasına yükselecekler."
  },
  AvgVideoCaption_96010_Content_34 = {
    Text = "Buyurun, Bay Pickman."
  },
  AvgVideoCaption_96010_Content_35 = {
    Text = "Bu kalp parçası size ait."
  },
  AvgVideoCaption_96010_Content_36 = {
    Text = "Hayır... Ben... Ben..."
  },
  AvgVideoCaption_96010_Content_37 = {
    Text = "Buraya ilham için geldim..."
  },
  AvgVideoCaption_96010_Content_38 = {
    Text = "Bir ceset yemekle sanatın ne ilgisi var?"
  },
  AvgVideoCaption_96010_Content_39 = {
    Text = "Yaratımınla bir olmanı sağlar."
  },
  AvgVideoCaption_96010_Content_4 = {
    Text = "İnsan dünyasından buraya gelebilmek için her şeyi geride bıraktım."
  },
  AvgVideoCaption_96010_Content_40 = {
    Text = "Gulyaları anlamak için. Bir gul olmak için."
  },
  AvgVideoCaption_96010_Content_41 = {
    Text = "Ancak o zaman fırçan gerçek güzelliğe dokunabilir."
  },
  AvgVideoCaption_96010_Content_42 = {
    Text = "Bunu hep biliyordun. Bu, yaratımın nihai gerçeği."
  },
  AvgVideoCaption_96010_Content_43 = {
    Text = "İnsan dünyasını terk edip benim krallığıma gelişinin sebebi de bu değil mi?"
  },
  AvgVideoCaption_96010_Content_44 = {
    Text = "Elbette, ama..."
  },
  AvgVideoCaption_96010_Content_45 = {
    Text = "Tadına bakın, Bay Pickman."
  },
  AvgVideoCaption_96010_Content_46 = {
    Text = "Sanat uğruna."
  },
  AvgVideoCaption_96010_Content_47 = {
    Text = "Bu da mı..."
  },
  AvgVideoCaption_96010_Content_48 = {
    Text = "Evet, Bay Pickman."
  },
  AvgVideoCaption_96010_Content_49 = {
    Text = "Bu, yenilen kişinin ruhudur,"
  },
  AvgVideoCaption_96010_Content_5 = {
    Text = "Ama şu zevksiz yemek mekânı mı?"
  },
  AvgVideoCaption_96010_Content_50 = {
    Text = "kulağına fısıldayan."
  },
  AvgVideoCaption_96010_Content_51 = {Text = "R-Ruh mu?"},
  AvgVideoCaption_96010_Content_52 = {
    Text = "İnsanlar bize sık sık leş yiyiciler der,"
  },
  AvgVideoCaption_96010_Content_53 = {
    Text = "ama biz çürümüş ete aç değiliz."
  },
  AvgVideoCaption_96010_Content_54 = {
    Text = "Biz onun altındaki ruha açız."
  },
  AvgVideoCaption_96010_Content_55 = {
    Text = "Mezarlara gömülü o kıymetli anılara."
  },
  AvgVideoCaption_96010_Content_56 = {
    Text = "Bay Pickman, parmak uçların titriyor."
  },
  AvgVideoCaption_96010_Content_57 = {
    Text = "Korkunu görüyorum. Heyecanını da."
  },
  AvgVideoCaption_96010_Content_58 = {
    Text = "Bu kalbi yut."
  },
  AvgVideoCaption_96010_Content_59 = {
    Text = "Şimdi söyle, ne görüyorsun?"
  },
  AvgVideoCaption_96010_Content_6 = {
    Text = "İlham için tam anlamıyla bir mezarlıktan farksız."
  },
  AvgVideoCaption_96010_Content_60 = {
    Text = "Anlıyorum..."
  },
  AvgVideoCaption_96010_Content_61 = {
    Text = "Bir insan krallığı görüyorum. Ölümsüzlük arayan bir kral..."
  },
  AvgVideoCaption_96010_Content_62 = {
    Text = "Bu yeri o buldu."
  },
  AvgVideoCaption_96010_Content_63 = {
    Text = "Şehrine insan ordusuyla saldırdı!"
  },
  AvgVideoCaption_96010_Content_64 = {Text = "Kan..."},
  AvgVideoCaption_96010_Content_65 = {
    Text = "Kopmuş uzuvlar..."
  },
  AvgVideoCaption_96010_Content_66 = {
    Text = "Bir katliam..."
  },
  AvgVideoCaption_96010_Content_67 = {
    Text = "Sizdiniz, Bay Doresain..."
  },
  AvgVideoCaption_96010_Content_68 = {
    Text = "Onun cesedine sarılmıştınız..."
  },
  AvgVideoCaption_96010_Content_69 = {
    Text = "İkiniz ay ışığında dans etmiştiniz..."
  },
  AvgVideoCaption_96010_Content_7 = {
    Text = "Resimlerinizi gördüm."
  },
  AvgVideoCaption_96010_Content_70 = {
    Text = "tıpkı bu geceki kadar parlak bir ay ışığında..."
  },
  AvgVideoCaption_96010_Content_71 = {
    Text = "Sen... Gulyabani... Dans partnerlerini yutuyordun!"
  },
  AvgVideoCaption_96010_Content_72 = {
    Text = "Evet, o yiğit savaş beyi..."
  },
  AvgVideoCaption_96010_Content_73 = {
    Text = "Ordusuyla istediği her şeyi ele geçirdi,"
  },
  AvgVideoCaption_96010_Content_74 = {
    Text = "yine de tatmin olmadı."
  },
  AvgVideoCaption_96010_Content_75 = {
    Text = "Krallığımdan ölümsüzlüğü çalmaya kalkıştı."
  },
  AvgVideoCaption_96010_Content_76 = {
    Text = "Ne yazık ki, asla fark edemedi ki..."
  },
  AvgVideoCaption_96010_Content_77 = {
    Text = "Ölümsüzlüğe, kendi etimizi sofraya sunarak erişiriz,"
  },
  AvgVideoCaption_96010_Content_78 = {
    Text = "başkasının hafızasında sonsuz bir yaşamla takas ederek."
  },
  AvgVideoCaption_96010_Content_79 = {
    Text = "Kendi soyumuzun bedenlerini parçalara ayırır, ruhlarına diş geçiririz,"
  },
  AvgVideoCaption_96010_Content_8 = {
    Text = "O çılgın çizgilerin içinde gizlenen Yetenek ve tutku..."
  },
  AvgVideoCaption_96010_Content_80 = {
    Text = "ve onların Anılarını kendi etimizde saklarız,"
  },
  AvgVideoCaption_96010_Content_81 = {
    Text = "bir gün bir başkası tarafından yutulacak bir ziyafet bu..."
  },
  AvgVideoCaption_96010_Content_82 = {
    Text = "Tek bir öğün, ne kadar da kısa."
  },
  AvgVideoCaption_96010_Content_83 = {
    Text = "Yine de bu gelip geçici Haz'ın içinde,"
  },
  AvgVideoCaption_96010_Content_84 = {
    Text = "gerçek ebediyete erişiriz."
  },
  AvgVideoCaption_96010_Content_85 = {
    Text = "Kaçmak zarif bir Seçim değil,"
  },
  AvgVideoCaption_96010_Content_86 = {
    Text = "Sence de öyle değil mi? Ey yüce insan Hükümdar?"
  },
  AvgVideoCaption_96010_Content_87 = {
    Text = "Onun çığlıklarını duyabiliyor musun, Bay Pickman?"
  },
  AvgVideoCaption_96010_Content_88 = {
    Text = "O Pain içinde, o Haz içinde..."
  },
  AvgVideoCaption_96010_Content_89 = {
    Text = "Bu, bir kralın ebediyete çağrısıdır."
  },
  AvgVideoCaption_96010_Content_9 = {
    Text = "beni bile etkilediler."
  },
  AvgVideoCaption_96010_Content_90 = {
    Text = "Bu, bir Ziyafet'in gurmeye çağrısıdır."
  },
  AvgVideoCaption_96010_Content_91 = {
    Text = "Evet, o bize aç..."
  },
  AvgVideoCaption_96010_Content_92 = {
    Text = "Tıpkı bizim... ona aç olduğumuz gibi."
  },
  AvgVideoCaption_96010_Content_93 = {
    Text = "Ebediyet için geldi. Ve ben ona tam da bunu bahşettim!"
  },
  AvgVideoCaption_96010_Content_94 = {
    Text = "Bu kurşuni Ruh'un fosforlu parıltısı..."
  },
  AvgVideoCaption_96010_Content_95 = {
    Text = "parıldayan, canlı Kan..."
  },
  AvgVideoCaption_96010_Content_96 = {
    Text = "böyle bir manzaraya hangi pigment denk düşebilir?"
  },
  AvgVideoCaption_96010_Content_97 = {
    Text = "Fırçam... Boyam nerede?!"
  },
  AvgVideoCaption_96010_Content_98 = {
    Text = "Lütfen gitmeme izin verin, Bay Doresain!"
  },
  AvgVideoCaption_96010_Content_99 = {
    Text = "Daha önce hiç görülmemiş başyapıtlar yaratacağım!"
  },
  AvgVideoCaption_96789_Content_1 = {
    Text = "Ziyafet çekmek, öğrendiğimiz ilk sanattır."
  },
  AvgVideoCaption_96789_Content_10 = {
    Text = "Büyümeni bekleyeceğim..."
  },
  AvgVideoCaption_96789_Content_11 = {Text = "Eskimiş"},
  AvgVideoCaption_96789_Content_12 = {Text = "Tomurcuk"},
  AvgVideoCaption_96789_Content_13 = {
    Text = "Lütfen elimi tut..."
  },
  AvgVideoCaption_96789_Content_14 = {
    Text = "Nefis lokmam, leziz sevgilim"
  },
  AvgVideoCaption_96789_Content_15 = {
    Text = "Bu nazik okşayışın içinde,"
  },
  AvgVideoCaption_96789_Content_16 = {
    Text = "Kader saati, sonunda olgunlaşacak"
  },
  AvgVideoCaption_96789_Content_17 = {
    Text = "Yalvarırım, kendini bana sun..."
  },
  AvgVideoCaption_96789_Content_18 = {
    Text = "Kokulu bedenini sun"
  },
  AvgVideoCaption_96789_Content_19 = {
    Text = "Bağımlılık yaratan etini sun!"
  },
  AvgVideoCaption_96789_Content_2 = {
    Text = "Sus... sadece bedeninle hisset..."
  },
  AvgVideoCaption_96789_Content_20 = {
    Text = "Yenilmek, öğreneceğin son sanat olacak"
  },
  AvgVideoCaption_96789_Content_21 = {
    Text = "Kokuyu alıyor musun?"
  },
  AvgVideoCaption_96789_Content_22 = {
    Text = "Bir sonraki yemekte..."
  },
  AvgVideoCaption_96789_Content_23 = {
    Text = "O koku, sana özgü olan mı?"
  },
  AvgVideoCaption_96789_Content_3 = {
    Text = "Alevlerin şefkatli yalayışını üzerinde hisset"
  },
  AvgVideoCaption_96789_Content_4 = {
    Text = "Dudaklarımın, dişlerimin okşayışının tadını çıkar,"
  },
  AvgVideoCaption_96789_Content_5 = {
    Text = "tenine ve iç organlarına tapınırken"
  },
  AvgVideoCaption_96789_Content_6 = {
    Text = "Bu ay ışığında,"
  },
  AvgVideoCaption_96789_Content_7 = {
    Text = "korku dolu nefesini duyuyorum..."
  },
  AvgVideoCaption_96789_Content_8 = {
    Text = "Ah, ürperişe gerek yok"
  },
  AvgVideoCaption_96789_Content_9 = {
    Text = "En derin sabırla bekleyeceğim"
  },
  AvgVideoCaption_98516_Content_1 = {
    Text = "Ugh, burası ne kadar da nemli... kaynayan bir kazan gibi."
  },
  AvgVideoCaption_98516_Content_10 = {Text = "Geldik."},
  AvgVideoCaption_98516_Content_11 = {
    Text = "@1@2 Ayin Alanı—Oniks Kurban Düzlüğü."
  },
  AvgVideoCaption_98516_Content_12 = {
    Text = "Aynı o eski kan kokusu."
  },
  AvgVideoCaption_98516_Content_13 = {
    Text = "Bakalım elimizde neler var..."
  },
  AvgVideoCaption_98516_Content_14 = {
    Text = "İçi oyulmuş balmumu bebekler, bağırsakları pürüzsüzce çıkarılmış."
  },
  AvgVideoCaption_98516_Content_15 = {
    Text = "yüzsüz ucubeler,"
  },
  AvgVideoCaption_98516_Content_16 = {
    Text = "dikiş dikiş birleştirilmiş kimera yaratıklar,"
  },
  AvgVideoCaption_98516_Content_17 = {
    Text = "ters yüz edilmiş kemikler..."
  },
  AvgVideoCaption_98516_Content_18 = {
    Text = "...saksı olmuş bitkiler?"
  },
  AvgVideoCaption_98516_Content_19 = {
    Text = "Bir kas yumağı..."
  },
  AvgVideoCaption_98516_Content_2 = {
    Text = "Tüylerimi diken diken ediyor..."
  },
  AvgVideoCaption_98516_Content_20 = {
    Text = "Deriyi yüzüp kasları kızgın bir dağlama demiriyle birbirine mi kaynatmışlar?"
  },
  AvgVideoCaption_98516_Content_21 = {
    Text = "Ses telleri lime lime edilmiş."
  },
  AvgVideoCaption_98516_Content_22 = {
    Text = "Demek \"çığlık en iyi Sunu’dur\" fikrinin hayranı değillermiş."
  },
  AvgVideoCaption_98516_Content_23 = {Text = "Ha?"},
  AvgVideoCaption_98516_Content_24 = {Text = "Bu kese..."},
  AvgVideoCaption_98516_Content_25 = {
    Text = "...Sert kısımları ezmişler,"
  },
  AvgVideoCaption_98516_Content_26 = {
    Text = "İç organları yumuşatsın diye içeri sıvı basıp sonra hepsini bir keseye mi tıkmışlar?"
  },
  AvgVideoCaption_98516_Content_27 = {
    Text = "Üzerinde yazıyor ki... “32. Ayin Dolgu Malzemesi: LT-13."
  },
  AvgVideoCaption_98516_Content_28 = {
    Text = "Yeni süreç benimsendi, ikincil malzeme: DT-13..."
  },
  AvgVideoCaption_98516_Content_29 = {
    Text = "Bu... LT-13’ün üç reşit olmayan çocuğu."
  },
  AvgVideoCaption_98516_Content_3 = {
    Text = "Heh, bu da senin namının ne kadar sarsılmaz olduğunu kanıtlıyor, Abla."
  },
  AvgVideoCaption_98516_Content_30 = {
    Text = "Bu sapık herifler hiç değişmiyor."
  },
  AvgVideoCaption_98516_Content_31 = {
    Text = "İyi. Gerçekten iyi. Görünüşe bakılırsa bu sefer eli boş dönmeyeceğim."
  },
  AvgVideoCaption_98516_Content_32 = {
    Text = "Heh, galiba muhafızlar geldi."
  },
  AvgVideoCaption_98516_Content_33 = {
    Text = "Vakit doldu, veletler."
  },
  AvgVideoCaption_98516_Content_34 = {
    Text = "Beklediğimden fazlalar ama..."
  },
  AvgVideoCaption_98516_Content_35 = {
    Text = "Neyse ki ben tam da biraz çığlık dinleme havasındayım!"
  },
  AvgVideoCaption_98516_Content_36 = {
    Text = "Fazla oyalanmışız."
  },
  AvgVideoCaption_98516_Content_37 = {
    Text = "Yol tarif etsin diye birini diri tutmalıydık."
  },
  AvgVideoCaption_98516_Content_38 = {
    Text = "...Eh, boş ver. Bugün buradan diri çıkacak kimse yok. Ağırdan almaya bol bol vaktim var."
  },
  AvgVideoCaption_98516_Content_39 = {
    Text = "Hm? Şimdiden döndün mü, velet?"
  },
  AvgVideoCaption_98516_Content_4 = {
    Text = "Saklanacak başka yerleri kalmadı."
  },
  AvgVideoCaption_98516_Content_40 = {Text = "Ne buldun?"},
  AvgVideoCaption_98516_Content_41 = {
    Text = "O tarafta mı?"
  },
  AvgVideoCaption_98516_Content_42 = {
    Text = "Anlaşıldı."
  },
  AvgVideoCaption_98516_Content_43 = {
    Text = "Kurbanının unutulmasına izin vermeyeceğiz."
  },
  AvgVideoCaption_98516_Content_44 = {
    Text = "Kes gevezeliği."
  },
  AvgVideoCaption_98516_Content_45 = {
    Text = "Öldün dediysem, ölmüşsündür."
  },
  AvgVideoCaption_98516_Content_46 = {
    Text = "Bir sonraki parti senin anma törenin olacak."
  },
  AvgVideoCaption_98516_Content_47 = {
    Text = "Mutlaka kendinin bir fotoğrafını getir."
  },
  AvgVideoCaption_98516_Content_48 = {
    Text = "Lanet olsun Rox, neredesin?!"
  },
  AvgVideoCaption_98516_Content_49 = {
    Text = "Rox’un son sinyali burada kesildi..."
  },
  AvgVideoCaption_98516_Content_5 = {
    Text = "Öyle mi? Bir bak sen şu hâline, birden ne kadar da yumuşadın."
  },
  AvgVideoCaption_98516_Content_50 = {
    Text = "...Yanıt yok."
  },
  AvgVideoCaption_98516_Content_51 = {
    Text = "Ha. Artık tek başıma uçuyorum."
  },
  AvgVideoCaption_98516_Content_52 = {
    Text = "Hadi ama, “Claire.”"
  },
  AvgVideoCaption_98516_Content_53 = {
    Text = "Kendini toparlamak zorundasın..."
  },
  AvgVideoCaption_98516_Content_54 = {Text = "Ne?!"},
  AvgVideoCaption_98516_Content_55 = {
    Text = "Yeni Şafak’a küfreden kâfir!"
  },
  AvgVideoCaption_98516_Content_56 = {
    Text = "Efendimizin sunağını sen besleyeceksin!\""
  },
  AvgVideoCaption_98516_Content_57 = {
    Text = "Aptal lekeleyiciler... Rox ve Claire, öyle miydi?"
  },
  AvgVideoCaption_98516_Content_58 = {
    Text = "Etin, Ayin’imin tuvali olacak—"
  },
  AvgVideoCaption_98516_Content_59 = {
    Text = "Ruhlarınızın ta içine azap mühürleri oyacağım!"
  },
  AvgVideoCaption_98516_Content_6 = {
    Text = "Seni o bunak heriflerle ilgilenmeye yollamalıydım."
  },
  AvgVideoCaption_98516_Content_60 = {
    Text = "Gerçekten mi?"
  },
  AvgVideoCaption_98516_Content_61 = {Text = "Ne yazık."},
  AvgVideoCaption_98516_Content_62 = {
    Text = "O veletin ruhu çoktan bana geri döndü."
  },
  AvgVideoCaption_98516_Content_63 = {
    Text = "Ayrıca, onun adı Rox falan değil."
  },
  AvgVideoCaption_98516_Content_64 = {
    Text = "Ve benimki de Claire hiç değil, hele Cehennem olsun."
  },
  AvgVideoCaption_98516_Content_65 = {Text = "H-Hayır!"},
  AvgVideoCaption_98516_Content_66 = {Text = "Nasıl?!"},
  AvgVideoCaption_98516_Content_67 = {
    Text = "O güçle, neden böyle bir şey—"
  },
  AvgVideoCaption_98516_Content_68 = {
    Text = "Elbette sana istediğini vermek için."
  },
  AvgVideoCaption_98516_Content_69 = {
    Text = "Bu senin en sevdiğin şey değil mi?"
  },
  AvgVideoCaption_98516_Content_7 = {
    Text = "Ohoo, dur bakalım, “Claire,”"
  },
  AvgVideoCaption_98516_Content_70 = {
    Text = "Avının yüzündeki o umutsuzluk ifadesine bayılırsın."
  },
  AvgVideoCaption_98516_Content_71 = {
    Text = "Evet, tıpkı şu an yüzünde olan gibi."
  },
  AvgVideoCaption_98516_Content_72 = {
    Text = "AAARRRGGGHHHH!"
  },
  AvgVideoCaption_98516_Content_73 = {
    Text = "Hah, bana teşekkür etmelisin! Sevin. Bugün cömert hissediyorum."
  },
  AvgVideoCaption_98516_Content_74 = {
    Text = "Senin gibi pislikleri işkenceyle kıvrandırmak öyle arındırıcı ki."
  },
  AvgVideoCaption_98516_Content_75 = {
    Text = "Ödül olarak, sana üst düzey bir acı tattıracağım,"
  },
  AvgVideoCaption_98516_Content_76 = {
    Text = "kin ve arzu ile taşan!"
  },
  AvgVideoCaption_98516_Content_77 = {
    Text = "Bütün kemiklerini kırıp, sonra parçaların yarısını bedeninden sökeceğim."
  },
  AvgVideoCaption_98516_Content_78 = {
    Text = "O kemik kırıntılarını göz kürelerinle birlikte öğütüp, hepsini yeniden göz çukurlarına tıkacağım."
  },
  AvgVideoCaption_98516_Content_79 = {
    Text = "Derini ve etini yırtıp, açığa çıkan sinirlerini ovuşturacağım,"
  },
  AvgVideoCaption_98516_Content_8 = {
    Text = "Sadece havayı biraz yumuşatmaya çalışıyordum!"
  },
  AvgVideoCaption_98516_Content_80 = {
    Text = "ve hepsini tek hamlede söküp almak."
  },
  AvgVideoCaption_98516_Content_81 = {
    Text = "Şimdi kızgın silah namlum yaraları dağlamak ve kan akıtmayı durdurmak için mükemmel..."
  },
  AvgVideoCaption_98516_Content_82 = {
    Text = "Haha, daha kurumamanı isterim."
  },
  AvgVideoCaption_98516_Content_83 = {
    Text = "Beden sıvılarını solunum yollarına boca edeceğim,"
  },
  AvgVideoCaption_98516_Content_84 = {
    Text = "seni tam boğulmanın eşiğinde tutarak."
  },
  AvgVideoCaption_98516_Content_85 = {
    Text = "Kafatasını açıp, bilincin açık kalsın diye beynini uyaracağım."
  },
  AvgVideoCaption_98516_Content_86 = {
    Text = "Heh, uzaktan bakınca..."
  },
  AvgVideoCaption_98516_Content_87 = {
    Text = "Bu gerçek bir sanat eseri. Senin gibiler için kusursuz bir görünüm."
  },
  AvgVideoCaption_98516_Content_88 = {
    Text = "Sanırım bugünlük bu kadar yeter."
  },
  AvgVideoCaption_98516_Content_89 = {
    Text = "Sıkılmaya başladım."
  },
  AvgVideoCaption_98516_Content_9 = {
    Text = "Şunu duymayı tercih ederdim: \"Şu lağım sıçanları mı? Karanlıkta sürünmek için doğmuşlar.\" Bu daha çok bana göre."
  },
  AvgVideoCaption_98516_Content_90 = {
    Text = "Defol, çöp."
  },
  AvgVideoCaption_98516_Content_91 = {
    Text = "Şimdi... o şey nerede?"
  },
  AvgVideoCaption_98516_Content_92 = {
    Text = "Haha, işte buradasın... İsimsiz Kaos’un Putu."
  },
  AvgVideoCaption_98516_Content_93 = {
    Text = "Söylemiştim sana, sıçan. Benden saklanamazsın. Asla."
  },
  AvgVideoCaption_98516_Content_94 = {
    Text = "Elveda, Bay Rapture. Bu sefil varoluşunun bu paçavrasına veda et, pis ▼▼!"
  },
  AvgVideoCaption_98516_Content_95 = {
    Text = "Off, ne harika bir gündü."
  },
  AvgVideoCaption_98516_Content_96 = {
    Text = "Pekâlâ çocuklar. Uyku vakti bitti."
  },
  AvgVideoCaption_98516_Content_97 = {
    Text = "Uyanma vaktin geldi! Her şeyi yere kadar yakacağız!"
  },
  AvgVideoCaption_98516_Content_98 = {
    Text = "Suçlu olan son kırıntıya kadar!"
  }
})
return Text_AvgVideoCaption
